import type { MagiaCatalogo } from "./magiasSrd";

export const MAGIAS_GERADAS: MagiaCatalogo[] = [
  {"en":"Calm Emotions","nome":"Acalmar emoções","nivel":2,"escola":"Encantamento","tempo":"1 ação","alcance":"18 m","duracao":"Concentração, até 1 minuto","componentes":"V, S","concentracao":true,"ritual":false,"classes":["Bardo","Clérigo"],"teste":"Salvaguarda de Carisma","dano":"","gatilho":"","texto":"Cada Humanoide em uma Esfera de 6 m de raio centrada em um ponto que você escolher ao alcance deve ter sucesso em uma salvaguarda de Carisma ou será afetado por um dos efeitos a seguir (escolha para cada criatura): - A criatura tem Imunidade às condições Enfeitiçado e Amedrontado até a magia terminar. Se a criatura já estava Enfeitiçada ou Amedrontada, essas condições ficam suprimidas pela duração. - A criatura se torna Indiferente em relação às criaturas de sua escolha com as quais ela é Hostil. Essa indiferença termina se o alvo sofrer dano ou presenciar seus aliados sofrendo dano. Quando a magia termina, a atitude da criatura volta ao normal.","superior":""},
  {"en":"Divination","nome":"Adivinhação","nivel":4,"escola":"Adivinhação","tempo":"1 ação","alcance":"Pessoal","duracao":"Instantânea","componentes":"V, S, M (incenso que valha 25+ PO, que a magia consome)","concentracao":false,"ritual":true,"classes":["Clérigo","Druida","Mago"],"teste":"","dano":"","gatilho":"","texto":"Esta magia coloca você em contato com um deus ou com os servos de um deus. Você faz uma pergunta sobre um objetivo, evento ou atividade específicos que ocorrerão em até 7 dias. O Mestre oferece uma resposta verdadeira, que pode ser uma frase curta ou uma rima enigmática. A magia não leva em conta circunstâncias que possam mudar a resposta, como a conjuração de outras magias. Se você conjurar a magia mais de uma vez antes de terminar um Descanso Longo, há 25 por cento de chance cumulativa, para cada conjuração após a primeira, de você não obter resposta.","superior":""},
  {"en":"Aid","nome":"Ajuda","nivel":2,"escola":"Abjuração","tempo":"1 ação","alcance":"9 m","duracao":"8 horas","componentes":"V, S, M (uma tira de pano branco)","concentracao":false,"ritual":false,"classes":["Bardo","Clérigo","Druida","Paladino","Patrulheiro"],"teste":"","dano":"","gatilho":"","texto":"Escolha até três criaturas ao alcance. O máximo de Pontos de Vida e os Pontos de Vida atuais de cada alvo aumentam em 5 pela duração.","superior":"Os Pontos de Vida de cada alvo aumentam em 5 para cada nível do espaço de magia acima de 2."},
  {"en":"Alarm","nome":"Alarme","nivel":1,"escola":"Abjuração","tempo":"1 minuto","alcance":"9 m","duracao":"8 horas","componentes":"V, S, M (um sino e fio de prata)","concentracao":false,"ritual":true,"classes":["Patrulheiro","Mago"],"teste":"","dano":"","gatilho":"","texto":"Você prepara um alarme contra intrusos. Escolha uma porta, uma janela ou uma área ao alcance que não seja maior que um Cubo de 6 m. Até a magia acabar, um alarme alerta você sempre que uma criatura tocar ou entrar na área protegida. Ao conjurar a magia, você pode designar criaturas que não ativarão o alarme. Você também escolhe se o alarme é audível ou mental:\n\n**Alarme Audível.** O alarme produz o som de uma sineta por 10 segundos a até 18 m da área protegida.\n\n**Alarme Mental.** Você é alertado por um sinal mental se estiver a até 1,5 km da área protegida. Esse sinal acorda você se estiver dormindo.","superior":""},
  {"en":"Planar Ally","nome":"Aliado planar","nivel":6,"escola":"Conjuração","tempo":"1 minuto","alcance":"18 m","duracao":"Instantânea","componentes":"V, S","concentracao":false,"ritual":false,"classes":["Clérigo"],"teste":"","dano":"","gatilho":"","texto":"Você implora a uma entidade de outro mundo por ajuda. O ser deve ser conhecido por você: um deus, um príncipe demônio ou algum outro ser de poder cósmico. Essa entidade envia um Celestial, um Elemental ou um Ínfero leal a ela para ajudar você, fazendo a criatura aparecer em um espaço desocupado ao alcance. Se você souber o nome de uma criatura específica, pode pronunciar esse nome ao conjurar esta magia para solicitar essa criatura, embora você possa receber uma criatura diferente mesmo assim (escolha do Mestre). Quando a criatura aparece, ela não está sob nenhuma compulsão para se comportar de determinada maneira. Você pode pedir que ela realize um serviço em troca de pagamento, mas ela não é obrigada a fazê-lo. A tarefa solicitada pode variar de simples (nos carregue voando pelo abismo, ou nos ajude a lutar uma batalha) a complexa (espione nossos inimigos, ou nos proteja durante nossa incursão na masmorra). Você deve ser capaz de se comunicar com a criatura para negociar seus serviços. O pagamento pode assumir várias formas. Um Celestial pode exigir uma doação considerável de ouro ou itens mágicos a um templo aliado, enquanto um Ínfero pode exigir um sacrifício vivo ou um presente em tesouro. Algumas criaturas podem trocar seu serviço por uma missão realizada por você. Uma tarefa que possa ser medida em minutos exige um pagamento de 100 PO por minuto. Uma tarefa medida em horas exige 1.000 PO por hora. E uma tarefa medida em dias (até 10 dias) exige 10.000 PO por dia. O Mestre pode ajustar esses pagamentos com base nas circunstâncias em que você conjurou a magia. Se a tarefa estiver alinhada com o ethos da criatura, o pagamento pode ser reduzido à metade ou até dispensado. Tarefas sem perigo normalmente exigem apenas metade do pagamento sugerido, enquanto tarefas especialmente perigosas podem exigir um presente maior. Criaturas raramente aceitam tarefas que pareçam suicidas. Depois que a criatura completar a tarefa, ou quando a duração de serviço acordada expirar, a criatura retorna ao seu plano natal, depois de se apresentar a você se possível. Se vocês não conseguirem chegar a um acordo sobre o preço pelo serviço da criatura, ela retorna imediatamente ao seu plano natal.","superior":""},
  {"en":"Alter Self","nome":"Alterar-se","nivel":2,"escola":"Transmutação","tempo":"1 ação","alcance":"Pessoal","duracao":"Concentração, até 1 hora","componentes":"V, S","concentracao":true,"ritual":false,"classes":["Feiticeiro","Mago"],"teste":"","dano":"1d6","gatilho":"","texto":"Você altera sua forma física. Escolha uma das opções a seguir. Os efeitos dela duram pela duração, e durante esse tempo você pode realizar uma ação Magia para substituir a opção escolhida por outra. _Adaptação Aquática._ Você desenvolve guelras e membranas entre os dedos. Você pode respirar debaixo d'água e ganha um Deslocamento de Natação igual ao seu Deslocamento. _Mudar Aparência._ Você altera sua aparência. Você decide como ela será, incluindo altura, peso, traços faciais, som da voz, comprimento do cabelo, coloração e outras características distintivas. Você pode se fazer parecer um membro de outra espécie, mas nenhuma de suas estatísticas muda. Você não pode parecer uma criatura de tamanho diferente, e sua forma básica permanece a mesma; se você é bípede, por exemplo, não pode usar esta magia para se tornar quadrúpede. Pela duração, você pode realizar uma ação Magia para mudar sua aparência dessa maneira novamente. _Armas Naturais._ Você desenvolve garras (cortante), presas (perfurante), chifres (perfurante) ou cascos (contundente). Quando você usa seu Ataque Desarmado para causar dano com esse novo crescimento, ele causa 1d6 de dano do tipo indicado entre parênteses em vez do dano normal do seu Ataque Desarmado, e você usa o modificador do seu atributo de conjuração nas jogadas de ataque e de dano em vez de usar Força.","superior":""},
  {"en":"Animal Friendship","nome":"Amizade animal","nivel":1,"escola":"Encantamento","tempo":"1 ação","alcance":"9 m","duracao":"24 horas","componentes":"V, S, M (um pedaço de comida)","concentracao":false,"ritual":false,"classes":["Bardo","Druida","Patrulheiro"],"teste":"Salvaguarda de Sabedoria","dano":"","gatilho":"","texto":"Escolha como alvo uma Fera que você possa ver ao alcance. O alvo deve ter sucesso em uma salvaguarda de Sabedoria ou ficará com a condição Enfeitiçado pela duração. Se você ou um de seus aliados causar dano ao alvo, a magia termina.","superior":"Você pode escolher uma Fera adicional como alvo para cada nível do espaço de magia acima de 1."},
  {"en":"Animate Dead","nome":"Animar mortos","nivel":3,"escola":"Necromancia","tempo":"1 minuto","alcance":"3 m","duracao":"Instantânea","componentes":"V, S, M (uma gota de sangue, um pedaço de carne e uma pitada de pó de osso)","concentracao":false,"ritual":false,"classes":["Clérigo","Mago"],"teste":"","dano":"","gatilho":"","texto":"Escolha uma pilha de ossos ou o cadáver de um Humanoide Médio ou Pequeno ao alcance. O alvo se torna uma criatura Morto-vivo: um Esqueleto, se você escolheu ossos, ou um Zumbi, se escolheu um cadáver (veja \"Monstros\" para os blocos de estatísticas). Em cada um dos seus turnos, você pode usar uma ação bônus para comandar mentalmente qualquer criatura que tenha criado com esta magia, se a criatura estiver a até 18 m de você (se você controla várias criaturas, pode comandar qualquer uma delas ao mesmo tempo, dando o mesmo comando a cada uma). Você decide qual ação a criatura realizará e para onde ela se moverá no próximo turno dela, ou pode dar um comando geral, como guardar uma câmara ou um corredor. Se você não der nenhum comando, a criatura realiza a ação Esquivar e se move apenas para evitar perigo. Uma vez dada uma ordem, a criatura continua a segui-la até concluir a tarefa. A criatura fica sob seu controle por 24 horas, após as quais deixa de obedecer a qualquer comando que você tenha dado. Para manter o controle da criatura por mais 24 horas, você deve conjurar esta magia sobre ela novamente antes de o período atual de 24 horas terminar. Esse uso da magia reafirma seu controle sobre até quatro criaturas que você tenha animado com esta magia, em vez de animar uma nova criatura.","superior":"Você anima ou reafirma o controle sobre duas criaturas Morto-vivo adicionais para cada nível do espaço de magia acima de 3. Cada uma das criaturas deve vir de um cadáver ou pilha de ossos diferente."},
  {"en":"Animate Objects","nome":"Animar objetos","nivel":5,"escola":"Transmutação","tempo":"1 ação","alcance":"36 m","duracao":"Concentração, até 1 minuto","componentes":"V, S","concentracao":true,"ritual":false,"classes":["Bardo","Feiticeiro","Mago"],"teste":"","dano":"","gatilho":"","texto":"Objetos ganham vida sob seu comando. Escolha uma quantidade de objetos não mágicos ao alcance que não estejam sendo vestidos ou carregados, não estejam fixados a uma superfície e não sejam Imensos. A quantidade máxima de objetos é igual ao modificador do seu atributo de conjuração; para esse número, um alvo Médio ou menor conta como um objeto, um alvo Grande conta como dois e um alvo Enorme conta como três. Cada alvo ganha vida, desenvolve pernas e se torna um Constructo que usa o bloco de estatísticas Objeto Animado; essa criatura fica sob seu controle até a magia acabar ou até ser reduzida a 0 Pontos de Vida. Cada criatura que você cria com esta magia é aliada sua e de seus aliados. Em combate, ela compartilha a sua contagem de Iniciativa e age imediatamente após você. Até a magia acabar, você pode usar uma ação bônus para comandar mentalmente qualquer criatura que tenha criado com esta magia, se a criatura estiver a até 150 m de você (se você controla várias criaturas, pode comandar qualquer uma delas ao mesmo tempo, dando o mesmo comando a cada uma). Se você não der nenhum comando, a criatura realiza a ação Esquivar e se move apenas para evitar perigo. Quando a criatura cai a 0 Pontos de Vida, ela volta à forma de objeto, e qualquer dano restante é transferido para essa forma.","superior":"O dano de Pancada da criatura aumenta em 1d4 (Médio ou menor), 1d6 (Grande) ou 1d12 (Enorme) para cada nível do espaço de magia acima de 5."},
  {"en":"Antipathy/Sympathy","nome":"Antipatia/Simpatia","nivel":8,"escola":"Encantamento","tempo":"1 hora","alcance":"18 m","duracao":"10 dias","componentes":"V, S, M (uma mistura de vinagre e mel)","concentracao":false,"ritual":false,"classes":["Bardo","Druida","Mago"],"teste":"Salvaguarda de Sabedoria","dano":"","gatilho":"","texto":"Ao conjurar a magia, escolha se ela cria antipatia ou simpatia, e escolha como alvo uma criatura ou objeto que seja Enorme ou menor. Em seguida, especifique um tipo de criatura, como dragões vermelhos, goblins ou vampiros. Uma criatura do tipo escolhido faz uma salvaguarda de Sabedoria quando chegar a até 36 m do alvo. Sua escolha entre antipatia ou simpatia determina o que acontece com uma criatura quando ela falha nessa salvaguarda:\n\n**Antipatia**. A criatura fica com a condição Amedrontado. A criatura Amedrontada deve usar seu movimento nos turnos dela para se afastar o máximo possível do alvo, movendo-se pela rota mais segura.\n\n**Simpatia**. A criatura fica com a condição Enfeitiçado. A criatura Enfeitiçada deve usar seu movimento nos turnos dela para se aproximar o máximo possível do alvo, movendo-se pela rota mais segura. Se a criatura estiver a até 1,5 m do alvo, ela não pode se afastar voluntariamente. Se o alvo causar dano à criatura Enfeitiçada, essa criatura pode fazer uma salvaguarda de Sabedoria para encerrar o efeito, conforme descrito a seguir.\n\n**Encerrando o Efeito**. Se a criatura Amedrontada ou Enfeitiçada terminar seu turno a mais de 36 m do alvo, ela faz uma salvaguarda de Sabedoria. Em uma salvaguarda bem-sucedida, a criatura deixa de ser afetada pelo alvo. Uma criatura que tem sucesso na salvaguarda contra este efeito fica imune a ele por 1 minuto, após o qual pode ser afetada novamente.","superior":""},
  {"en":"Seeming","nome":"Aparência","nivel":5,"escola":"Ilusão","tempo":"1 ação","alcance":"9 m","duracao":"8 horas","componentes":"V, S","concentracao":false,"ritual":false,"classes":["Bardo","Feiticeiro","Mago"],"teste":"Salvaguarda de Carisma","dano":"","gatilho":"","texto":"Você dá uma aparência ilusória a cada criatura de sua escolha que você possa ver ao alcance. Um alvo involuntário pode realizar uma salvaguarda de Carisma e, se tiver sucesso, não é afetado por esta magia. Você pode dar a mesma aparência ou aparências diferentes aos alvos. A magia pode mudar a aparência do corpo e do equipamento dos alvos. Você pode fazer cada criatura parecer 30 cm mais baixa ou mais alta e parecer mais pesada ou mais leve. A nova aparência de um alvo deve ter o mesmo arranjo básico de membros que o alvo, mas a extensão da ilusão fica, de resto, a seu critério. A magia dura pela duração. As mudanças causadas por esta magia não resistem a uma inspeção física. Por exemplo, se você usar esta magia para acrescentar um chapéu à roupa de uma criatura, objetos atravessam o chapéu. Uma criatura que realize a ação Estudar para examinar um alvo pode fazer um teste de Inteligência (Investigação) contra a CD de salvaguarda da sua magia. Se tiver sucesso, ela percebe que o alvo está disfarçado.","superior":""},
  {"en":"Enhance Ability","nome":"Aprimorar habilidade","nivel":2,"escola":"Transmutação","tempo":"1 ação","alcance":"Toque","duracao":"Concentração, até 1 hora","componentes":"V, S, M (pelo ou uma pena)","concentracao":true,"ritual":false,"classes":["Bardo","Clérigo","Druida","Patrulheiro","Feiticeiro","Mago"],"teste":"","dano":"","gatilho":"","texto":"Você toca uma criatura e escolhe Força, Destreza, Inteligência, Sabedoria ou Carisma. Pela duração, o alvo tem Vantagem em testes de atributo que usem o atributo escolhido.","superior":"Você pode escolher uma criatura adicional como alvo para cada nível do espaço de magia acima de 2. Você pode escolher um atributo diferente para cada alvo."},
  {"en":"Imprisonment","nome":"Aprisionamento","nivel":9,"escola":"Abjuração","tempo":"1 minuto","alcance":"9 m","duracao":"Até ser dissipada","componentes":"V, S, M (uma estatueta do alvo que valha 5.000+ PO)","concentracao":false,"ritual":false,"classes":["Bruxo","Mago"],"teste":"Salvaguarda de Sabedoria","dano":"","gatilho":"","texto":"Você cria uma contenção mágica para prender uma criatura que você possa ver ao alcance. O alvo deve fazer uma salvaguarda de Sabedoria. Com um sucesso, o alvo não é afetado e fica imune a esta magia pelas próximas 24 horas. Com uma falha, o alvo é aprisionado. Enquanto aprisionado, o alvo não precisa respirar, comer nem beber, e não envelhece. Magias de adivinhação não conseguem localizar nem perceber o alvo aprisionado, e o alvo não pode se teletransportar.\n\nAté a magia terminar, o alvo também é afetado por um dos efeitos a seguir, à sua escolha:\n\n- **Sepultamento.** O alvo é enterrado sob a terra em um globo oco de energia mágica, grande o bastante apenas para conter o alvo. Nada pode entrar no globo nem sair dele.\n- **Acorrentamento.** Correntes firmemente fixadas no chão mantêm o alvo no lugar. O alvo tem a condição Contido e não pode ser movido por nenhum meio.\n- **Prisão Cercada.** O alvo fica preso em um semiplano protegido contra teletransporte e viagem planar. O semiplano é, à sua escolha, um labirinto, uma jaula, uma torre ou algo semelhante.\n- **Contenção Minimus.** O alvo passa a ter 2,5 cm de altura e fica preso dentro de uma gema indestrutível ou de um objeto semelhante. A luz pode atravessar a gema (permitindo que o alvo veja para fora e que outras criaturas vejam para dentro), mas nada mais pode atravessá-la por nenhum meio.\n- **Sono Profundo.** O alvo tem a condição Inconsciente e não pode ser acordado.\n\n**_Fim da Magia._** Ao conjurar a magia, especifique um gatilho que a encerrará. O gatilho pode ser tão simples ou elaborado quanto você escolher, mas o Mestre deve concordar que há grande probabilidade de ele acontecer na próxima década. O gatilho deve ser uma ação observável, como alguém fazer uma oferenda específica no templo do seu deus, salvar seu verdadeiro amor ou derrotar um monstro específico.\n\nUma magia Dissipar Magia só pode encerrar esta magia se for conjurada com um espaço de magia de nível 9, tendo como alvo a prisão ou o componente usado para criá-la.","superior":""},
  {"en":"Heat Metal","nome":"Aquecer metal","nivel":2,"escola":"Transmutação","tempo":"1 ação","alcance":"18 m","duracao":"Concentração, até 1 minuto","componentes":"V, S, M (um pedaço de ferro e uma chama)","concentracao":true,"ritual":false,"classes":["Bardo","Druida"],"teste":"Ataque de magia + Salvaguarda de Constituição","dano":"2d8 fogo","gatilho":"","texto":"Escolha um objeto de metal manufaturado, como uma arma de metal ou uma armadura de metal Pesada ou Média, que você possa ver ao alcance. Você faz o objeto brilhar em brasa. Qualquer criatura em contato físico com o objeto sofre 2d8 de dano de Fogo quando você conjura a magia. Até a magia terminar, você pode usar uma ação bônus em cada um dos seus turnos seguintes para causar esse dano novamente, se o objeto estiver ao alcance. Se uma criatura estiver segurando ou vestindo o objeto e sofrer o dano dele, ela deve ter sucesso em uma salvaguarda de Constituição ou largará o objeto, se puder. Se não largar o objeto, ela tem Desvantagem em jogadas de ataque e testes de atributo até o início do seu próximo turno.","superior":"O dano aumenta em 1d8 para cada nível do espaço de magia acima de 2."},
  {"en":"Spiritual Weapon","nome":"Arma espiritual","nivel":2,"escola":"Evocação","tempo":"1 ação bônus","alcance":"18 m","duracao":"Concentração, até 1 minuto","componentes":"V, S","concentracao":true,"ritual":false,"classes":["Clérigo"],"teste":"","dano":"1d8 energia","gatilho":"","texto":"Você cria uma força espectral flutuante que se assemelha a uma arma à sua escolha e dura pela duração. A força aparece ao alcance em um espaço à sua escolha, e você pode imediatamente fazer uma jogada de ataque de magia corpo a corpo contra uma criatura a até 1,5 m da força. Se acertar, o alvo sofre dano de energia igual a 1d8 mais o seu modificador de atributo de conjuração. Com uma ação bônus nos seus turnos seguintes, você pode mover a força até 6 m e repetir o ataque contra uma criatura a até 1,5 m dela.","superior":"O dano aumenta em 1d8 para cada nível de espaço acima de 2."},
  {"en":"Magic Weapon","nome":"Arma mágica","nivel":2,"escola":"Transmutação","tempo":"1 ação bônus","alcance":"Toque","duracao":"1 hora","componentes":"V, S","concentracao":false,"ritual":false,"classes":["Paladino","Patrulheiro","Feiticeiro","Mago"],"teste":"Ataque de magia","dano":"","gatilho":"","texto":"Você toca uma arma não mágica. Até a magia terminar, essa arma se torna uma arma mágica com bônus de +1 em jogadas de ataque e jogadas de dano. A magia termina antecipadamente se você a conjurar novamente.","superior":"O bônus aumenta para +2 com um espaço de magia de nível 3–5. O bônus aumenta para +3 com um espaço de magia de nível 6 ou superior."},
  {"en":"Mage Armor","nome":"Armadura arcana","nivel":1,"escola":"Abjuração","tempo":"1 ação","alcance":"Toque","duracao":"8 horas","componentes":"V, S, M (um pedaço de couro curtido)","concentracao":false,"ritual":false,"classes":["Feiticeiro","Mago"],"teste":"","dano":"","gatilho":"","texto":"Você toca uma criatura disposta que não esteja usando armadura. Até a magia terminar, a CA base do alvo passa a ser 13 mais o modificador de Destreza dele. A magia termina antecipadamente se o alvo vestir uma armadura.","superior":""},
  {"en":"Knock","nome":"Arrombar","nivel":2,"escola":"Transmutação","tempo":"1 ação","alcance":"18 m","duracao":"Instantânea","componentes":"V","concentracao":false,"ritual":false,"classes":["Bardo","Feiticeiro","Mago"],"teste":"","dano":"","gatilho":"","texto":"Um alvo mantido fechado por uma fechadura comum, ou que esteja emperrado ou travado por barras, é destrancado, desemperrado ou destravado. Se o objeto tiver várias fechaduras, apenas uma delas é destrancada. Se o alvo estiver mantido fechado por Tranca Arcana, essa magia é suprimida por 10 minutos, período durante o qual o alvo pode ser aberto e fechado. Quando você conjura a magia, uma batida alta, audível a até 90 m de distância, emana do alvo.","superior":""},
  {"en":"Druidcraft","nome":"Arte druídica","nivel":0,"escola":"Transmutação","tempo":"1 ação","alcance":"9 m","duracao":"Instantânea","componentes":"V, S","concentracao":false,"ritual":false,"classes":["Druida"],"teste":"","dano":"","gatilho":"","texto":"Sussurrando aos espíritos da natureza, você cria um dos efeitos a seguir ao alcance.\n\n- ***Sensor do Clima.*** Você cria um efeito sensorial Miúdo e inofensivo que prevê como será o clima no seu local nas próximas 24 horas. O efeito pode se manifestar como um orbe dourado para céu limpo, uma nuvem para chuva, flocos de neve caindo para neve, e assim por diante. Esse efeito dura 1 rodada.\n- ***Florescer.*** Você faz instantaneamente uma flor desabrochar, uma vagem de semente se abrir ou um botão de folha brotar.\n- ***Efeito Sensorial.*** Você cria um efeito sensorial inofensivo, como folhas caindo, fadas espectrais dançando, uma brisa suave, o som de um animal ou o odor tênue de gambá. O efeito deve caber em um Cubo de 1,5 m.\n- ***Brincar com Fogo.*** Você acende ou apaga uma vela, uma tocha ou uma fogueira.","superior":""},
  {"en":"Phantasmal Killer","nome":"Assassino fantasmagórico","nivel":4,"escola":"Ilusão","tempo":"1 ação","alcance":"36 m","duracao":"Concentração, até 1 minuto","componentes":"V, S","concentracao":true,"ritual":false,"classes":["Bardo","Mago"],"teste":"Ataque de magia + Salvaguarda de Sabedoria","dano":"4d10 psíquico","gatilho":"","texto":"Você acessa os pesadelos de uma criatura que você possa ver ao alcance e cria uma ilusão dos seus medos mais profundos, visível apenas para essa criatura. O alvo faz uma salvaguarda de Sabedoria. Se falhar, o alvo sofre 4d10 de dano psíquico e tem Desvantagem em testes de atributo e jogadas de ataque pela duração. Se tiver sucesso, o alvo sofre metade do dano, e a magia termina. Pela duração, o alvo faz uma salvaguarda de Sabedoria no final de cada um dos seus turnos. Se falhar, sofre o dano psíquico novamente. Se tiver sucesso, a magia termina.","superior":"O dano aumenta em 1d10 para cada nível do espaço de magia acima de 4."},
  {"en":"Augury","nome":"Augúrio","nivel":2,"escola":"Adivinhação","tempo":"1 minuto","alcance":"Pessoal","duracao":"Instantânea","componentes":"V, S, M (gravetos, ossos, cartas ou outros símbolos divinatórios especialmente marcados que valham 25+ PO)","concentracao":false,"ritual":true,"classes":["Clérigo","Druida","Mago"],"teste":"","dano":"","gatilho":"","texto":"Você recebe um presságio de uma entidade de outro mundo sobre os resultados de um curso de ação que você planeja tomar nos próximos 30 minutos. O Mestre escolhe o presságio na tabela Presságios. Tabela: Presságios | Presságio | Para Resultados Que Serão... | |--------------|----------------------------| | Bonança | Bons | | Desgraça | Ruins | | Bonança e desgraça | Bons e ruins | | Indiferença | Nem bons nem ruins | A magia não leva em conta circunstâncias, como outras magias, que possam mudar os resultados. Se você conjurar a magia mais de uma vez antes de terminar um Descanso Longo, há uma chance cumulativa de 25 por cento, para cada conjuração após a primeira, de você não obter resposta.","superior":""},
  {"en":"Enlarge/Reduce","nome":"Aumentar/Reduzir","nivel":2,"escola":"Transmutação","tempo":"1 ação","alcance":"9 m","duracao":"Concentração, até 1 minuto","componentes":"V, S, M (uma pitada de ferro em pó)","concentracao":true,"ritual":false,"classes":["Bardo","Druida","Feiticeiro","Mago"],"teste":"Salvaguarda de Constituição","dano":"","gatilho":"","texto":"Pela duração, a magia aumenta ou reduz uma criatura ou um objeto que você possa ver ao alcance (veja o efeito escolhido abaixo). Um objeto alvo não pode estar sendo vestido nem carregado. Se o alvo for uma criatura involuntária, ela pode fazer uma salvaguarda de Constituição. Se tiver sucesso, a magia não tem efeito. Tudo o que a criatura alvo estiver vestindo e carregando muda de tamanho com ela. Qualquer item que ela largue volta imediatamente ao tamanho normal. Uma arma arremessada ou uma munição volta ao tamanho normal imediatamente depois de acertar ou errar um alvo.\n\n**_Ampliar._** O tamanho do alvo aumenta em uma categoria, de Médio para Grande, por exemplo. O alvo também tem Vantagem em testes de Força e salvaguardas de Força. Os ataques do alvo com suas armas ampliadas ou Ataques Desarmados causam 1d4 de dano extra em um acerto.\n\n**_Reduzir._** O tamanho do alvo diminui em uma categoria, de Médio para Pequeno, por exemplo. O alvo também tem Desvantagem em testes de Força e salvaguardas de Força. Os ataques do alvo com suas armas reduzidas ou Ataques Desarmados causam 1d4 a menos de dano em um acerto (isso não pode reduzir o dano abaixo de 1).","superior":""},
  {"en":"Aura of Life","nome":"Aura de vida","nivel":4,"escola":"Abjuração","tempo":"1 ação","alcance":"Pessoal","duracao":"Concentração, até 10 minutos","componentes":"V","concentracao":true,"ritual":false,"classes":["Clérigo","Paladino"],"teste":"","dano":"","gatilho":"","texto":"Uma aura irradia de você em uma Emanação de 9 m pela duração. Enquanto estiverem na aura, você e seus aliados têm Resistência a dano necrótico, e seus máximos de Pontos de Vida não podem ser reduzidos. Se um aliado com 0 Pontos de Vida começar o turno dele na aura, esse aliado recupera 1 Ponto de Vida.","superior":""},
  {"en":"Arcanist's Magic Aura","nome":"Aura mágica do arcanista","nivel":2,"escola":"Ilusão","tempo":"1 ação","alcance":"Toque","duracao":"24 horas","componentes":"V, S, M (um pequeno quadrado de seda)","concentracao":false,"ritual":false,"classes":["Mago"],"teste":"","dano":"","gatilho":"","texto":"Com um toque, você coloca uma ilusão sobre uma criatura disposta ou sobre um objeto que não esteja sendo vestido ou carregado. Uma criatura recebe o efeito Máscara abaixo, e um objeto recebe o efeito Aura Falsa abaixo. O efeito dura pela duração. Se você conjurar a magia sobre o mesmo alvo todos os dias durante 30 dias, a ilusão dura até ser dissipada.\n\n**Máscara (Criatura).** Escolha um tipo de criatura diferente do tipo real do alvo. Magias e outros efeitos mágicos tratam o alvo como se ele fosse uma criatura do tipo escolhido.\n\n**Aura Falsa (Objeto).** Você muda a maneira como o alvo aparece para magias e efeitos mágicos que detectam auras mágicas, como Detectar Magia. Você pode fazer um objeto não mágico parecer mágico, fazer um item mágico parecer não mágico ou mudar a aura do objeto para que pareça pertencer a uma escola de magia que você escolher.","superior":""},
  {"en":"Holy Aura","nome":"Aura sagrada","nivel":8,"escola":"Abjuração","tempo":"1 ação","alcance":"Pessoal","duracao":"Concentração, até 1 minuto","componentes":"V, S, M (um relicário que valha 1.000+ PO)","concentracao":true,"ritual":false,"classes":["Clérigo"],"teste":"Ataque de magia","dano":"","gatilho":"","texto":"Pela duração, você emite uma aura em uma Emanação de 9 m. Enquanto estiverem na aura, criaturas à sua escolha têm Vantagem em todas as salvaguardas, e outras criaturas têm Desvantagem em jogadas de ataque contra elas. Além disso, quando um Ínfero ou um Morto-vivo acertar uma criatura afetada com uma jogada de ataque corpo a corpo, o atacante deve ter sucesso em uma salvaguarda de Constituição ou ficará com a condição Cego até o final do seu próximo turno.","superior":""},
  {"en":"Banishment","nome":"Banimento","nivel":4,"escola":"Abjuração","tempo":"1 ação","alcance":"9 m","duracao":"Concentração, até 1 minuto","componentes":"V, S, M (um pentáculo)","concentracao":true,"ritual":false,"classes":["Clérigo","Paladino","Feiticeiro","Bruxo","Mago"],"teste":"Salvaguarda de Carisma","dano":"","gatilho":"","texto":"Uma criatura que você possa ver ao alcance deve ter sucesso em uma salvaguarda de Carisma ou será transportada para um semiplano inofensivo pela duração. Enquanto estiver lá, o alvo tem a condição Incapacitado. Quando a magia termina, o alvo reaparece no espaço que deixou ou, se esse espaço estiver ocupado, no espaço desocupado mais próximo. Se o alvo for uma Aberração, um Celestial, um Elemental, um Feérico ou um Ínfero, ele não retorna se a magia durar 1 minuto. Em vez disso, o alvo é transportado para um local aleatório em um plano (à escolha do Mestre) associado ao seu tipo de criatura.","superior":"Você pode escolher uma criatura adicional como alvo para cada nível do espaço de magia acima de 4."},
  {"en":"Heroes' Feast","nome":"Banquete de heróis","nivel":6,"escola":"Conjuração","tempo":"1 minuto","alcance":"Pessoal","duracao":"Instantânea","componentes":"V, S, M (uma tigela incrustada de gemas que valha 1.000+ PO, que a magia consome)","concentracao":false,"ritual":false,"classes":["Bardo","Clérigo","Druida"],"teste":"","dano":"2d10 veneno","gatilho":"","texto":"Você conjura um banquete que surge sobre uma superfície em um Cubo de 3 m desocupado ao seu lado. O banquete leva 1 hora para ser consumido e desaparece ao final desse tempo, e os efeitos benéficos só se iniciam depois dessa hora. Até doze criaturas podem participar do banquete. Uma criatura que participar recebe vários benefícios, que duram 24 horas. A criatura tem Resistência a dano de Veneno e Imunidade às condições Amedrontado e Envenenado. Seu máximo de Pontos de Vida também aumenta em 2d10, e ela recebe o mesmo número de Pontos de Vida.","superior":""},
  {"en":"Blade Barrier","nome":"Barreira de lâminas","nivel":6,"escola":"Evocação","tempo":"1 ação","alcance":"27 m","duracao":"Concentração, até 10 minutos","componentes":"V, S","concentracao":true,"ritual":false,"classes":["Clérigo"],"teste":"Salvaguarda de Destreza","dano":"6d10 energia","gatilho":"","texto":"Você cria uma muralha de lâminas giratórias feitas de energia mágica. A muralha aparece ao alcance e dura pela duração. Você cria uma muralha reta de até 30 m de comprimento, 6 m de altura e 1,5 m de espessura, ou uma muralha em anel de até 18 m de diâmetro, 6 m de altura e 1,5 m de espessura. A muralha fornece Cobertura de Três Quartos, e o espaço dela é Terreno Difícil. Qualquer criatura no espaço da muralha faz uma salvaguarda de Destreza, sofrendo 6d10 de dano de energia em uma falha ou metade desse dano em um sucesso. Uma criatura também faz essa salvaguarda se entrar no espaço da muralha ou terminar o turno dela ali. Uma criatura faz essa salvaguarda apenas uma vez por turno.","superior":""},
  {"en":"Befuddlement","nome":"Befuddlement","nivel":8,"escola":"Encantamento","tempo":"1 ação","alcance":"45 m","duracao":"Instantânea","componentes":"V, S, M (um chaveiro sem chaves)","concentracao":false,"ritual":false,"classes":["Bardo","Druida","Bruxo","Mago"],"teste":"Salvaguarda de Inteligência","dano":"10d12 psíquico","gatilho":"","texto":"Você explode a mente de uma criatura que você possa ver ao alcance. O alvo faz uma salvaguarda de Inteligência. Em uma falha, o alvo sofre 10d12 de dano psíquico e não pode conjurar magias nem realizar a ação Magia. No final de cada período de 30 dias, o alvo repete a salvaguarda, encerrando o efeito em um sucesso. O efeito também pode ser encerrado pelas magias Restauração Maior, Cura ou Desejo. Em uma salvaguarda bem-sucedida, o alvo sofre apenas metade do dano.","superior":""},
  {"en":"Bless","nome":"Bênção","nivel":1,"escola":"Encantamento","tempo":"1 ação","alcance":"9 m","duracao":"Concentração, até 1 minuto","componentes":"V, S, M (um Símbolo Sagrado que valha 5+ PO)","concentracao":true,"ritual":false,"classes":["Clérigo","Paladino"],"teste":"Ataque de magia","dano":"1d4","gatilho":"","texto":"Você abençoa até três criaturas ao alcance. Sempre que um alvo fizer uma jogada de ataque ou uma salvaguarda antes de a magia acabar, o alvo soma 1d4 à jogada de ataque ou à salvaguarda.","superior":"Você pode escolher uma criatura adicional como alvo para cada nível do espaço de magia acima de 1."},
  {"en":"Magic Mouth","nome":"Boca mágica","nivel":2,"escola":"Ilusão","tempo":"1 minuto","alcance":"9 m","duracao":"Até ser dissipada","componentes":"V, S, M (pó de jade que valha 10+ PO, que a magia consome)","concentracao":false,"ritual":true,"classes":["Bardo","Mago"],"teste":"","dano":"","gatilho":"","texto":"Você implanta uma mensagem em um objeto ao alcance, uma mensagem que é pronunciada quando uma condição de gatilho é cumprida. Escolha um objeto que você possa ver e que não esteja sendo vestido nem carregado por outra criatura. Depois, diga a mensagem, que deve ter 25 palavras ou menos, embora possa ser entregue ao longo de até 10 minutos. Por fim, determine a circunstância que fará a magia entregar sua mensagem. Quando esse gatilho ocorrer, uma boca mágica surge no objeto e recita a mensagem com a sua voz e no mesmo volume em que você falou. Se o objeto escolhido tiver uma boca ou algo que pareça uma boca (por exemplo, a boca de uma estátua), a boca mágica surge ali, de modo que as palavras pareçam vir da boca do objeto. Ao conjurar esta magia, você pode fazê-la terminar depois de entregar a mensagem, ou ela pode permanecer e repetir a mensagem sempre que o gatilho ocorrer. O gatilho pode ser tão geral ou detalhado quanto você quiser, embora deva se basear em condições visuais ou sonoras que ocorram a até 9 m do objeto. Por exemplo, você poderia instruir a boca a falar quando qualquer criatura se mover a até 9 m do objeto ou quando um sino de prata tocar a até 9 m dele.","superior":""},
  {"en":"Fireball","nome":"Bola de fogo","nivel":3,"escola":"Evocação","tempo":"1 ação","alcance":"45 m","duracao":"Instantânea","componentes":"V, S, M (uma bola de guano de morcego e enxofre)","concentracao":false,"ritual":false,"classes":["Feiticeiro","Mago"],"teste":"Salvaguarda de Destreza","dano":"8d6 fogo","gatilho":"","texto":"Um clarão brilhante parte de você até um ponto que você escolher ao alcance e então floresce, com um rugido baixo, em uma explosão flamejante. Cada criatura em uma Esfera de 6 m de raio centrada nesse ponto faz uma salvaguarda de Destreza, sofrendo 8d6 de dano de fogo se falhar, ou metade desse dano se tiver sucesso. Objetos inflamáveis na área que não estejam sendo vestidos nem carregados começam a queimar.","superior":"O dano aumenta em 1d6 para cada nível do espaço de magia acima de 3."},
  {"en":"Delayed Blast Fireball","nome":"Bola de fogo controlada","nivel":7,"escola":"Evocação","tempo":"1 ação","alcance":"45 m","duracao":"Concentração, até 1 minuto","componentes":"V, S, M (uma bola de guano de morcego e enxofre)","concentracao":true,"ritual":false,"classes":["Feiticeiro","Mago"],"teste":"Salvaguarda de Destreza","dano":"12d6 fogo","gatilho":"","texto":"Um feixe de luz amarela surge de você e então se condensa em um ponto escolhido ao alcance como uma conta brilhante pela duração. Quando a magia termina, a conta explode, e cada criatura em uma Esfera de 6 m de raio centrada nesse ponto faz uma salvaguarda de Destreza. Uma criatura sofre dano de fogo igual ao dano total acumulado se falhar na salvaguarda, ou metade desse dano se tiver sucesso. O dano base da magia é 12d6, e o dano aumenta em 1d6 sempre que seu turno termina e a magia não terminou. Se uma criatura tocar a conta brilhante antes de a magia terminar, ela faz uma salvaguarda de Destreza. Se falhar, a magia termina, fazendo a conta explodir. Se tiver sucesso, a criatura pode arremessar a conta até 12 m. Se a conta arremessada entrar no espaço de uma criatura ou colidir com um objeto sólido, a magia termina, e a conta explode. Quando a conta explode, objetos inflamáveis na explosão que não estejam sendo vestidos nem carregados começam a queimar.","superior":"O dano base aumenta em 1d6 para cada nível do espaço de magia acima de 7."},
  {"en":"Blur","nome":"Borrão","nivel":2,"escola":"Ilusão","tempo":"1 ação","alcance":"Pessoal","duracao":"Concentração, até 1 minuto","componentes":"V","concentracao":true,"ritual":false,"classes":["Feiticeiro","Mago"],"teste":"Ataque de magia","dano":"","gatilho":"","texto":"Seu corpo fica borrado. Pela duração, qualquer criatura tem Desvantagem nas jogadas de ataque contra você. Um atacante é imune a esse efeito se perceber você com Visão às Cegas ou Visão Verdadeira.","superior":""},
  {"en":"Tiny Hut","nome":"Cabana minúscula","nivel":3,"escola":"Evocação","tempo":"1 minuto","alcance":"Pessoal","duracao":"8 horas","componentes":"V, S, M (uma conta de cristal)","concentracao":false,"ritual":true,"classes":["Bardo","Mago"],"teste":"","dano":"","gatilho":"","texto":"Uma Emanação de 3 m surge ao seu redor e permanece estacionária pela duração. A magia falha quando você a conjura se a Emanação não for grande o bastante para envolver completamente todas as criaturas em sua área. Criaturas e objetos dentro da Emanação quando você conjura a magia podem atravessá-la livremente. Todas as outras criaturas e objetos são impedidos de atravessá-la. Magias de nível 3 ou inferior não podem ser conjuradas através dela, e os efeitos dessas magias não podem se estender para dentro dela. A atmosfera dentro da Emanação é confortável e seca, independentemente do clima do lado de fora. Até a magia terminar, você pode ordenar que o interior tenha Penumbra ou Escuridão (não requer ação). A Emanação é opaca vista de fora e da cor que você escolher, mas é transparente vista de dentro. A magia termina antecipadamente se você sair da Emanação ou se conjurá-la novamente.","superior":""},
  {"en":"Wind Walk","nome":"Caminhar no vento","nivel":6,"escola":"Transmutação","tempo":"1 minuto","alcance":"9 m","duracao":"8 horas","componentes":"V, S, M (uma vela)","concentracao":false,"ritual":false,"classes":["Druida"],"teste":"","dano":"","gatilho":"","texto":"Você e até dez criaturas voluntárias à sua escolha ao alcance assumem formas gasosas pela duração, aparecendo como fiapos de nuvem. Enquanto estiver nessa forma de nuvem, um alvo tem Deslocamento de Voo de 90 m e pode pairar; tem Imunidade à condição Caído; e tem Resistência a dano contundente, perfurante e cortante. As únicas ações que um alvo pode realizar nessa forma são a ação Disparada ou uma ação Magia para começar a reverter à sua forma normal. Reverter leva 1 minuto, durante o qual o alvo tem a condição Atordoado. Até a magia terminar, o alvo pode voltar à forma de nuvem, o que também requer uma ação Magia seguida de uma transformação de 1 minuto. Se um alvo estiver em forma de nuvem e voando quando o efeito terminar, ele desce 18 m por rodada durante 1 minuto até pousar, o que faz com segurança. Se não conseguir pousar após 1 minuto, ele cai a distância restante.","superior":""},
  {"en":"Water Walk","nome":"Caminhar sobre as águas","nivel":3,"escola":"Transmutação","tempo":"1 ação","alcance":"9 m","duracao":"1 hora","componentes":"V, S, M (um pedaço de cortiça)","concentracao":false,"ritual":true,"classes":["Clérigo","Druida","Patrulheiro","Feiticeiro"],"teste":"","dano":"","gatilho":"","texto":"Esta magia concede a capacidade de se mover sobre qualquer superfície líquida, como água, ácido, lama, neve, areia movediça ou lava, como se fosse solo sólido inofensivo (criaturas que atravessem lava derretida ainda podem sofrer dano pelo calor). Até dez criaturas voluntárias à sua escolha ao alcance ganham essa capacidade pela duração. Um alvo afetado deve gastar uma ação bônus para passar da superfície do líquido para dentro do líquido e vice-versa, mas, se o alvo cair no líquido, ele atravessa a superfície e vai para o líquido abaixo.","superior":""},
  {"en":"Antimagic Field","nome":"Campo antimagia","nivel":8,"escola":"Abjuração","tempo":"1 ação","alcance":"Pessoal","duracao":"Concentração, até 1 hora","componentes":"V, S, M (limalha de ferro)","concentracao":true,"ritual":false,"classes":["Clérigo","Mago"],"teste":"","dano":"","gatilho":"","texto":"Uma aura de antimagia envolve você em uma Emanação de 3 m. Ninguém pode conjurar magias, realizar ações Magia ou criar outros efeitos mágicos dentro da aura, e essas coisas não podem ter como alvo nem afetar de outra forma nada dentro dela. As propriedades mágicas de itens mágicos não funcionam dentro da aura nem em qualquer coisa dentro dela. Áreas de efeito criadas por magias ou outra magia não podem se estender para dentro da aura, e ninguém pode se teletransportar para dentro ou para fora dela nem usar viagem planar ali. Portais se fecham temporariamente enquanto estiverem na aura. Magias em andamento, exceto as conjuradas por um Artefato ou por uma divindade, são suprimidas na área. Enquanto um efeito está suprimido, ele não funciona, mas o tempo que passa suprimido conta contra a duração dele.","superior":""},
  {"en":"Faithful Hound","nome":"Cão fiel","nivel":4,"escola":"Conjuração","tempo":"1 ação","alcance":"9 m","duracao":"8 horas","componentes":"V, S, M (um apito de prata)","concentracao":false,"ritual":false,"classes":["Mago"],"teste":"Salvaguarda de Destreza","dano":"4d8 energia","gatilho":"","texto":"Você conjura um cão de guarda fantasma em um espaço desocupado que você possa ver ao alcance. O cão permanece pela duração ou até vocês dois ficarem a mais de 90 m um do outro. Ninguém além de você pode ver o cão, e ele é intangível e invulnerável. Quando uma criatura Pequena ou maior chega a até 9 m dele sem antes dizer a senha que você especificou ao conjurar esta magia, o cão começa a latir alto. O cão tem Visão Verdadeira com alcance de 9 m. No início de cada um dos seus turnos, o cão tenta morder um inimigo a até 1,5 m dele. Esse inimigo deve ter sucesso em uma salvaguarda de Destreza ou sofrerá 4d8 de dano de energia. Nos seus turnos seguintes, você pode usar uma ação Magia para mover o cão até 9 m.","superior":""},
  {"en":"Antilife Shell","nome":"Carapaça antivida","nivel":5,"escola":"Abjuração","tempo":"1 ação","alcance":"Pessoal","duracao":"Concentração, até 1 hora","componentes":"V, S","concentracao":true,"ritual":false,"classes":["Druida"],"teste":"","dano":"","gatilho":"","texto":"Uma aura se estende a partir de você em uma Emanação de 3 m pela duração. A aura impede que criaturas que não sejam Constructos ou Mortos-vivos passem ou alcancem através dela. Uma criatura afetada pode conjurar magias ou fazer ataques com armas à Distância ou com Alcance através da barreira. Se você se mover de modo que uma criatura afetada seja forçada a atravessar a barreira, a magia termina.","superior":""},
  {"en":"Flesh to Stone","nome":"Carne para pedra","nivel":6,"escola":"Transmutação","tempo":"1 ação","alcance":"18 m","duracao":"Concentração, até 1 minuto","componentes":"V, S, M (uma pena de cocatriz)","concentracao":true,"ritual":false,"classes":["Druida","Feiticeiro","Mago"],"teste":"Salvaguarda de Constituição","dano":"","gatilho":"","texto":"Você tenta transformar em pedra uma criatura que você possa ver ao alcance. O alvo faz uma salvaguarda de Constituição. Se falhar, ele fica com a condição Contido pela duração. Se tiver sucesso, seu Deslocamento é 0 até o início do seu próximo turno. Constructos têm sucesso automático na salvaguarda. Um alvo Contido faz outra salvaguarda de Constituição no final de cada turno dele. Se tiver sucesso contra esta magia três vezes, a magia termina. Se falhar três vezes, ele é transformado em pedra e fica com a condição Petrificado pela duração. Os sucessos e as falhas não precisam ser consecutivos; contabilize ambos até o alvo acumular três de um tipo. Se você mantiver sua Concentração nesta magia durante toda a duração possível, o alvo fica Petrificado até a condição ser encerrada por Restauração Maior ou magia semelhante.","superior":""},
  {"en":"Enthrall","nome":"Cativar","nivel":2,"escola":"Encantamento","tempo":"1 ação","alcance":"18 m","duracao":"Concentração, até 1 minuto","componentes":"V, S","concentracao":true,"ritual":false,"classes":["Bardo","Bruxo"],"teste":"Salvaguarda de Sabedoria","dano":"","gatilho":"","texto":"Você tece uma sequência de palavras distrativas, fazendo criaturas à sua escolha que você possa ver ao alcance realizarem uma salvaguarda de Sabedoria. Qualquer criatura que você ou seus companheiros estejam combatendo tem sucesso automático nessa salvaguarda. Se falhar, o alvo sofre uma penalidade de −10 em testes de Sabedoria (Percepção) e na Percepção Passiva até a magia acabar.","superior":""},
  {"en":"Blindness/Deafness","nome":"Cegueira/Surdez","nivel":2,"escola":"Transmutação","tempo":"1 ação","alcance":"36 m","duracao":"1 minuto","componentes":"V","concentracao":false,"ritual":false,"classes":["Bardo","Clérigo","Feiticeiro","Mago"],"teste":"Salvaguarda de Constituição","dano":"","gatilho":"","texto":"Uma criatura que você possa ver ao alcance deve ter sucesso em uma salvaguarda de Constituição, ou ficará com a condição Cego ou Surdo (à sua escolha) pela duração. No final de cada turno dela, o alvo repete a salvaguarda, encerrando a magia sobre si mesmo em um sucesso.","superior":"Você pode escolher uma criatura adicional como alvo para cada nível do espaço de magia acima de 2."},
  {"en":"Continual Flame","nome":"Chama contínua","nivel":2,"escola":"Evocação","tempo":"1 ação","alcance":"Toque","duracao":"Até ser dissipada","componentes":"V, S, M (pó de rubi que valha 50+ PO, que a magia consome)","concentracao":false,"ritual":false,"classes":["Clérigo","Druida","Mago"],"teste":"","dano":"","gatilho":"","texto":"Uma chama surge de um objeto que você toca. O efeito emite Luz Plena em um raio de 6 m e Penumbra por mais 6 m. Parece uma chama comum, mas não produz calor e não consome combustível. A chama pode ser coberta ou escondida, mas não sufocada nem apagada.","superior":""},
  {"en":"Sacred Flame","nome":"Chama sagrada","nivel":0,"escola":"Evocação","tempo":"1 ação","alcance":"18 m","duracao":"Instantânea","componentes":"V, S","concentracao":false,"ritual":false,"classes":["Clérigo"],"teste":"Salvaguarda de Destreza","dano":"1d8 radiante","gatilho":"","texto":"Uma radiância semelhante a chamas desce sobre uma criatura que você possa ver ao alcance. O alvo deve ter sucesso em uma salvaguarda de Destreza ou sofrerá 1d8 de dano radiante. O alvo não recebe benefício de Cobertura Parcial nem de Cobertura de Três Quartos nesta salvaguarda.","superior":"O dano aumenta em 1d8 quando você alcança os níveis 5 (2d8), 11 (3d8) e 17 (4d8)."},
  {"en":"Meteor Swarm","nome":"Chuva de meteoros","nivel":9,"escola":"Evocação","tempo":"1 ação","alcance":"1,5 km","duracao":"Instantânea","componentes":"V, S","concentracao":false,"ritual":false,"classes":["Feiticeiro","Mago"],"teste":"Salvaguarda de Destreza","dano":"20d6 fogo contundente","gatilho":"","texto":"Orbes flamejantes de fogo despencam no chão em quatro pontos diferentes que você possa ver ao alcance. Cada criatura em uma Esfera de 12 m de raio centrada em cada um desses pontos faz uma salvaguarda de Destreza. Uma criatura sofre 20d6 de dano de fogo e 20d6 de dano contundente se falhar na salvaguarda, ou metade desse dano se tiver sucesso. Uma criatura na área de mais de uma Esfera flamejante é afetada apenas uma vez. Um objeto não mágico que não esteja sendo vestido ou carregado também sofre o dano se estiver na área da magia, e o objeto começa a queimar se for inflamável.","superior":""},
  {"en":"Circle of Death","nome":"Círculo da morte","nivel":6,"escola":"Necromancia","tempo":"1 ação","alcance":"45 m","duracao":"Instantânea","componentes":"V, S, M (o pó de uma pérola negra esmagada que valha 500+ PO)","concentracao":false,"ritual":false,"classes":["Feiticeiro","Bruxo","Mago"],"teste":"Salvaguarda de Constituição","dano":"8d8 necrótico","gatilho":"","texto":"Energia negativa se propaga em uma Esfera de 18 m de raio a partir de um ponto que você escolher ao alcance. Cada criatura nessa área faz uma salvaguarda de Constituição, sofrendo 8d8 de dano necrótico se falhar ou metade desse dano se tiver sucesso.","superior":"O dano aumenta em 2d8 para cada nível do espaço de magia acima de 6."},
  {"en":"Teleportation Circle","nome":"Círculo de teletransporte","nivel":5,"escola":"Conjuração","tempo":"1 minuto","alcance":"3 m","duracao":"1 rodada","componentes":"V, M (tintas raras que valham 50+ PO, que a magia consome)","concentracao":false,"ritual":false,"classes":["Bardo","Feiticeiro","Bruxo","Mago"],"teste":"","dano":"","gatilho":"","texto":"Ao conjurar a magia, você desenha no chão um círculo de 1,5 m de raio inscrito com sigilos que ligam a sua localização a um círculo de teleporte permanente à sua escolha, cuja sequência de sigilos você conheça e que esteja no mesmo plano de existência que você. Um portal cintilante se abre dentro do círculo que você desenhou e permanece aberto até o final do seu próximo turno. Qualquer criatura que entre no portal aparece instantaneamente a até 1,5 m do círculo de destino ou no espaço desocupado mais próximo, se esse espaço estiver ocupado. Muitos templos importantes, sedes de guildas e outros lugares relevantes têm círculos de teleporte permanentes. Cada círculo inclui uma sequência de sigilos única, uma cadeia de runas dispostas em um padrão específico. Quando você ganha pela primeira vez a capacidade de conjurar esta magia, aprende as sequências de sigilos de dois destinos no Plano Material, determinados pelo Mestre. Você pode aprender outras sequências de sigilos durante suas aventuras. Você pode memorizar uma nova sequência de sigilos depois de estudá-la por 1 minuto. Você pode criar um círculo de teleporte permanente conjurando esta magia no mesmo local todos os dias por 365 dias.","superior":""},
  {"en":"Magic Circle","nome":"Círculo mágico","nivel":3,"escola":"Abjuração","tempo":"1 minuto","alcance":"3 m","duracao":"1 hora","componentes":"V, S, M (sal e prata em pó que valham 100+ PO, que a magia consome)","concentracao":false,"ritual":false,"classes":["Clérigo","Paladino","Bruxo","Mago"],"teste":"Ataque de magia + Salvaguarda de Carisma","dano":"","gatilho":"","texto":"Você cria um Cilindro de energia mágica de 3 m de raio e 6 m de altura, centrado em um ponto no chão que você possa ver ao alcance. Runas brilhantes surgem onde o Cilindro intercepta o piso ou outra superfície. Escolha um ou mais dos seguintes tipos de criatura: Celestiais, Elementais, Feéricos, Ínferos ou Mortos-vivos. O círculo afeta uma criatura do tipo escolhido das seguintes formas:\n\n- A criatura não pode entrar voluntariamente no Cilindro por meios não mágicos. Se a criatura tentar usar teletransporte ou viagem interplanar para isso, ela deve primeiro ter sucesso em uma salvaguarda de Carisma.\n- A criatura tem Desvantagem em jogadas de ataque contra alvos dentro do Cilindro.\n- Alvos dentro do Cilindro não podem ser possuídos pela criatura nem receber dela a condição Enfeitiçado ou Amedrontado. Cada vez que conjurar esta magia, você pode fazer sua magia operar no sentido inverso, impedindo que uma criatura do tipo especificado saia do Cilindro e protegendo alvos fora dele.","superior":"A duração aumenta em 1 hora para cada nível do espaço de magia acima de 3."},
  {"en":"Clairvoyance","nome":"Clarividência","nivel":3,"escola":"Adivinhação","tempo":"1 minuto","alcance":"1,5 km","duracao":"Concentração, até 10 minutos","componentes":"V, S, M (um foco que valha 100+ PO, seja uma trompa cravejada de joias para ouvir, seja um olho de vidro para ver)","concentracao":true,"ritual":false,"classes":["Bardo","Clérigo","Feiticeiro","Mago"],"teste":"","dano":"","gatilho":"","texto":"Você cria um sensor Invisível ao alcance em um local que lhe seja familiar (um lugar que você já visitou ou viu antes) ou em um local óbvio que lhe seja desconhecido (como atrás de uma porta, depois de uma esquina ou em um bosque). O sensor intangível e invulnerável permanece no lugar pela duração. Quando você conjura a magia, escolha ver ou ouvir. Você pode usar o sentido escolhido através do sensor como se estivesse no espaço dele. Com uma ação bônus, você pode alternar entre ver e ouvir. Uma criatura que veja o sensor (como uma criatura que se beneficie de Ver Invisibilidade ou Visão Verdadeira) vê um orbe luminoso do tamanho aproximado do seu punho.","superior":""},
  {"en":"Clone","nome":"Clone","nivel":8,"escola":"Necromancia","tempo":"1 hora","alcance":"Toque","duracao":"Instantânea","componentes":"V, S, M (um diamante que valha 1.000+ PO, que a magia consome, e um recipiente selável que valha 2.000+ PO e seja grande o bastante para conter a criatura a ser clonada)","concentracao":false,"ritual":false,"classes":["Mago"],"teste":"","dano":"","gatilho":"","texto":"Você toca uma criatura ou pelo menos 16 cm³ da carne dela. Um duplicado inerte dessa criatura se forma dentro do recipiente usado na conjuração da magia e termina de crescer após 120 dias; você escolhe se o clone pronto tem a mesma idade da criatura ou é mais jovem. O clone permanece inerte e dura indefinidamente enquanto seu recipiente permanecer intacto. Se a criatura original morrer depois que o clone terminar de se formar, a alma da criatura é transferida para o clone, se a alma estiver livre e disposta a retornar. O clone é fisicamente idêntico ao original e tem a mesma personalidade, memórias e habilidades, mas nenhum dos equipamentos do original. Os restos mortais originais da criatura, se houver, tornam-se inertes e não podem ser revividos, já que a alma da criatura está em outro lugar.","superior":""},
  {"en":"Flame Strike","nome":"Coluna de chamas","nivel":5,"escola":"Evocação","tempo":"1 ação","alcance":"18 m","duracao":"Instantânea","componentes":"V, S, M (uma pitada de enxofre)","concentracao":false,"ritual":false,"classes":["Clérigo"],"teste":"Salvaguarda de Destreza","dano":"5d6 fogo radiante","gatilho":"","texto":"Uma coluna vertical de fogo brilhante ruge vinda do alto. Cada criatura em um Cilindro de 3 m de raio e 12 m de altura centrado em um ponto ao alcance faz uma salvaguarda de Destreza, sofrendo 5d6 de dano de fogo e 5d6 de dano radiante se falhar, ou metade desse dano se tiver sucesso.","superior":"O dano de fogo e o dano radiante aumentam em 1d6 para cada nível do espaço de magia acima de 5."},
  {"en":"Command","nome":"Comando","nivel":1,"escola":"Encantamento","tempo":"1 ação","alcance":"18 m","duracao":"Instantânea","componentes":"V","concentracao":false,"ritual":false,"classes":["Bardo","Clérigo","Paladino"],"teste":"Salvaguarda de Sabedoria","dano":"","gatilho":"","texto":"Você fala um comando de uma palavra a uma criatura que você possa ver ao alcance. O alvo deve ter sucesso em uma salvaguarda de Sabedoria ou seguir o comando em seu próximo turno. Escolha o comando entre estas opções:\n\n- **Largar.** O alvo larga o que quer que esteja segurando e então termina seu turno.\n- **Fugir.** O alvo gasta seu turno se afastando de você pelo meio mais rápido disponível.\n- **Rojar-se.** O alvo tem a condição Caído e então termina seu turno.\n- **Parar.** Em seu turno, o alvo não se move e não realiza ação nem ação bônus.","superior":"Você pode afetar uma criatura adicional para cada nível do espaço de magia acima de 1."},
  {"en":"Comprehend Languages","nome":"Compreender idiomas","nivel":1,"escola":"Adivinhação","tempo":"1 ação","alcance":"Pessoal","duracao":"1 hora","componentes":"V, S, M (uma pitada de fuligem e sal)","concentracao":false,"ritual":true,"classes":["Bardo","Feiticeiro","Bruxo","Mago"],"teste":"","dano":"","gatilho":"","texto":"Pela duração, você entende o significado literal de qualquer idioma que ouça ou veja em sinais. Você também entende qualquer idioma escrito que veja, mas deve estar tocando a superfície em que as palavras estão escritas. Leva cerca de 1 minuto para ler uma página de texto. Esta magia não decifra símbolos nem mensagens secretas.","superior":""},
  {"en":"Compulsion","nome":"Compulsão","nivel":4,"escola":"Encantamento","tempo":"1 ação","alcance":"9 m","duracao":"Concentração, até 1 minuto","componentes":"V, S","concentracao":true,"ritual":false,"classes":["Bardo"],"teste":"Salvaguarda de Sabedoria","dano":"","gatilho":"","texto":"Cada criatura de sua escolha que você possa ver ao alcance deve ter sucesso em uma salvaguarda de Sabedoria ou terá a condição Enfeitiçado até a magia terminar. Pela duração, você pode usar uma ação bônus para designar uma direção horizontal em relação a você. Cada alvo Enfeitiçado deve usar o máximo possível de seu movimento para se mover nessa direção em seu próximo turno, seguindo a rota mais segura. Depois de se mover dessa forma, o alvo repete a salvaguarda, encerrando a magia sobre si se tiver sucesso.","superior":""},
  {"en":"Commune","nome":"Comunhão","nivel":5,"escola":"Adivinhação","tempo":"1 minuto","alcance":"Pessoal","duracao":"1 minuto","componentes":"V, S, M (incenso)","concentracao":false,"ritual":true,"classes":["Clérigo"],"teste":"","dano":"","gatilho":"","texto":"Você entra em contato com uma divindade ou um representante divino e faz até três perguntas que possam ser respondidas com sim ou não. Você deve fazer suas perguntas antes de a magia terminar. Você recebe uma resposta correta para cada pergunta. Seres divinos não são necessariamente oniscientes, então você pode receber \"incerto\" como resposta se uma pergunta se referir a informações que estejam além do conhecimento da divindade. Caso uma resposta de uma palavra possa ser enganosa ou contrária aos interesses da divindade, o Mestre pode oferecer uma frase curta como resposta. Se você conjurar a magia mais de uma vez antes de terminar um Descanso Longo, há uma chance cumulativa de 25% a cada conjuração após a primeira de que você não receba resposta.","superior":""},
  {"en":"Commune with Nature","nome":"Comunhão com a natureza","nivel":5,"escola":"Adivinhação","tempo":"1 minuto","alcance":"Pessoal","duracao":"Instantânea","componentes":"V, S","concentracao":false,"ritual":true,"classes":["Druida","Patrulheiro"],"teste":"","dano":"","gatilho":"","texto":"Você se comunica com espíritos da natureza e obtém conhecimento da área ao redor. Ao ar livre, a magia lhe dá conhecimento da área a até 4,5 km de você. Em cavernas e outros ambientes subterrâneos naturais, o raio é limitado a 90 m. A magia não funciona onde a natureza foi substituída por construções, como em castelos e povoados. Escolha três dos fatos a seguir; você descobre esses fatos conforme se aplicam à área da magia: - Localização de povoados - Localização de portais para outros planos de existência - Localização de uma criatura de Nível de Desafio 10+ (à escolha do Mestre) que seja um Celestial, um Elemental, um Feérico, um Ínfero ou um Morto-vivo - O tipo mais predominante de planta, mineral ou Fera (você escolhe qual descobrir) - Localização de corpos d'água Por exemplo, você poderia determinar a localização de um monstro poderoso na área, a localização de corpos d'água e a localização de quaisquer cidades.","superior":""},
  {"en":"Cone of Cold","nome":"Cone de frio","nivel":5,"escola":"Evocação","tempo":"1 ação","alcance":"Pessoal","duracao":"Instantânea","componentes":"V, S, M (um pequeno cone de cristal ou vidro)","concentracao":false,"ritual":false,"classes":["Druida","Feiticeiro","Mago"],"teste":"Salvaguarda de Constituição","dano":"8d8 frio","gatilho":"","texto":"Você libera uma rajada de ar gélido. Cada criatura em um Cone de 18 m com origem em você faz uma salvaguarda de Constituição, sofrendo 8d8 de dano de frio se falhar ou metade desse dano se tiver sucesso. Uma criatura morta por esta magia se torna uma estátua congelada até descongelar.","superior":"O dano aumenta em 1d8 para cada nível do espaço de magia acima de 5."},
  {"en":"Confusion","nome":"Confusão","nivel":4,"escola":"Encantamento","tempo":"1 ação","alcance":"27 m","duracao":"Concentração, até 1 minuto","componentes":"V, S, M (três cascas de noz)","concentracao":true,"ritual":false,"classes":["Bardo","Druida","Feiticeiro","Mago"],"teste":"Salvaguarda de Sabedoria","dano":"1d10","gatilho":"","texto":"Cada criatura em uma Esfera de 3 m de raio centrada em um ponto que você escolher ao alcance deve ter sucesso em uma salvaguarda de Sabedoria, ou esse alvo não pode realizar ações bônus nem reações e deve rolar 1d10 no início de cada um de seus turnos para determinar seu comportamento naquele turno, consultando a tabela abaixo. Tabela: 1d10 Comportamento no Turno | d10 | Comportamento no Turno | |------|----------------------------------------------------------------------------------------------------------------------------------------------| | 1 | O alvo não realiza ação e usa todo o seu movimento para se mover. Role 1d4 para a direção: 1, norte; 2, leste; 3, sul; ou 4, oeste.| | 2–6 | O alvo não se move nem realiza ações. | | 7–8 | O alvo não se move e realiza a ação Atacar para fazer um ataque corpo a corpo contra uma criatura aleatória ao seu alcance. Se nenhuma estiver ao alcance, o alvo não realiza ação. | | 9–10 | O alvo escolhe seu comportamento. | Ao final de cada um de seus turnos, um alvo afetado repete a salvaguarda, encerrando a magia sobre si se tiver sucesso.","superior":"O raio da Esfera aumenta em 1,5 m para cada nível do espaço de magia acima de 4."},
  {"en":"Legend Lore","nome":"Conhecimento lendário","nivel":5,"escola":"Adivinhação","tempo":"1 minuto","alcance":"Pessoal","duracao":"Instantânea","componentes":"V, S, M (incenso que valha 250+ PO, que a magia consome, e quatro tiras de marfim que valham 50+ PO cada)","concentracao":false,"ritual":false,"classes":["Bardo","Clérigo","Mago"],"teste":"","dano":"","gatilho":"","texto":"Diga o nome ou descreva uma pessoa, lugar ou objeto famoso. A magia traz à sua mente um breve resumo do conhecimento significativo sobre essa coisa famosa, conforme descrito pelo Mestre. O conhecimento pode consistir em detalhes importantes, revelações curiosas ou até saberes secretos que nunca foram amplamente conhecidos. Quanto mais informações você já souber sobre a coisa, mais precisas e detalhadas serão as informações que receber. Essas informações são corretas, mas podem vir em linguagem figurada ou poesia, conforme determinado pelo Mestre. Se a coisa famosa que você escolheu não for realmente famosa, você ouve notas musicais tristes tocadas em um trombone, e a magia falha.","superior":""},
  {"en":"Contagion","nome":"Contágio","nivel":5,"escola":"Necromancia","tempo":"1 ação","alcance":"Toque","duracao":"7 dias","componentes":"V, S","concentracao":false,"ritual":false,"classes":["Clérigo","Druida"],"teste":"Salvaguarda de Constituição","dano":"11d8 necrótico","gatilho":"","texto":"Seu toque inflige um contágio mágico. O alvo deve ter sucesso em uma salvaguarda de Constituição ou sofrerá 11d8 de dano necrótico e terá a condição Envenenado. Além disso, escolha um atributo quando conjurar a magia. Enquanto Envenenado, o alvo tem Desvantagem em salvaguardas feitas com o atributo escolhido. O alvo deve repetir a salvaguarda ao final de cada um de seus turnos até obter três sucessos ou três falhas. Se o alvo tiver sucesso em três dessas salvaguardas, a magia termina sobre ele. Se o alvo falhar em três das salvaguardas, a magia dura 7 dias sobre ele. Sempre que o alvo Envenenado receber um efeito que encerraria a condição Envenenado, ele deve ter sucesso em uma salvaguarda de Constituição, ou a condição Envenenado não termina sobre ele.","superior":""},
  {"en":"Contact Other Plane","nome":"Contatar outro plano","nivel":5,"escola":"Adivinhação","tempo":"1 minuto","alcance":"Pessoal","duracao":"1 minuto","componentes":"V","concentracao":false,"ritual":true,"classes":["Bruxo","Mago"],"teste":"Salvaguarda de Inteligência","dano":"6d6 psíquico","gatilho":"","texto":"Você contata mentalmente um semideus, o espírito de um sábio morto há muito tempo ou alguma outra entidade conhecedora de outro plano. Contatar essa inteligência de outro mundo pode destruir sua mente. Quando você conjura esta magia, faça uma salvaguarda de Inteligência CD 15. Se tiver sucesso, você pode fazer até cinco perguntas à entidade. Você deve fazer suas perguntas antes de a magia terminar. O Mestre responde a cada pergunta com uma palavra, como \"sim\", \"não\", \"talvez\", \"nunca\", \"irrelevante\" ou \"incerto\" (se a entidade não souber a resposta). Se uma resposta de uma palavra for enganosa, o Mestre pode oferecer uma frase curta como resposta. Se falhar, você sofre 6d6 de dano psíquico e tem a condição Incapacitado até terminar um Descanso Longo. Uma magia Restauração Maior conjurada sobre você encerra esse efeito.","superior":""},
  {"en":"Contingency","nome":"Contingência","nivel":6,"escola":"Abjuração","tempo":"1 minuto","alcance":"Pessoal","duracao":"10 dias","componentes":"V, S, M (uma estatueta de si mesmo incrustada de gemas que valha 1.500+ PO)","concentracao":false,"ritual":false,"classes":["Mago"],"teste":"","dano":"","gatilho":"","texto":"Escolha uma magia de nível 5 ou inferior que você possa conjurar, que tenha tempo de conjuração de uma ação e que possa ter você como alvo. Você conjura essa magia, chamada de magia contingente, como parte da conjuração de Contingência, gastando espaços de magia para ambas, mas a magia contingente não entra em vigor. Em vez disso, ela entra em vigor quando ocorre um determinado gatilho. Você descreve esse gatilho quando conjura as duas magias. Por exemplo, uma Contingência conjurada com Respirar na Água pode estipular que Respirar na Água entra em vigor quando você for envolvido por água ou um líquido semelhante. A magia contingente entra em vigor imediatamente após o gatilho ocorrer pela primeira vez, quer você queira, quer não, e então Contingência termina. A magia contingente afeta apenas você, mesmo que normalmente possa ter outros como alvo. Você só pode ter uma magia Contingência ativa por vez. Se você conjurar esta magia novamente, o efeito de outra magia Contingência sobre você termina. Além disso, Contingência termina sobre você se o componente material dela deixar de estar em sua pessoa.","superior":""},
  {"en":"Counterspell","nome":"Contramágica","nivel":3,"escola":"Abjuração","tempo":"1 reação","alcance":"18 m","duracao":"Instantânea","componentes":"S","concentracao":false,"ritual":false,"classes":["Feiticeiro","Bruxo","Mago"],"teste":"Salvaguarda de Constituição","dano":"","gatilho":"que você realiza quando vê uma criatura a até 18 m de você conjurando uma magia com componentes Verbais, Somáticos ou Materiais","texto":"Você tenta interromper uma criatura no processo de conjurar uma magia. A criatura faz uma salvaguarda de Constituição. Se falhar, a magia se dissipa sem efeito, e a ação, ação bônus ou reação usada para conjurá-la é desperdiçada. Se essa magia foi conjurada com um espaço de magia, o espaço não é gasto.","superior":""},
  {"en":"Control Water","nome":"Controlar a água","nivel":4,"escola":"Transmutação","tempo":"1 ação","alcance":"90 m","duracao":"Concentração, até 10 minutos","componentes":"V, S, M (uma mistura de água e poeira)","concentracao":true,"ritual":false,"classes":["Clérigo","Druida","Mago"],"teste":"","dano":"","gatilho":"","texto":"Até a magia terminar, você controla qualquer água dentro de uma área que você escolher que seja um Cubo de até 30 m de lado, usando um dos efeitos a seguir. Com uma ação Magia em seus turnos seguintes, você pode repetir o mesmo efeito ou escolher outro.\n\n**Inundação.** Você faz o nível de toda a água parada na área subir até 6 m. Se você escolher uma área em um grande corpo d'água, em vez disso você cria uma onda de 6 m de altura que viaja de um lado da área ao outro e então arrebenta. Quaisquer veículos Enormes ou menores no caminho da onda são carregados com ela para o outro lado. Quaisquer veículos Enormes ou menores atingidos pela onda têm 25% de chance de virar.\n\nO nível da água permanece elevado até a magia terminar ou você escolher um efeito diferente. Se esse efeito produziu uma onda, a onda se repete no início do seu próximo turno enquanto o efeito de inundação durar.\n\n**Dividir Águas.** Você divide a água na área e cria uma vala. A vala se estende por toda a área da magia, e a água separada forma uma parede de cada lado. A vala permanece até a magia terminar ou você escolher um efeito diferente. A água então preenche lentamente a vala ao longo da rodada seguinte, até o nível normal da água ser restaurado.\n\n**Redirecionar Fluxo.** Você faz a água corrente na área se mover em uma direção que você escolher, mesmo que a água tenha de fluir sobre obstáculos, subir paredes ou seguir outras direções improváveis. A água na área se move conforme você a dirige, mas, uma vez que sai da área da magia, retoma seu fluxo com base no terreno. A água continua a se mover na direção que você escolheu até a magia terminar ou você escolher um efeito diferente.\n\n**Redemoinho.** Você faz um redemoinho se formar no centro da área, que deve ter pelo menos 15 m de lado e 7,5 m de profundidade. O redemoinho dura até você escolher um efeito diferente ou a magia terminar. O redemoinho tem 1,5 m de largura na base, até 15 m de largura no topo e 7,5 m de altura. Qualquer criatura na água e a até 7,5 m do redemoinho é puxada 3 m em direção a ele. Quando uma criatura entra no redemoinho pela primeira vez em um turno ou termina seu turno ali, ela faz uma salvaguarda de Força. Se falhar, a criatura sofre 2d8 de dano contundente. Se tiver sucesso, a criatura sofre metade desse dano. Uma criatura só pode nadar para longe do redemoinho se primeiro usar uma ação para se afastar e tiver sucesso em um teste de Força (Atletismo) contra a CD de salvaguarda da sua magia.","superior":""},
  {"en":"Control Weather","nome":"Controlar o clima","nivel":8,"escola":"Transmutação","tempo":"1 minuto","alcance":"Pessoal","duracao":"Concentração, até 8 horas","componentes":"V, S, M (incenso queimando)","concentracao":true,"ritual":false,"classes":["Clérigo","Druida","Mago"],"teste":"","dano":"1d4","gatilho":"","texto":"Você assume o controle do clima a até 7,5 km de você pela duração. Você deve estar ao ar livre para conjurar esta magia, e ela termina antes do tempo se você entrar em um local fechado. Quando você conjura a magia, você muda as condições climáticas atuais, que são determinadas pelo Mestre. Você pode mudar a precipitação, a temperatura e o vento. Leva 1d4 × 10 minutos para as novas condições entrarem em vigor. Quando isso acontece, você pode mudar as condições novamente. Quando a magia termina, o clima volta gradualmente ao normal. Ao mudar as condições climáticas, encontre uma condição atual nas tabelas a seguir e altere seu estágio em um, para cima ou para baixo. Ao mudar o vento, você pode mudar sua direção. Tabela: Precipitação | Estágio | Condição | |-------|--------------------------------------------| | 1 | Céu limpo | | 2 | Nuvens leves | | 3 | Nublado ou neblina rasteira | | 4 | Chuva, granizo ou neve | | 5 | Chuva torrencial, granizo intenso ou nevasca | Tabela: Temperatura | Estágio | Condição | |-------------|-----------| | 1 | Onda de calor | | 2 | Quente | | 3 | Morno | | 4 | Fresco | | 5 | Frio | | 6 | Congelante | Tabela: Vento | Estágio | Condição | |-------|---------------| | 1 | Calmaria | | 2 | Vento moderado | | 3 | Vento forte | | 4 | Ventania | | 5 | Tempestade |","superior":""},
  {"en":"Find Familiar","nome":"Convocar familiar","nivel":1,"escola":"Conjuração","tempo":"1 hora","alcance":"3 m","duracao":"Instantânea","componentes":"V, S, M (incenso queimando que valha 10+ PO, que a magia consome)","concentracao":false,"ritual":true,"classes":["Mago"],"teste":"","dano":"","gatilho":"","texto":"Você ganha o serviço de um familiar, um espírito que assume uma forma animal à sua escolha: Morcego, Gato, Sapo, Falcão, Lagarto, Polvo, Coruja, Rato, Corvo, Aranha, Doninha ou outra Fera que tenha Nível de Desafio 0. Aparecendo em um espaço desocupado ao alcance, o familiar tem as estatísticas da forma escolhida (veja \"Monstros\"), embora seja um Celestial, Feérico ou Ínfero (à sua escolha) em vez de uma Fera. Seu familiar age de forma independente de você, mas obedece aos seus comandos.\n\n**_Conexão Telepática._** Enquanto seu familiar estiver a até 30 m de você, você pode se comunicar com ele telepaticamente. Além disso, com uma ação bônus, você pode ver pelos olhos do familiar e ouvir o que ele ouve até o início do seu próximo turno, obtendo os benefícios de quaisquer sentidos especiais que ele tenha.\n\nPor fim, quando você conjura uma magia com alcance de toque, seu familiar pode transmitir o toque. Seu familiar deve estar a até 30 m de você e deve usar uma reação para transmitir o toque quando você conjura a magia.\n\n**_Combate._** O familiar é um aliado seu e dos seus aliados. Ele rola a própria Iniciativa e age no próprio turno. Um familiar não pode atacar, mas pode realizar outras ações normalmente.\n\n**_Desaparecimento do Familiar._** Quando o familiar chega a 0 Pontos de Vida, ele desaparece. Ele reaparece depois que você conjura esta magia novamente. Com uma ação Magia, você pode dispensar temporariamente o familiar para uma dimensão de bolso. Como alternativa, você pode dispensá-lo para sempre. Com uma ação Magia enquanto ele estiver temporariamente dispensado, você pode fazê-lo reaparecer em um espaço desocupado a até 9 m de você. Sempre que o familiar chega a 0 Pontos de Vida ou desaparece na dimensão de bolso, ele deixa para trás, no espaço dele, tudo o que estava vestindo ou carregando.\n\n**_Apenas um Familiar._** Você não pode ter mais de um familiar ao mesmo tempo. Se você conjurar esta magia enquanto tiver um familiar, faz com que ele adote uma nova forma elegível.","superior":""},
  {"en":"Find Steed","nome":"Convocar montaria","nivel":2,"escola":"Conjuração","tempo":"1 ação","alcance":"9 m","duracao":"Instantânea","componentes":"V, S","concentracao":false,"ritual":false,"classes":["Paladino"],"teste":"","dano":"","gatilho":"","texto":"Você convoca um ser de outro mundo que aparece como uma montaria leal em um espaço desocupado à sua escolha ao alcance. Essa criatura usa o bloco de estatísticas Montaria de Outro Mundo. Se você já tiver uma montaria desta magia, ela é substituída pela nova.\n\nA montaria se assemelha a um animal Grande e cavalgável à sua escolha, como um cavalo, um camelo, um lobo atroz ou um alce. Sempre que conjurar a magia, escolha o tipo de criatura da montaria: Celestial, Feérico ou Ínfero, o que determina certas características do bloco de estatísticas.\n\n**_Combate._** A montaria é um aliado seu e dos seus aliados. Em combate, ela compartilha a sua contagem de Iniciativa e funciona como uma montaria controlada enquanto você a cavalga (conforme definido nas regras de combate montado). Se você estiver com a condição Incapacitado, a montaria age imediatamente depois de você e atua de forma independente, concentrando-se em protegê-lo.\n\n**_Desaparecimento da Montaria._** A montaria desaparece se chegar a 0 Pontos de Vida ou se você morrer. Quando desaparece, ela deixa para trás tudo o que estava vestindo ou carregando. Se você conjurar esta magia novamente, você decide se convoca a montaria que desapareceu ou uma diferente.","superior":"Use o nível do espaço de magia como o nível da magia no bloco de estatísticas."},
  {"en":"Call Lightning","nome":"Convocar relâmpago","nivel":3,"escola":"Conjuração","tempo":"1 ação","alcance":"36 m","duracao":"Concentração, até 10 minutos","componentes":"V, S","concentracao":true,"ritual":false,"classes":["Druida"],"teste":"Salvaguarda de Destreza","dano":"3d10 elétrico","gatilho":"","texto":"Uma nuvem de tempestade surge em um ponto ao alcance que você possa ver acima de você. Ela assume a forma de um Cilindro de 3 m de altura e 18 m de raio. Quando você conjura a magia, escolha um ponto que você possa ver sob a nuvem. Um raio parte da nuvem até esse ponto. Cada criatura a até 1,5 m desse ponto faz uma salvaguarda de Destreza, sofrendo 3d10 de dano elétrico se falhar ou metade desse dano se tiver sucesso. Até a magia terminar, você pode realizar uma ação Magia para fazer cair um raio dessa forma novamente, mirando o mesmo ponto ou outro. Se você estiver ao ar livre durante uma tempestade quando conjurar esta magia, ela lhe dá controle sobre essa tempestade em vez de criar uma nova. Nessas condições, o dano da magia aumenta em 1d10.","superior":"O dano aumenta em 1d10 para cada nível do espaço de magia acima de 3."},
  {"en":"Spike Growth","nome":"Crescimento de espinhos","nivel":2,"escola":"Transmutação","tempo":"1 ação","alcance":"45 m","duracao":"Concentração, até 10 minutos","componentes":"V, S, M (sete espinhos)","concentracao":true,"ritual":false,"classes":["Druida","Patrulheiro"],"teste":"","dano":"2d4 perfurante","gatilho":"","texto":"O chão em uma Esfera de 6 m de raio centrada em um ponto ao alcance brota espinhos e espetos duros. A área se torna Terreno Difícil pela duração. Quando uma criatura se move para dentro da área ou dentro dela, sofre 2d4 de dano perfurante para cada 1,5 m que percorrer. A transformação do chão é camuflada para parecer natural. Qualquer criatura que não possa ver a área quando a magia é conjurada deve realizar a ação Procurar e ter sucesso em um teste de Sabedoria (Percepção ou Sobrevivência) contra a CD da sua magia para reconhecer o terreno como perigoso antes de entrar nele.","superior":""},
  {"en":"Plant Growth","nome":"Crescimento vegetal","nivel":3,"escola":"Transmutação","tempo":"1 hora","alcance":"45 m","duracao":"Instantânea","componentes":"V, S","concentracao":false,"ritual":false,"classes":["Bardo","Druida","Patrulheiro"],"teste":"","dano":"","gatilho":"","texto":"Esta magia canaliza vitalidade para as plantas. O tempo de conjuração que você usar determina se a magia tem o efeito Crescimento Excessivo ou Enriquecimento abaixo.\n\n**_Crescimento Excessivo._** Escolha um ponto ao alcance. Todas as plantas normais em uma Esfera de 30 m de raio centrada nesse ponto se tornam espessas e emaranhadas. Uma criatura que se mova por essa área deve gastar 1,2 m de movimento para cada 0,3 m que se mover. Você pode excluir uma ou mais áreas de qualquer tamanho dentro da área da magia para que não sejam afetadas.\n\n**_Enriquecimento._** Todas as plantas em um raio de 750 m centrado em um ponto ao alcance ficam enriquecidas por 365 dias. As plantas produzem o dobro da quantidade normal de alimento quando colhidas. Elas só podem se beneficiar de um *Crescimento de Plantas* por ano.","superior":""},
  {"en":"Creation","nome":"Criação","nivel":5,"escola":"Ilusão","tempo":"1 minuto","alcance":"9 m","duracao":"Especial","componentes":"V, S, M (um pincel)","concentracao":false,"ritual":false,"classes":["Feiticeiro","Mago"],"teste":"","dano":"","gatilho":"","texto":"Você puxa fiapos de matéria sombria do Pendor das Sombras para criar um objeto ao alcance. Ele é um objeto de matéria vegetal (tecidos macios, corda, madeira e semelhantes) ou de matéria mineral (pedra, cristal, metal e semelhantes). O objeto não pode ser maior que um Cubo de 1,5 m, e deve ter uma forma e um material que você já tenha visto. A duração da magia depende do material do objeto, conforme mostra a tabela Materiais. Se o objeto for composto de vários materiais, use a menor duração. Usar qualquer objeto criado por esta magia como componente material de outra magia faz a outra magia falhar. Tabela: Materiais | Material | Duração | |-----------------------|------------| | Matéria vegetal | 24 horas | | Pedra ou cristal | 12 horas | | Metais preciosos | 1 hora | | Gemas | 10 minutos | | Adamantina ou mithral | 1 minuto |","superior":"O Cubo aumenta em 1,5 m para cada nível do espaço de magia acima de 5."},
  {"en":"Create Food and Water","nome":"Criar alimento e água","nivel":3,"escola":"Conjuração","tempo":"1 ação","alcance":"9 m","duracao":"Instantânea","componentes":"V, S","concentracao":false,"ritual":false,"classes":["Clérigo","Paladino"],"teste":"","dano":"","gatilho":"","texto":"Você cria 22,5 kg de alimento e 114 litros de água fresca no chão ou em recipientes ao alcance, ambos úteis para combater os perigos da desnutrição e da desidratação. O alimento é insípido, mas nutritivo, e tem a aparência de um alimento de sua escolha, e a água é limpa. O alimento estraga após 24 horas se não for consumido.","superior":""},
  {"en":"Produce Flame","nome":"Criar chamas","nivel":0,"escola":"Conjuração","tempo":"1 ação bônus","alcance":"Pessoal","duracao":"10 minutos","componentes":"V, S","concentracao":false,"ritual":false,"classes":["Druida"],"teste":"Ataque de magia","dano":"1d8 fogo","gatilho":"","texto":"Uma chama tremeluzente surge em sua mão e permanece ali pela duração. Enquanto estiver ali, a chama não emite calor e não incendeia nada, e emite Luz Plena em um raio de 6 m e Penumbra por mais 6 m. A magia termina se você a conjurar novamente. Até a magia terminar, você pode realizar uma ação Magia para arremessar fogo em uma criatura ou um objeto a até 18 m de você. Faça uma jogada de ataque de magia à distância. Em um acerto, o alvo sofre 1d8 de dano de fogo.","superior":"O dano aumenta em 1d8 quando você alcança os níveis 5 (2d8), 11 (3d8) e 17 (4d8)."},
  {"en":"Create Undead","nome":"Criar mortos-vivos","nivel":6,"escola":"Necromancia","tempo":"1 minuto","alcance":"3 m","duracao":"Instantânea","componentes":"V, S, M (uma pedra de ônix negro que valha 150+ PO para cada cadáver)","concentracao":false,"ritual":false,"classes":["Clérigo","Bruxo","Mago"],"teste":"","dano":"","gatilho":"","texto":"Você pode conjurar esta magia apenas à noite. Escolha até três cadáveres de Humanoides Médios ou Pequenos ao alcance. Cada um se torna um Carniçal sob seu controle (veja \"Monstros\" para o bloco de estatísticas dele). Como ação bônus em cada um dos seus turnos, você pode comandar mentalmente qualquer criatura que tenha animado com esta magia, se ela estiver a até 36 m de você (se você controlar várias criaturas, pode comandar qualquer uma delas ao mesmo tempo, dando o mesmo comando a todas). Você decide qual ação a criatura realizará e para onde ela se moverá no próximo turno dela, ou pode dar um comando geral, como vigiar um local específico. Se você não der nenhum comando, a criatura realiza a ação Esquivar e se move apenas para evitar perigo. Depois de receber uma ordem, a criatura continua a segui-la até que sua tarefa esteja completa. A criatura fica sob seu controle por 24 horas, após as quais deixa de obedecer a qualquer comando que você tenha dado. Para manter o controle da criatura por mais 24 horas, você deve conjurar esta magia sobre ela antes que o período atual de 24 horas termine. Esse uso da magia reafirma seu controle sobre até três criaturas que você tenha animado com esta magia, em vez de animar novas.","superior":"Se você usar um espaço de magia de nível 7, pode animar ou reafirmar o controle sobre quatro Carniçais. Se usar um espaço de magia de nível 8, pode animar ou reafirmar o controle sobre cinco Carniçais ou dois Ghasts ou Wights. Se usar um espaço de magia de nível 9, pode animar ou reafirmar o controle sobre seis Carniçais, três Ghasts ou Wights, ou duas Múmias. Veja \"Monstros\" para esses blocos de estatísticas."},
  {"en":"Create or Destroy Water","nome":"Criar ou destruir água","nivel":1,"escola":"Transmutação","tempo":"1 ação","alcance":"9 m","duracao":"Instantânea","componentes":"V, S, M (uma mistura de água e areia)","concentracao":false,"ritual":false,"classes":["Clérigo","Druida"],"teste":"","dano":"","gatilho":"","texto":"Você faz uma das seguintes opções:\n\n**Criar Água.** Você cria até 38 litros de água limpa ao alcance em um recipiente aberto. Alternativamente, a água cai como chuva em um Cubo de 9 m ao alcance, extinguindo chamas expostas ali.\n\n**Destruir Água.** Você destrói até 38 litros de água em um recipiente aberto ao alcance. Alternativamente, você destrói névoa em um Cubo de 9 m ao alcance.","superior":"Você cria ou destrói 38 litros adicionais de água, ou o tamanho do Cubo aumenta em 1,5 m, para cada nível do espaço de magia acima de 1."},
  {"en":"Heal","nome":"Cura","nivel":6,"escola":"Abjuração","tempo":"1 ação","alcance":"18 m","duracao":"Instantânea","componentes":"V, S","concentracao":false,"ritual":false,"classes":["Clérigo","Druida"],"teste":"","dano":"","gatilho":"","texto":"Escolha uma criatura que você possa ver ao alcance. Energia positiva percorre o alvo, restaurando 70 Pontos de Vida. Esta magia também encerra as condições Cego, Surdo e Envenenado no alvo.","superior":"A cura aumenta em 10 para cada nível do espaço de magia acima de 6."},
  {"en":"Mass Heal","nome":"Cura em massa","nivel":9,"escola":"Abjuração","tempo":"1 ação","alcance":"18 m","duracao":"Instantânea","componentes":"V, S","concentracao":false,"ritual":false,"classes":["Clérigo"],"teste":"","dano":"","gatilho":"","texto":"Uma onda de energia curativa flui de você para as criaturas ao seu redor. Você restaura até 700 Pontos de Vida, divididos como você escolher entre qualquer número de criaturas que você possa ver ao alcance. As criaturas curadas por esta magia também têm as condições Cego, Surdo e Envenenado removidas.","superior":""},
  {"en":"Cure Wounds","nome":"Curar ferimentos","nivel":1,"escola":"Abjuração","tempo":"1 ação","alcance":"Toque","duracao":"Instantânea","componentes":"V, S","concentracao":false,"ritual":false,"classes":["Bardo","Clérigo","Druida","Paladino","Patrulheiro"],"teste":"","dano":"2d8","gatilho":"","texto":"Uma criatura que você tocar recupera uma quantidade de Pontos de Vida igual a 2d8 mais o modificador de atributo de conjuração.","superior":"A cura aumenta em 2d8 para cada nível do espaço de magia acima de 1."},
  {"en":"Mass Cure Wounds","nome":"Curar ferimentos em massa","nivel":5,"escola":"Abjuração","tempo":"1 ação","alcance":"18 m","duracao":"Instantânea","componentes":"V, S","concentracao":false,"ritual":false,"classes":["Bardo","Clérigo","Druida"],"teste":"","dano":"5d8","gatilho":"","texto":"Uma onda de energia curativa emana de um ponto que você possa ver ao alcance. Escolha até seis criaturas em uma Esfera de 9 m de raio centrada nesse ponto. Cada alvo recupera Pontos de Vida iguais a 5d8 mais o seu modificador de atributo de conjuração.","superior":"A cura aumenta em 1d8 para cada nível do espaço de magia acima de 5."},
  {"en":"Irresistible Dance","nome":"Dança irresistível","nivel":6,"escola":"Encantamento","tempo":"1 ação","alcance":"9 m","duracao":"Concentração, até 1 minuto","componentes":"V","concentracao":true,"ritual":false,"classes":["Bardo","Mago"],"teste":"Ataque de magia + Salvaguarda de Sabedoria","dano":"","gatilho":"","texto":"Uma criatura que você possa ver ao alcance deve fazer uma salvaguarda de Sabedoria. Com um sucesso, o alvo dança comicamente até o final do próximo turno dele, durante o qual deve gastar todo o seu movimento para dançar no lugar. Com uma falha, o alvo tem a condição Enfeitiçado pela duração. Enquanto Enfeitiçado, o alvo dança comicamente, deve usar todo o seu movimento para dançar no lugar, tem Desvantagem em salvaguardas de Destreza e em jogadas de ataque, e outras criaturas têm Vantagem em jogadas de ataque contra ele. Em cada um dos seus turnos, o alvo pode usar uma ação para se recompor e repetir a salvaguarda, encerrando a magia sobre si com um sucesso.","superior":""},
  {"en":"Finger of Death","nome":"Dedo da morte","nivel":7,"escola":"Necromancia","tempo":"1 ação","alcance":"18 m","duracao":"Instantânea","componentes":"V, S","concentracao":false,"ritual":false,"classes":["Feiticeiro","Bruxo","Mago"],"teste":"Salvaguarda de Constituição","dano":"7d8 + 30 necrótico","gatilho":"","texto":"Você libera energia negativa contra uma criatura que você possa ver ao alcance. O alvo faz uma salvaguarda de Constituição, sofrendo 7d8 + 30 de dano necrótico se falhar, ou metade desse dano se tiver sucesso. Um Humanoide morto por esta magia se levanta no início do seu próximo turno como um Zumbi (veja \"Monstros\") que segue suas ordens verbais.","superior":""},
  {"en":"Blight","nome":"Definhar","nivel":4,"escola":"Necromancia","tempo":"1 ação","alcance":"9 m","duracao":"Instantânea","componentes":"V, S","concentracao":false,"ritual":false,"classes":["Druida","Feiticeiro","Bruxo","Mago"],"teste":"Salvaguarda de Constituição","dano":"8d8 necrótico","gatilho":"","texto":"Uma criatura que você possa ver ao alcance faz uma salvaguarda de Constituição, sofrendo 8d8 de dano necrótico em uma falha ou metade desse dano em um sucesso. Uma criatura Planta falha automaticamente na salvaguarda. Alternativamente, escolha como alvo uma planta não mágica que não seja uma criatura, como uma árvore ou arbusto. Ela não faz salvaguarda; simplesmente murcha e morre.","superior":"O dano aumenta em 1d8 para cada nível do espaço de magia acima de 4."},
  {"en":"Gentle Repose","nome":"Descanso tranquilo","nivel":2,"escola":"Necromancia","tempo":"1 ação","alcance":"Toque","duracao":"10 dias","componentes":"V, S, M (2 Peças de Cobre, que a magia consome)","concentracao":false,"ritual":true,"classes":["Clérigo","Paladino","Mago"],"teste":"","dano":"","gatilho":"","texto":"Você toca um cadáver ou outros restos mortais. Pela duração, o alvo fica protegido contra a decomposição e não pode se tornar Morto-vivo. A magia também estende efetivamente o prazo para reviver o alvo, pois os dias passados sob a influência desta magia não contam para o prazo de magias como Reviver os Mortos.","superior":""},
  {"en":"Wish","nome":"Desejo","nivel":9,"escola":"Conjuração","tempo":"1 ação","alcance":"Pessoal","duracao":"Instantânea","componentes":"V","concentracao":false,"ritual":false,"classes":["Feiticeiro","Mago"],"teste":"","dano":"1d10 necrótico","gatilho":"","texto":"*Desejo* é a magia mais poderosa que um mortal pode conjurar. Apenas falando em voz alta, você pode alterar a própria realidade.\n\nO uso básico desta magia é duplicar qualquer outra magia de nível 8 ou inferior. Se você a usar dessa forma, não precisa cumprir nenhum requisito para conjurar essa magia, incluindo componentes dispendiosos. A magia simplesmente entra em efeito.\n\nAlternativamente, você pode criar um dos seguintes efeitos à sua escolha:\n\n**_Criação de Objeto._** Você cria um objeto de valor até 25.000 PO que não seja um item mágico. O objeto não pode ter mais de 90 m em qualquer dimensão e surge em um espaço desocupado no chão que você possa ver.\n\n**_Saúde Instantânea._** Você permite que você mesmo e até vinte criaturas que você possa ver recuperem todos os Pontos de Vida, e encerra todos os efeitos sobre elas listados na magia *Restauração Maior*.\n\n**_Resistência._** Você concede a até dez criaturas que você possa ver Resistência a um tipo de dano à sua escolha. Essa Resistência é permanente.\n\n**_Imunidade a Magia._** Você concede a até dez criaturas que você possa ver imunidade a uma única magia ou outro efeito mágico por 8 horas.\n\n**_Aprendizado Súbito._** Você substitui um de seus talentos por outro talento para o qual você seja elegível. Você perde todos os benefícios do talento antigo e ganha os benefícios do novo. Você não pode substituir um talento que seja pré-requisito para qualquer um de seus outros talentos ou características.\n\n**_Repetição de Jogada._** Você desfaz um único evento recente forçando a repetição de qualquer jogada de dado feita durante a última rodada (incluindo seu último turno). A realidade se remodela para acomodar o novo resultado. Por exemplo, uma magia *Desejo* poderia desfazer uma salvaguarda fracassada de um aliado ou um Acerto Crítico de um inimigo. Você pode forçar que a repetição seja feita com Vantagem ou Desvantagem, e escolhe se usará a nova jogada ou a original.\n\n**_Remodelar a Realidade._** Você pode desejar algo não incluído em nenhum dos outros efeitos. Para isso, declare seu desejo ao Mestre da maneira mais precisa possível. O Mestre tem grande liberdade para decidir o que ocorre nesse caso; quanto maior o desejo, maior a probabilidade de que algo dê errado. A magia pode simplesmente falhar, o efeito desejado pode ser alcançado apenas em parte, ou você pode sofrer uma consequência imprevista devido à forma como formulou o desejo. Por exemplo, desejar que um vilão estivesse morto pode lançar você adiante no tempo, para uma época em que esse vilão já não esteja vivo, removendo-o efetivamente do jogo.\n\nDa mesma forma, desejar um item mágico Lendário ou um Artefato pode transportá-lo instantaneamente à presença do atual dono do item. Se seu desejo for concedido e seus efeitos tiverem consequências para uma comunidade, região ou mundo inteiro, é provável que você atraia inimigos poderosos. Se seu desejo afetasse um deus, os servos divinos desse deus poderiam intervir instantaneamente para impedi-lo ou para incentivá-lo a formular o desejo de determinada maneira. Se seu desejo desfizesse o próprio multiverso, ele falha.\n\nO estresse de conjurar *Desejo* para produzir qualquer efeito diferente de duplicar outra magia enfraquece você. Depois de suportar esse estresse, cada vez que você conjurar uma magia até terminar um Descanso Longo, você sofre 1d10 de dano necrótico por nível dessa magia. Esse dano não pode ser reduzido nem evitado de nenhuma forma. Além disso, seu valor de Força passa a ser 3 por 2d4 dias. Para cada um desses dias que você passar descansando e fazendo nada além de atividade leve, o tempo de recuperação restante diminui em 2 dias. Por fim, há 33 por cento de chance de você nunca mais conseguir conjurar *Desejo* se sofrer esse estresse.","superior":""},
  {"en":"Disintegrate","nome":"Desintegrar","nivel":6,"escola":"Transmutação","tempo":"1 ação","alcance":"18 m","duracao":"Instantânea","componentes":"V, S, M (uma pedra-ímã e poeira)","concentracao":false,"ritual":false,"classes":["Feiticeiro","Mago"],"teste":"Salvaguarda de Destreza","dano":"10d6 + 40 energia","gatilho":"","texto":"Você lança um raio verde contra um alvo que você possa ver ao alcance. O alvo pode ser uma criatura, um objeto não mágico ou uma criação de energia mágica, como a parede criada por Muralha de Energia. Uma criatura alvo desta magia faz uma salvaguarda de Destreza. Se falhar, o alvo sofre 10d6 + 40 de dano de energia. Se esse dano reduzir o alvo a 0 Pontos de Vida, ele e tudo que for não mágico e que ele esteja vestindo e carregando são desintegrados em poeira cinzenta. O alvo só pode ser revivido por Ressurreição Verdadeira ou pela magia Desejo. Esta magia desintegra automaticamente um objeto não mágico Grande ou menor ou uma criação de energia mágica. Se tal alvo for Enorme ou maior, esta magia desintegra uma porção dele equivalente a um Cubo de 3 m.","superior":"O dano aumenta em 3d6 para cada nível do espaço de magia acima de 6."},
  {"en":"Shatter","nome":"Despedaçar","nivel":2,"escola":"Evocação","tempo":"1 ação","alcance":"18 m","duracao":"Instantânea","componentes":"V, S, M (um fragmento de mica)","concentracao":false,"ritual":false,"classes":["Bardo","Feiticeiro","Mago"],"teste":"Salvaguarda de Constituição","dano":"3d8 trovejante","gatilho":"","texto":"Um ruído alto irrompe de um ponto à sua escolha ao alcance. Cada criatura em uma Esfera de 3 m de raio centrada ali realiza uma salvaguarda de Constituição, sofrendo 3d8 de dano trovejante em caso de falha ou metade desse dano em caso de sucesso. Um Constructo tem Desvantagem na salvaguarda. Um objeto não mágico que não esteja sendo vestido nem carregado também sofre o dano se estiver na área da magia.","superior":"O dano aumenta em 1d8 para cada nível do espaço de magia acima de 2."},
  {"en":"Awaken","nome":"Despertar","nivel":5,"escola":"Transmutação","tempo":"1 hora","alcance":"Toque","duracao":"Instantânea","componentes":"V, S, M (uma ágata que valha 1.000+ PO, que a magia consome)","concentracao":false,"ritual":false,"classes":["Bardo","Druida"],"teste":"","dano":"","gatilho":"","texto":"Você gasta o tempo de conjuração traçando caminhos mágicos dentro de uma gema preciosa e então toca o alvo. O alvo deve ser uma criatura Fera ou Planta com Inteligência 3 ou menos, ou uma planta natural que não seja uma criatura. O alvo ganha Inteligência 10 e a capacidade de falar um idioma que você conheça. Se o alvo for uma planta natural, ela se torna uma criatura Planta e ganha a capacidade de mover seus membros, raízes, trepadeiras, ramos e assim por diante, além de sentidos semelhantes aos de um humano. O Mestre escolhe estatísticas apropriadas para a Planta despertada, como as estatísticas do Arbusto Desperto ou da Árvore Desperta em \"Monstros\". O alvo despertado fica com a condição Enfeitiçado por 30 dias ou até você ou seus aliados causarem dano a ele. Quando essa condição termina, a criatura despertada escolhe sua atitude em relação a você.","superior":""},
  {"en":"Mislead","nome":"Despistar","nivel":5,"escola":"Ilusão","tempo":"1 ação","alcance":"Pessoal","duracao":"Concentração, até 1 hora","componentes":"S","concentracao":true,"ritual":false,"classes":["Bardo","Bruxo","Mago"],"teste":"Ataque de magia","dano":"","gatilho":"","texto":"Você recebe a condição Invisível ao mesmo tempo em que um duplo ilusório seu aparece onde você está. O duplo dura pela duração, mas a invisibilidade termina imediatamente depois que você fizer uma jogada de ataque, causar dano ou conjurar uma magia. Com uma ação Magia, você pode mover o duplo ilusório até o dobro do seu Deslocamento e fazê-lo gesticular, falar e se comportar da maneira que você escolher. Ele é intangível e invulnerável. Você pode ver através dos olhos dele e ouvir através dos ouvidos dele como se estivesse onde ele está.","superior":""},
  {"en":"Detect Magic","nome":"Detectar magia","nivel":1,"escola":"Adivinhação","tempo":"1 ação","alcance":"Pessoal","duracao":"Concentração, até 10 minutos","componentes":"V, S","concentracao":true,"ritual":true,"classes":["Bardo","Clérigo","Druida","Paladino","Patrulheiro","Feiticeiro","Bruxo","Mago"],"teste":"","dano":"","gatilho":"","texto":"Pela duração, você sente a presença de efeitos mágicos a até 9 m de você. Se sentir tais efeitos, você pode realizar a ação Magia para ver uma aura tênue ao redor de qualquer criatura ou objeto visível na área que carregue a magia e, se um efeito foi criado por uma magia, você descobre a escola de magia dela. A magia é bloqueada por 30 cm de pedra, terra ou madeira; 2,5 cm de metal; ou uma fina folha de chumbo.","superior":""},
  {"en":"Detect Evil and Good","nome":"Detectar o bem e o mal","nivel":1,"escola":"Adivinhação","tempo":"1 ação","alcance":"Pessoal","duracao":"Concentração, até 10 minutos","componentes":"V, S","concentracao":true,"ritual":false,"classes":["Clérigo","Paladino"],"teste":"","dano":"","gatilho":"","texto":"Pela duração, você sente a localização de qualquer Aberração, Celestial, Elemental, Feérico, Ínfero ou Morto-vivo a até 9 m de você. Você também sente se a magia Consagrar está ativa ali e, se estiver, onde. A magia é bloqueada por 30 cm de pedra, terra ou madeira; 2,5 cm de metal; ou uma fina folha de chumbo.","superior":""},
  {"en":"Detect Thoughts","nome":"Detectar pensamentos","nivel":2,"escola":"Adivinhação","tempo":"1 ação","alcance":"Pessoal","duracao":"Concentração, até 1 minuto","componentes":"V, S, M (1 moeda de cobre)","concentracao":true,"ritual":false,"classes":["Bardo","Feiticeiro","Mago"],"teste":"Salvaguarda de Sabedoria","dano":"","gatilho":"","texto":"Você ativa um dos efeitos abaixo. Até a magia terminar, você pode ativar qualquer um dos efeitos como ação Magia nos seus turnos seguintes.\n\n***Sentir Pensamentos.*** Você sente a presença de pensamentos a até 9 m de você que pertençam a criaturas que conheçam idiomas ou sejam telepáticas. Você não lê os pensamentos, mas sabe que uma criatura pensante está presente. A magia é bloqueada por 30 cm de pedra, terra ou madeira; 2,5 cm de metal; ou uma fina folha de chumbo.\n\n**Ler Pensamentos.** Escolha como alvo uma criatura que você possa ver a até 9 m de você ou uma criatura a até 9 m de você que você tenha detectado com a opção Sentir Pensamentos. Você descobre o que está mais presente na mente do alvo no momento. Se o alvo não conhecer nenhum idioma e não for telepático, você não descobre nada.\n\nComo ação Magia no seu próximo turno, você pode tentar sondar mais fundo a mente do alvo. Se sondar mais fundo, o alvo faz uma salvaguarda de Sabedoria. Se falhar, você discerne o raciocínio do alvo, suas emoções e algo que ocupe grande espaço em sua mente (como uma preocupação, um amor ou um ódio). Se tiver sucesso, a magia termina. De qualquer modo, o alvo sabe que você está sondando a mente dele, e, até você desviar a atenção da mente do alvo, ele pode realizar uma ação no turno dele para fazer um teste de Inteligência (Arcanismo) contra a CD de salvaguarda das suas magias, encerrando a magia se tiver sucesso.","superior":""},
  {"en":"Detect Poison and Disease","nome":"Detectar veneno e doença","nivel":1,"escola":"Adivinhação","tempo":"1 ação","alcance":"Pessoal","duracao":"Concentração, até 10 minutos","componentes":"V, S, M (uma folha de teixo)","concentracao":true,"ritual":true,"classes":["Clérigo","Druida","Paladino","Patrulheiro"],"teste":"","dano":"","gatilho":"","texto":"Pela duração, você sente a localização de venenos, criaturas peçonhentas ou venenosas e contágios mágicos a até 9 m de você. Em cada caso, você sente o tipo de veneno, criatura ou contágio. A magia é bloqueada por 30 cm de pedra, terra ou madeira; 2,5 cm de metal; ou uma fina folha de chumbo.","superior":""},
  {"en":"Floating Disk","nome":"Disco flutuante","nivel":1,"escola":"Conjuração","tempo":"1 ação","alcance":"9 m","duracao":"1 hora","componentes":"V, S, M (uma gota de mercúrio)","concentracao":false,"ritual":true,"classes":["Mago"],"teste":"","dano":"","gatilho":"","texto":"Esta magia cria um plano de energia circular e horizontal, com 90 cm de diâmetro e 2,5 cm de espessura, que flutua 90 cm acima do chão em um espaço desocupado à sua escolha que você possa ver ao alcance. O disco permanece pela duração e pode sustentar até 250 kg. Se mais peso for colocado sobre ele, a magia termina, e tudo o que estiver no disco cai no chão. O disco fica imóvel enquanto você estiver a até 6 m dele. Se você se afastar mais de 6 m dele, o disco segue você de modo a permanecer a até 6 m de você. Ele pode se mover por terreno irregular, subir ou descer escadas, ladeiras e similares, mas não pode atravessar uma mudança de elevação de 3 m ou mais. Por exemplo, o disco não pode atravessar um fosso de 3 m de profundidade, nem sairia de um fosso assim se tivesse sido criado no fundo. Se você se afastar mais de 30 m do disco (normalmente porque ele não consegue contornar um obstáculo para seguir você), a magia termina.","superior":""},
  {"en":"Disguise Self","nome":"Disfarçar-se","nivel":1,"escola":"Ilusão","tempo":"1 ação","alcance":"Pessoal","duracao":"1 hora","componentes":"V, S","concentracao":false,"ritual":false,"classes":["Bardo","Feiticeiro","Mago"],"teste":"","dano":"","gatilho":"","texto":"Você faz a si mesmo, incluindo suas roupas, armadura, armas e outros pertences que carregue, parecer diferente até a magia terminar. Você pode parecer 30 cm mais baixo ou mais alto e pode parecer mais pesado ou mais leve. Você deve adotar uma forma que tenha o mesmo arranjo básico de membros que o seu. Fora isso, a extensão da ilusão fica a seu critério. As alterações causadas por esta magia não resistem a uma inspeção física. Por exemplo, se você usar esta magia para acrescentar um chapéu ao seu traje, objetos atravessam o chapéu, e qualquer um que o tocar não sentiria nada. Para perceber que você está disfarçado, uma criatura deve realizar a ação Estudar para inspecionar sua aparência e ter sucesso em um teste de Inteligência (Investigação) contra a CD de salvaguarda das suas magias.","superior":""},
  {"en":"Dispel Magic","nome":"Dissipar magia","nivel":3,"escola":"Abjuração","tempo":"1 ação","alcance":"36 m","duracao":"Instantânea","componentes":"V, S","concentracao":false,"ritual":false,"classes":["Bardo","Clérigo","Druida","Paladino","Patrulheiro","Feiticeiro","Bruxo","Mago"],"teste":"","dano":"","gatilho":"","texto":"Escolha uma criatura, objeto ou efeito mágico ao alcance. Qualquer magia em andamento de nível 3 ou inferior sobre o alvo termina. Para cada magia em andamento de nível 4 ou superior sobre o alvo, faça um teste de atributo usando seu atributo de conjuração (CD 10 mais o nível dessa magia). Se tiver sucesso no teste, a magia termina.","superior":"Você encerra automaticamente uma magia sobre o alvo se o nível da magia for igual ou inferior ao nível do espaço de magia que você usar."},
  {"en":"Dispel Evil and Good","nome":"Dissipar o bem e o mal","nivel":5,"escola":"Abjuração","tempo":"1 ação","alcance":"Pessoal","duracao":"Concentração, até 1 minuto","componentes":"V, S, M (prata e ferro em pó)","concentracao":true,"ritual":false,"classes":["Clérigo","Paladino"],"teste":"Ataque de magia","dano":"","gatilho":"","texto":"Pela duração, Celestiais, Elementais, Feéricos, Ínferos e Mortos-vivos têm Desvantagem em jogadas de ataque contra você. Você pode encerrar a magia antes do fim usando qualquer uma das seguintes funções especiais.\n\n**Quebrar Encantamento.** Como ação Magia, você toca uma criatura que esteja possuída por criaturas dos tipos acima, ou que tenha a condição Enfeitiçado ou Amedrontado causada por uma ou mais delas. O alvo deixa de estar possuído, Enfeitiçado ou Amedrontado por tais criaturas.\n\n**Dispensar.** Como ação Magia, você escolhe como alvo uma criatura que você possa ver a até 1,5 m de você e que seja de um dos tipos de criatura acima. O alvo deve ter sucesso em uma salvaguarda de Carisma ou será enviado de volta ao seu plano natal, se já não estiver lá. Se não estiverem em seu plano natal, Mortos-vivos são enviados ao Pendor das Sombras, e Feéricos são enviados à Agrestia Feérica.","superior":""},
  {"en":"Dominate Beast","nome":"Dominar fera","nivel":4,"escola":"Encantamento","tempo":"1 ação","alcance":"18 m","duracao":"Concentração, até 1 minuto","componentes":"V, S","concentracao":true,"ritual":false,"classes":["Druida","Patrulheiro","Feiticeiro"],"teste":"Salvaguarda de Sabedoria","dano":"","gatilho":"","texto":"Uma Fera que você possa ver ao alcance deve ter sucesso em uma salvaguarda de Sabedoria ou terá a condição Enfeitiçado pela duração. O alvo tem Vantagem na salvaguarda se você ou seus aliados estiverem lutando contra ele. Sempre que o alvo sofrer dano, ele repete a salvaguarda, encerrando a magia sobre si mesmo se tiver sucesso. Você tem um elo telepático com o alvo Enfeitiçado enquanto vocês dois estiverem no mesmo plano de existência. No seu turno, você pode usar esse elo para dar comandos ao alvo (nenhuma ação necessária), como \"Ataque aquela criatura\", \"Mova-se para lá\" ou \"Traga aquele objeto\". O alvo faz o melhor para obedecer no turno dele. Se ele cumprir uma ordem e não receber nova direção sua, ele age e se move como quiser, focando em se proteger. Você pode comandar o alvo a realizar uma reação, mas deve usar a sua própria reação para isso.","superior":"Sua Concentração pode durar mais com um espaço de magia de nível 5 (até 10 minutos), 6 (até 1 hora) ou 7+ (até 8 horas)."},
  {"en":"Dominate Monster","nome":"Dominar monstro","nivel":8,"escola":"Encantamento","tempo":"1 ação","alcance":"18 m","duracao":"Concentração, até 1 hora","componentes":"V, S","concentracao":true,"ritual":false,"classes":["Bardo","Feiticeiro","Bruxo","Mago"],"teste":"Salvaguarda de Sabedoria","dano":"","gatilho":"","texto":"Uma criatura que você possa ver ao alcance deve ter sucesso em uma salvaguarda de Sabedoria ou terá a condição Enfeitiçado pela duração. O alvo tem Vantagem na salvaguarda se você ou seus aliados estiverem lutando contra ele. Sempre que o alvo sofrer dano, ele repete a salvaguarda, encerrando a magia sobre si mesmo se tiver sucesso. Você tem um elo telepático com o alvo Enfeitiçado enquanto vocês dois estiverem no mesmo plano de existência. No seu turno, você pode usar esse elo para dar comandos ao alvo (nenhuma ação necessária), como \"Ataque aquela criatura\", \"Mova-se para lá\" ou \"Traga aquele objeto\". O alvo faz o melhor para obedecer no turno dele. Se ele cumprir uma ordem e não receber nova direção sua, ele age e se move como quiser, focando em se proteger. Você pode comandar o alvo a realizar uma reação, mas deve usar a sua própria reação para isso.","superior":"Sua Concentração pode durar mais com um espaço de magia de nível 9 (até 8 horas)."},
  {"en":"Dominate Person","nome":"Dominar pessoa","nivel":5,"escola":"Encantamento","tempo":"1 ação","alcance":"18 m","duracao":"Concentração, até 1 minuto","componentes":"V, S","concentracao":true,"ritual":false,"classes":["Bardo","Feiticeiro","Mago"],"teste":"Salvaguarda de Sabedoria","dano":"","gatilho":"","texto":"Um Humanoide que você possa ver ao alcance deve ter sucesso em uma salvaguarda de Sabedoria ou terá a condição Enfeitiçado pela duração. O alvo tem Vantagem na salvaguarda se você ou seus aliados estiverem lutando contra ele. Sempre que o alvo sofrer dano, ele repete a salvaguarda, encerrando a magia sobre si mesmo se tiver sucesso. Você tem um elo telepático com o alvo Enfeitiçado enquanto vocês dois estiverem no mesmo plano de existência. No seu turno, você pode usar esse elo para dar comandos ao alvo (nenhuma ação necessária), como \"Ataque aquela criatura\", \"Mova-se para lá\" ou \"Traga aquele objeto\". O alvo faz o melhor para obedecer no turno dele. Se ele cumprir uma ordem e não receber nova direção sua, ele age e se move como quiser, focando em se proteger. Você pode comandar o alvo a realizar uma reação, mas deve usar a sua própria reação para isso.","superior":"Sua Concentração pode durar mais com um espaço de magia de nível 6 (até 10 minutos), 7 (até 1 hora) ou 8+ (até 8 horas)."},
  {"en":"Elementalism","nome":"Elementalismo","nivel":0,"escola":"Transmutação","tempo":"1 ação","alcance":"9 m","duracao":"Instantânea","componentes":"V, S","concentracao":false,"ritual":false,"classes":["Druida","Feiticeiro","Mago"],"teste":"","dano":"","gatilho":"","texto":"Você exerce controle sobre os elementos, criando um dos efeitos a seguir ao alcance.\n\n***Convocar Ar.*** Você cria uma brisa forte o bastante para ondular tecido, levantar poeira, farfalhar folhas e fechar portas e venezianas abertas, tudo em um Cubo de 1,5 m. Portas e venezianas mantidas abertas por alguém ou algo não são afetadas.\n\n***Convocar Terra.*** Você cria uma fina camada de poeira ou areia que cobre superfícies em uma área quadrada de 1,5 m, ou faz uma única palavra aparecer, na sua caligrafia, em um trecho de terra ou areia.\n\n***Convocar Fogo.*** Você cria uma nuvem fina de brasas inofensivas e fumaça colorida e perfumada em um Cubo de 1,5 m. Você escolhe a cor e o aroma, e as brasas podem acender velas, tochas ou lamparinas nessa área. O aroma da fumaça persiste por 1 minuto.\n\n***Convocar Água.*** Você cria uma névoa fresca que umedece levemente criaturas e objetos em um Cubo de 1,5 m. Como alternativa, você cria 1 xícara de água limpa em um recipiente aberto ou sobre uma superfície, e a água evapora em 1 minuto.\n\n***Moldar Elemento.*** Você faz terra, areia, fogo, fumaça, névoa ou água que caibam em um Cubo de 30 cm assumirem uma forma tosca (como a de uma criatura) por 1 hora.","superior":""},
  {"en":"Glibness","nome":"Eloquência","nivel":8,"escola":"Encantamento","tempo":"1 ação","alcance":"Pessoal","duracao":"1 hora","componentes":"V","concentracao":false,"ritual":false,"classes":["Bardo","Bruxo"],"teste":"","dano":"","gatilho":"","texto":"Até a magia terminar, quando você fizer um teste de Carisma, você pode substituir o número que tirar por 15. Além disso, não importa o que você diga, a magia que determinaria se você está dizendo a verdade indica que você está sendo sincero.","superior":""},
  {"en":"Find Traps","nome":"Encontrar armadilhas","nivel":2,"escola":"Adivinhação","tempo":"1 ação","alcance":"36 m","duracao":"Instantânea","componentes":"V, S","concentracao":false,"ritual":false,"classes":["Clérigo","Druida","Patrulheiro"],"teste":"","dano":"","gatilho":"","texto":"Você sente qualquer armadilha ao alcance que esteja na sua linha de visão. Para os fins desta magia, uma armadilha inclui qualquer objeto ou mecanismo criado para causar dano ou outro perigo. Assim, a magia sentiria as magias Alarme ou Glifo de Proteção ou uma armadilha mecânica de fosso, mas não revelaria uma fraqueza natural no piso, um teto instável ou um sumidouro oculto. Esta magia revela que há uma armadilha presente, mas não sua localização. Você fica sabendo a natureza geral do perigo representado por uma armadilha que sentir.","superior":""},
  {"en":"Find the Path","nome":"Encontrar o caminho","nivel":6,"escola":"Adivinhação","tempo":"1 minuto","alcance":"Pessoal","duracao":"Concentração, até 1 dia","componentes":"V, S, M (um conjunto de ferramentas de adivinhação, como cartas ou runas, que valha 100+ PO)","concentracao":true,"ritual":false,"classes":["Bardo","Clérigo","Druida"],"teste":"","dano":"","gatilho":"","texto":"Você sente magicamente a rota física mais direta até um local que você nomear. Você deve estar familiarizado com o local, e a magia falha se você nomear um destino em outro plano de existência, um destino em movimento (como uma fortaleza móvel) ou um destino inespecífico (como \"a toca de um dragão verde\"). Pela duração, enquanto você estiver no mesmo plano de existência do destino, você sabe a que distância ele está e em que direção fica. Sempre que você enfrentar uma escolha de caminhos no trajeto até lá, você sabe qual caminho é o mais direto.","superior":""},
  {"en":"Charm Monster","nome":"Enfeitiçar monstro","nivel":4,"escola":"Encantamento","tempo":"1 ação","alcance":"9 m","duracao":"1 hora","componentes":"V, S","concentracao":false,"ritual":false,"classes":["Bardo","Druida","Feiticeiro","Bruxo","Mago"],"teste":"Salvaguarda de Sabedoria","dano":"","gatilho":"","texto":"Uma criatura que você possa ver ao alcance faz uma salvaguarda de Sabedoria. Ela a faz com Vantagem se você ou seus aliados estiverem lutando contra ela. Se falhar, o alvo tem a condição Enfeitiçado até a magia terminar ou até você ou seus aliados lhe causarem dano. A criatura Enfeitiçada é Amistosa com você. Quando a magia termina, o alvo sabe que foi Enfeitiçado por você.","superior":"Você pode ter como alvo uma criatura adicional para cada nível do espaço de magia acima de 4."},
  {"en":"Charm Person","nome":"Enfeitiçar pessoa","nivel":1,"escola":"Encantamento","tempo":"1 ação","alcance":"9 m","duracao":"1 hora","componentes":"V, S","concentracao":false,"ritual":false,"classes":["Bardo","Druida","Feiticeiro","Bruxo","Mago"],"teste":"Salvaguarda de Sabedoria","dano":"","gatilho":"","texto":"Um Humanoide que você possa ver ao alcance faz uma salvaguarda de Sabedoria. Ele a faz com Vantagem se você ou seus aliados estiverem lutando contra ele. Se falhar, o alvo tem a condição Enfeitiçado até a magia terminar ou até você ou seus aliados lhe causarem dano. A criatura Enfeitiçada é Amistosa com você. Quando a magia termina, o alvo sabe que foi Enfeitiçado por você.","superior":"Você pode ter como alvo uma criatura adicional para cada nível do espaço de magia acima de 1."},
  {"en":"Entangle","nome":"Enredar","nivel":1,"escola":"Conjuração","tempo":"1 ação","alcance":"27 m","duracao":"Concentração, até 1 minuto","componentes":"V, S","concentracao":true,"ritual":false,"classes":["Druida","Patrulheiro"],"teste":"Salvaguarda de Força","dano":"","gatilho":"","texto":"Plantas agarradoras brotam do chão em um quadrado de 6 m ao alcance. Pela duração, essas plantas transformam o solo da área em Terreno Difícil. Elas desaparecem quando a magia acaba. Cada criatura (exceto você) na área quando você conjura a magia deve ter sucesso em uma salvaguarda de Força ou ficará com a condição Contido até a magia acabar. Uma criatura Contida pode usar uma ação para fazer um teste de Força (Atletismo) contra a CD de salvaguarda das suas magias. Se tiver sucesso, ela se liberta das plantas agarradoras e deixa de estar Contida por elas.","superior":""},
  {"en":"Ensnaring Strike","nome":"Ensnaring Strike","nivel":1,"escola":"Conjuração","tempo":"1 ação bônus","alcance":"Pessoal","duracao":"Concentração, até 1 minuto","componentes":"V","concentracao":true,"ritual":false,"classes":["Patrulheiro"],"teste":"Salvaguarda de Força","dano":"1d6 perfurante","gatilho":"","texto":"Quando você acerta o alvo, trepadeiras agarradoras surgem nele, e ele faz uma salvaguarda de Força. Uma criatura Grande ou maior tem Vantagem nessa salvaguarda. Se falhar, o alvo fica com a condição Contido até a magia acabar. Se tiver sucesso, as trepadeiras murcham, e a magia acaba. Enquanto estiver Contido, o alvo sofre 1d6 de dano perfurante no início de cada turno dele. O alvo ou uma criatura ao alcance dele pode usar uma ação para fazer um teste de Força (Atletismo) contra a CD de salvaguarda das suas magias. Se tiver sucesso, a magia acaba.","superior":"O dano aumenta em 1d6 para cada nível do espaço de magia acima de 1."},
  {"en":"Spider Climb","nome":"Escalada de aranha","nivel":2,"escola":"Transmutação","tempo":"1 ação","alcance":"Toque","duracao":"Concentração, até 1 hora","componentes":"V, S, M (uma gota de betume e uma aranha)","concentracao":true,"ritual":false,"classes":["Feiticeiro","Bruxo","Mago"],"teste":"","dano":"","gatilho":"","texto":"Até a magia terminar, uma criatura voluntária que você tocar ganha a capacidade de se mover para cima, para baixo e ao longo de superfícies verticais e de tetos, deixando as mãos livres. O alvo também ganha um Deslocamento de Escalada igual ao seu Deslocamento.","superior":"Você pode escolher uma criatura adicional como alvo para cada nível do espaço de magia acima de 2."},
  {"en":"Illusory Script","nome":"Escrita ilusória","nivel":1,"escola":"Ilusão","tempo":"1 minuto","alcance":"Toque","duracao":"10 dias","componentes":"S, M (tinta que valha 10+ PO, que a magia consome)","concentracao":false,"ritual":true,"classes":["Bardo","Bruxo","Mago"],"teste":"","dano":"","gatilho":"","texto":"Você escreve em pergaminho, papel ou outro material adequado e o imbui com uma ilusão que dura pela duração. Para você e para quaisquer criaturas que designar ao conjurar a magia, a escrita parece normal, parece ter sido escrita por sua mão e transmite o significado que você pretendia ao escrever o texto. Para todos os outros, a escrita parece estar em uma escrita desconhecida ou mágica, ininteligível. Como alternativa, a ilusão pode alterar o significado, a caligrafia e o idioma do texto, desde que o idioma seja um que você conheça. Se a magia for dissipada, a escrita original e a ilusão desaparecem. Uma criatura que tenha Visão Verdadeira pode ler a mensagem oculta.","superior":""},
  {"en":"Shield","nome":"Escudo arcano","nivel":1,"escola":"Abjuração","tempo":"1 reação","alcance":"Pessoal","duracao":"1 rodada","componentes":"V, S","concentracao":false,"ritual":false,"classes":["Feiticeiro","Mago"],"teste":"","dano":"","gatilho":"que você realiza quando é atingido por uma jogada de ataque ou é alvo da magia Mísseis Mágicos","texto":"Uma barreira imperceptível de energia mágica protege você. Até o início do seu próximo turno, você tem +5 de bônus na CA, inclusive contra o ataque que acionou a magia, e não sofre dano de Mísseis Mágicos.","superior":""},
  {"en":"Shield of Faith","nome":"Escudo da fé","nivel":1,"escola":"Abjuração","tempo":"1 ação bônus","alcance":"18 m","duracao":"Concentração, até 10 minutos","componentes":"V, S, M (um pergaminho de oração)","concentracao":true,"ritual":false,"classes":["Clérigo","Paladino"],"teste":"","dano":"","gatilho":"","texto":"Um campo cintilante envolve uma criatura à sua escolha ao alcance, concedendo a ela +2 de bônus na CA pela duração.","superior":""},
  {"en":"Fire Shield","nome":"Escudo de fogo","nivel":4,"escola":"Evocação","tempo":"1 ação","alcance":"Pessoal","duracao":"10 minutos","componentes":"V, S, M (um pouco de fósforo ou um vaga-lume)","concentracao":false,"ritual":false,"classes":["Druida","Feiticeiro","Mago"],"teste":"Ataque de magia","dano":"2d8 fogo frio","gatilho":"","texto":"Chamas tênues envolvem seu corpo pela duração, emitindo Luz Plena em um raio de 3 m e Penumbra por mais 3 m. As chamas fornecem a você um escudo quente ou um escudo frio, à sua escolha. O escudo quente concede Resistência a dano de frio, e o escudo frio concede Resistência a dano de fogo. Além disso, sempre que uma criatura a até 1,5 m de você acertar você com uma jogada de ataque corpo a corpo, o escudo irrompe em chamas. O atacante sofre 2d8 de dano de fogo se for um escudo quente ou 2d8 de dano de frio se for um escudo frio.","superior":""},
  {"en":"Darkness","nome":"Escuridão","nivel":2,"escola":"Evocação","tempo":"1 ação","alcance":"18 m","duracao":"Concentração, até 10 minutos","componentes":"V, M (pelo de morcego e um pedaço de carvão)","concentracao":true,"ritual":false,"classes":["Feiticeiro","Bruxo","Mago"],"teste":"","dano":"","gatilho":"","texto":"Pela duração, Escuridão mágica se espalha a partir de um ponto ao alcance e preenche uma Esfera de 4,5 m de raio. A Visão no Escuro não enxerga através dela, e luz não mágica não consegue iluminá-la. Como alternativa, você conjura a magia sobre um objeto que não esteja sendo vestido nem carregado, fazendo a Escuridão preencher uma Emanação de 4,5 m com origem nesse objeto. Cobrir esse objeto com algo opaco, como uma tigela ou um elmo, bloqueia a Escuridão. Se qualquer parte da área desta magia se sobrepuser a uma área de Luz Plena ou Penumbra criada por uma magia de nível 2 ou inferior, essa outra magia é dissipada.","superior":""},
  {"en":"Freezing Sphere","nome":"Esfera congelante","nivel":6,"escola":"Evocação","tempo":"1 ação","alcance":"90 m","duracao":"Instantânea","componentes":"V, S, M (uma esfera de cristal em miniatura)","concentracao":false,"ritual":false,"classes":["Feiticeiro","Mago"],"teste":"Salvaguarda de Constituição","dano":"10d6 frio","gatilho":"","texto":"Um globo gélido parte de você até um ponto à sua escolha ao alcance, onde explode em uma Esfera de 18 m de raio. Cada criatura nessa área faz uma salvaguarda de Constituição, sofrendo 10d6 de dano de frio se falhar, ou metade desse dano se tiver sucesso.\n\nSe o globo atingir um corpo de água, ele congela a água até uma profundidade de 15 cm em uma área quadrada de 9 m. Esse gelo dura 1 minuto. Criaturas que estavam nadando na superfície da água congelada ficam presas no gelo e têm a condição Contido. Uma criatura presa pode usar uma ação para fazer um teste de Força (Atletismo) contra a CD de salvaguarda das suas magias para se libertar.\n\nVocê pode se abster de lançar o globo depois de completar a conjuração da magia. Se fizer isso, um globo do tamanho de uma bala de funda, frio ao toque, aparece na sua mão. A qualquer momento, você ou uma criatura a quem você der o globo pode arremessá-lo (a um alcance de 12 m) ou lançá-lo com uma funda (ao alcance normal da funda). Ele se estilhaça no impacto, com o mesmo efeito de uma conjuração normal da magia. Você também pode pousar o globo sem estilhaçá-lo. Após 1 minuto, se o globo ainda não tiver se estilhaçado, ele explode.","superior":"O dano aumenta em 1d6 para cada nível do espaço de magia acima de 6."},
  {"en":"Flaming Sphere","nome":"Esfera flamejante","nivel":2,"escola":"Conjuração","tempo":"1 ação","alcance":"18 m","duracao":"Concentração, até 1 minuto","componentes":"V, S, M (uma bola de cera)","concentracao":true,"ritual":false,"classes":["Druida","Feiticeiro","Mago"],"teste":"Salvaguarda de Destreza","dano":"2d6 fogo","gatilho":"","texto":"Você cria uma esfera de fogo de 1,5 m de diâmetro em um espaço desocupado no chão ao alcance. Ela dura pela duração. Qualquer criatura que terminar o turno a até 1,5 m da esfera faz uma salvaguarda de Destreza, sofrendo 2d6 de dano de fogo se falhar, ou metade desse dano se tiver sucesso. Com uma ação bônus, você pode mover a esfera até 9 m, rolando-a pelo chão. Se você mover a esfera para o espaço de uma criatura, essa criatura faz a salvaguarda contra a esfera, e a esfera para de se mover pelo turno. Ao mover a esfera, você pode direcioná-la sobre barreiras de até 1,5 m de altura e fazê-la saltar sobre fossos de até 3 m de largura. Objetos inflamáveis que não estejam sendo vestidos nem carregados começam a queimar se tocados pela esfera, e ela emite Luz Plena em um raio de 6 m e Penumbra por mais 6 m.","superior":"O dano aumenta em 1d6 para cada nível do espaço de magia acima de 2."},
  {"en":"Resilient Sphere","nome":"Esfera resiliente","nivel":4,"escola":"Abjuração","tempo":"1 ação","alcance":"9 m","duracao":"Concentração, até 1 minuto","componentes":"V, S, M (uma esfera de vidro)","concentracao":true,"ritual":false,"classes":["Mago"],"teste":"Salvaguarda de Destreza","dano":"","gatilho":"","texto":"Uma esfera cintilante envolve uma criatura ou um objeto Grande ou menor ao alcance. Uma criatura involuntária deve ter sucesso em uma salvaguarda de Destreza ou ficará envolvida pela duração. Nada, nem objetos físicos, nem energia, nem outros efeitos de magia, pode atravessar a barreira, para dentro ou para fora, embora uma criatura dentro da esfera possa respirar ali. A esfera é imune a todo dano, e uma criatura ou um objeto dentro dela não pode sofrer dano de ataques ou efeitos originados do lado de fora, nem uma criatura dentro da esfera pode causar dano a nada fora dela. A esfera não tem peso e é apenas grande o suficiente para conter a criatura ou o objeto dentro. Uma criatura envolvida pode realizar uma ação para empurrar as paredes da esfera e assim rolá-la a até metade do Deslocamento da criatura. Da mesma forma, o globo pode ser levantado e movido por outras criaturas. Uma magia Desintegrar que tenha o globo como alvo o destrói sem ferir nada em seu interior.","superior":""},
  {"en":"Vitriolic Sphere","nome":"Esfera vitriólica","nivel":4,"escola":"Evocação","tempo":"1 ação","alcance":"45 m","duracao":"Instantânea","componentes":"V, S, M (uma gota de bile)","concentracao":false,"ritual":false,"classes":["Feiticeiro","Mago"],"teste":"Salvaguarda de Destreza","dano":"10d4 ácido","gatilho":"","texto":"Você aponta para um local ao alcance, e uma bola brilhante de ácido, com 30 cm de diâmetro, dispara até lá e explode em uma Esfera de 6 m de raio. Cada criatura nessa área faz uma salvaguarda de Destreza. Em caso de falha, a criatura sofre 10d4 de dano ácido e mais 5d4 de dano ácido no final do seu próximo turno. Em caso de sucesso, a criatura sofre apenas metade do dano inicial.","superior":"O dano inicial aumenta em 2d4 para cada nível do espaço de magia acima de 4."},
  {"en":"Arcane Sword","nome":"Espada arcana","nivel":7,"escola":"Evocação","tempo":"1 ação","alcance":"27 m","duracao":"Concentração, até 1 minuto","componentes":"V, S, M (uma espada em miniatura que valha 250+ PO)","concentracao":true,"ritual":false,"classes":["Bardo","Mago"],"teste":"Ataque de magia","dano":"4d12 energia","gatilho":"","texto":"Você cria uma espada espectral que paira ao alcance. Ela dura pela duração. Quando a espada aparece, você faz uma jogada de ataque de magia corpo a corpo contra um alvo a até 1,5 m da espada. Em um acerto, o alvo sofre dano de energia igual a 4d12 mais o modificador do seu atributo de conjuração. Em seus turnos posteriores, você pode usar uma ação bônus para mover a espada até 9 m para um ponto que possa ver e repetir o ataque contra o mesmo alvo ou contra um diferente.","superior":""},
  {"en":"Spirit Guardians","nome":"Espíritos guardiões","nivel":3,"escola":"Conjuração","tempo":"1 ação","alcance":"Pessoal","duracao":"Concentração, até 10 minutos","componentes":"V, S, M (um pergaminho de oração)","concentracao":true,"ritual":false,"classes":["Clérigo"],"teste":"Salvaguarda de Sabedoria","dano":"3d8 radiante necrótico","gatilho":"","texto":"Espíritos protetores esvoaçam ao seu redor em uma Emanação de 4,5 m pela duração. Se você for bom ou neutro, a forma espectral deles parece angelical ou feérica (à sua escolha). Se você for mau, eles parecem ínferos. Quando você conjura esta magia, pode designar criaturas para não serem afetadas por ela. O Deslocamento de qualquer outra criatura é reduzido à metade na Emanação, e sempre que a Emanação entra no espaço de uma criatura e sempre que uma criatura entra na Emanação ou termina seu turno ali, a criatura deve fazer uma salvaguarda de Sabedoria. Se falhar, a criatura sofre 3d8 de dano radiante (se você for bom ou neutro) ou 3d8 de dano necrótico (se você for mau). Se tiver sucesso, a criatura sofre metade do dano. Uma criatura faz esta salvaguarda apenas uma vez por turno.","superior":"O dano aumenta em 1d8 para cada nível do espaço de magia acima de 3."},
  {"en":"Etherealness","nome":"Eterealidade","nivel":7,"escola":"Conjuração","tempo":"1 ação","alcance":"Pessoal","duracao":"8 horas","componentes":"V, S","concentracao":false,"ritual":false,"classes":["Bardo","Clérigo","Feiticeiro","Bruxo","Mago"],"teste":"","dano":"","gatilho":"","texto":"Você entra nas regiões de fronteira do Plano Etéreo, onde ele se sobrepõe ao seu plano atual. Você permanece na Fronteira Etérea pela duração. Durante esse tempo, você pode se mover em qualquer direção. Se você se mover para cima ou para baixo, cada 30 cm de movimento custa 30 cm extras. Você pode perceber o plano que deixou, que parece cinzento, e não consegue ver nada ali a mais de 18 m de distância. Enquanto estiver no Plano Etéreo, você só pode afetar e ser afetado por criaturas, objetos e efeitos desse plano. Criaturas que não estão no Plano Etéreo não podem perceber você nem interagir com você, a menos que uma característica lhes dê essa capacidade. Quando a magia acaba, você retorna ao plano que deixou, no ponto que corresponde ao seu espaço na Fronteira Etérea. Se você aparecer em um espaço ocupado, é empurrado para o espaço desocupado mais próximo e sofre dano de energia igual a 2 para cada 30 cm que você for movido. Esta magia acaba instantaneamente se você a conjurar enquanto estiver no Plano Etéreo ou em um plano que não faça fronteira com ele, como um dos Planos Exteriores.","superior":"Você pode escolher até três criaturas dispostas (incluindo você) para cada nível do espaço de magia acima de 7. As criaturas devem estar a até 3 m de você quando você conjura a magia."},
  {"en":"Sunburst","nome":"Explosão solar","nivel":8,"escola":"Evocação","tempo":"1 ação","alcance":"45 m","duracao":"Instantânea","componentes":"V, S, M (um pedaço de pedra-do-sol)","concentracao":false,"ritual":false,"classes":["Clérigo","Druida","Feiticeiro","Mago"],"teste":"Salvaguarda de Constituição","dano":"12d6 radiante","gatilho":"","texto":"Uma luz solar brilhante irrompe em uma Esfera de 18 m de raio centrada em um ponto que você escolher ao alcance. Cada criatura na Esfera faz uma salvaguarda de Constituição. Se falhar, a criatura sofre 12d6 de dano radiante e fica com a condição Cego por 1 minuto. Se tiver sucesso, sofre apenas metade do dano. Uma criatura Cega por esta magia faz outra salvaguarda de Constituição no final de cada um dos turnos dela, encerrando o efeito sobre si com um sucesso. Esta magia dissipa a Escuridão em sua área que tenha sido criada por qualquer magia.","superior":""},
  {"en":"Eyebite","nome":"Eyebite","nivel":6,"escola":"Necromancia","tempo":"1 ação","alcance":"Pessoal","duracao":"Concentração, até 1 minuto","componentes":"V, S","concentracao":true,"ritual":false,"classes":["Bardo","Feiticeiro","Bruxo","Mago"],"teste":"Salvaguarda de Sabedoria","dano":"","gatilho":"","texto":"Pela duração, seus olhos se tornam um vazio escuro como tinta. Uma criatura à sua escolha a até 18 m de você que você possa ver deve ter sucesso em uma salvaguarda de Sabedoria ou será afetada por um dos seguintes efeitos à sua escolha pela duração. Em cada um dos seus turnos até a magia acabar, você pode usar uma ação Magia para escolher outra criatura como alvo, mas não pode escolher de novo uma criatura que tenha tido sucesso em uma salvaguarda contra esta conjuração da magia.\n\n**_Adormecido._** O alvo fica com a condição Inconsciente. Ele acorda se sofrer qualquer dano ou se outra criatura usar uma ação para sacudi-lo até acordar.\n\n**_Em Pânico._** O alvo fica com a condição Amedrontado. Em cada turno dele, o alvo Amedrontado deve realizar a ação Disparada e se afastar de você pela rota mais segura e mais curta disponível. Se o alvo se mover para um espaço a pelo menos 18 m de você onde ele não possa ver você, esse efeito acaba.\n\n**_Enjoado._** O alvo fica com a condição Envenenado.","superior":""},
  {"en":"Fabricate","nome":"Fabricar","nivel":4,"escola":"Transmutação","tempo":"1 minuto","alcance":"36 m","duracao":"Instantânea","componentes":"V, S","concentracao":false,"ritual":false,"classes":["Mago"],"teste":"","dano":"","gatilho":"","texto":"Você converte matérias-primas em produtos do mesmo material. Por exemplo, você pode fabricar uma ponte de madeira a partir de um aglomerado de árvores, uma corda a partir de um campo de cânhamo, ou roupas a partir de linho ou lã. Escolha matérias-primas que você possa ver ao alcance. Você pode fabricar um objeto Grande ou menor (contido em um Cubo de 3 m ou oito Cubos de 1,5 m conectados), desde que haja material suficiente. Se você estiver trabalhando com metal, pedra ou outra substância mineral, porém, o objeto fabricado não pode ser maior que Médio (contido em um Cubo de 1,5 m). A qualidade de qualquer objeto fabricado depende da qualidade das matérias-primas. Criaturas e itens mágicos não podem ser criados por esta magia. Você também não pode usá-la para criar itens que exijam alto grau de habilidade, como armas e armaduras, a menos que tenha proficiência no tipo de Ferramentas de Artesão usado para fabricar esses objetos.","superior":""},
  {"en":"Ice Knife","nome":"Faca de gelo","nivel":1,"escola":"Conjuração","tempo":"1 ação","alcance":"18 m","duracao":"Instantânea","componentes":"S, M (uma gota de água ou um pedaço de gelo)","concentracao":false,"ritual":false,"classes":["Druida","Feiticeiro","Mago"],"teste":"Ataque de magia + Salvaguarda de Destreza","dano":"1d10 perfurante frio","gatilho":"","texto":"Você cria um estilhaço de gelo e o arremessa contra uma criatura ao alcance. Faça uma jogada de ataque de magia à distância contra o alvo. Se acertar, o alvo sofre 1d10 de dano Perfurante. Acertando ou errando, o estilhaço então explode. O alvo e cada criatura a até 1,5 m dele devem ter sucesso em uma salvaguarda de Destreza ou sofrerão 2d6 de dano de Frio.","superior":"O dano de Frio aumenta em 1d6 para cada nível do espaço de magia acima de 1."},
  {"en":"Speak with Animals","nome":"Falar com animais","nivel":1,"escola":"Adivinhação","tempo":"1 ação","alcance":"Pessoal","duracao":"10 minutos","componentes":"V, S","concentracao":false,"ritual":true,"classes":["Bardo","Druida","Patrulheiro","Bruxo"],"teste":"","dano":"","gatilho":"","texto":"Pela duração, você pode compreender e se comunicar verbalmente com Feras e pode usar qualquer uma das opções de perícia da ação Influenciar com elas. A maioria das Feras tem pouco a dizer sobre assuntos que não se relacionem a sobrevivência ou companhia, mas, no mínimo, uma Fera pode lhe dar informações sobre locais e monstros próximos, incluindo o que quer que ela tenha percebido no último dia.","superior":""},
  {"en":"Speak with Dead","nome":"Falar com os mortos","nivel":3,"escola":"Necromancia","tempo":"1 ação","alcance":"3 m","duracao":"10 minutos","componentes":"V, S, M (incenso queimando)","concentracao":false,"ritual":false,"classes":["Bardo","Clérigo","Mago"],"teste":"","dano":"","gatilho":"","texto":"Você concede a aparência de vida a um cadáver à sua escolha ao alcance, permitindo que ele responda às perguntas que você fizer. O cadáver deve ter boca, e esta magia falha se a criatura morta era um Morto-vivo quando morreu. A magia também falha se o cadáver foi alvo desta magia nos últimos 10 dias. Até a magia terminar, você pode fazer até cinco perguntas ao cadáver. O cadáver sabe apenas o que sabia em vida, incluindo os idiomas que conhecia. As respostas costumam ser breves, enigmáticas ou repetitivas, e o cadáver não tem obrigação de dar uma resposta verdadeira se você for hostil com ele ou se ele o reconhecer como inimigo. Esta magia não devolve a alma da criatura ao corpo, apenas o espírito que o anima. Assim, o cadáver não pode aprender informações novas, não compreende nada do que aconteceu desde que morreu e não pode especular sobre eventos futuros.","superior":""},
  {"en":"Speak with Plants","nome":"Falar com plantas","nivel":3,"escola":"Transmutação","tempo":"1 ação","alcance":"Pessoal","duracao":"10 minutos","componentes":"V, S","concentracao":false,"ritual":false,"classes":["Bardo","Druida","Patrulheiro"],"teste":"","dano":"","gatilho":"","texto":"Você imbui as plantas em uma Emanação imóvel de 9 m com senciência e animação limitadas, dando a elas a capacidade de se comunicar com você e seguir seus comandos simples. Você pode questionar as plantas sobre eventos na área da magia ocorridos no último dia, obtendo informações sobre criaturas que passaram, clima e outras circunstâncias. Você também pode transformar Terreno Difícil causado pelo crescimento de plantas (como matagais e vegetação rasteira) em terreno comum que dura pela duração. Ou pode transformar terreno comum onde haja plantas em Terreno Difícil que dura pela duração. A magia não permite que as plantas se desenraizem e se movam, mas elas podem mover seus galhos, gavinhas e caules para você. Se uma criatura Planta estiver na área, você pode se comunicar com ela como se compartilhassem um idioma comum.","superior":""},
  {"en":"Beacon of Hope","nome":"Farol de esperança","nivel":3,"escola":"Abjuração","tempo":"1 ação","alcance":"9 m","duracao":"Concentração, até 1 minuto","componentes":"V, S","concentracao":true,"ritual":false,"classes":["Clérigo"],"teste":"Salvaguarda de Sabedoria","dano":"","gatilho":"","texto":"Escolha qualquer quantidade de criaturas ao alcance. Pela duração, cada alvo tem Vantagem em salvaguardas de Sabedoria e em Salvaguardas Contra Morte e recupera o número máximo possível de Pontos de Vida de qualquer cura.","superior":""},
  {"en":"Divine Favor","nome":"Favor divino","nivel":1,"escola":"Transmutação","tempo":"1 ação bônus","alcance":"Pessoal","duracao":"1 minuto","componentes":"V, S","concentracao":false,"ritual":false,"classes":["Paladino"],"teste":"","dano":"1d4 radiante","gatilho":"","texto":"Até a magia terminar, seus ataques com armas causam 1d4 de dano radiante extra ao atingir.","superior":""},
  {"en":"Acid Arrow","nome":"Flecha ácida","nivel":2,"escola":"Evocação","tempo":"1 ação","alcance":"27 m","duracao":"Instantânea","componentes":"V, S, M (folha de ruibarbo em pó)","concentracao":false,"ritual":false,"classes":["Mago"],"teste":"Ataque de magia","dano":"4d4 ácido","gatilho":"","texto":"Uma flecha verde cintilante dispara em direção a um alvo ao alcance e explode em um jato de ácido. Faça uma jogada de ataque de magia à distância contra o alvo. Em um acerto, o alvo sofre 4d4 de dano de ácido e mais 2d4 de dano de ácido no final do próximo turno dele. Em um erro, a flecha respinga ácido no alvo, causando apenas metade do dano inicial.","superior":"O dano (tanto o inicial quanto o posterior) aumenta em 1d4 para cada nível do espaço de magia acima de 2."},
  {"en":"Faerie Fire","nome":"Fogo das fadas","nivel":1,"escola":"Evocação","tempo":"1 ação","alcance":"18 m","duracao":"Concentração, até 1 minuto","componentes":"V","concentracao":true,"ritual":false,"classes":["Bardo","Druida"],"teste":"Ataque de magia + Salvaguarda de Destreza","dano":"","gatilho":"","texto":"Objetos em um Cubo de 6 m ao alcance são contornados por uma luz azul, verde ou violeta (à sua escolha). Cada criatura no Cubo também é contornada se falhar em uma salvaguarda de Destreza. Pela duração, objetos e criaturas afetadas emitem Penumbra em um raio de 3 m e não podem se beneficiar da condição Invisível. Jogadas de ataque contra uma criatura ou objeto afetado têm Vantagem se o atacante puder vê-lo.","superior":""},
  {"en":"Phantasmal Force","nome":"Força fantasmagórica","nivel":2,"escola":"Ilusão","tempo":"1 ação","alcance":"18 m","duracao":"Concentração, até 1 minuto","componentes":"V, S, M (um pedaço de lã)","concentracao":true,"ritual":false,"classes":["Bardo","Feiticeiro","Mago"],"teste":"Salvaguarda de Inteligência","dano":"2d8 psíquico","gatilho":"","texto":"Você tenta criar uma ilusão na mente de uma criatura que você possa ver ao alcance. O alvo faz uma salvaguarda de Inteligência. Se falhar, você cria um objeto, criatura ou outro fenômeno fantasmagórico que não seja maior que um Cubo de 3 m e que só é perceptível ao alvo pela duração. O fantasma inclui som, temperatura e outros estímulos. O alvo pode usar a ação Estudar para examinar o fantasma com um teste de Inteligência (Investigação) contra a CD da sua magia. Se o teste tiver sucesso, o alvo percebe que o fantasma é uma ilusão, e a magia termina. Enquanto estiver afetado pela magia, o alvo trata o fantasma como se fosse real e racionaliza quaisquer resultados ilógicos de interagir com ele. Por exemplo, se o alvo pisar em uma ponte fantasmagórica e sobreviver à queda, ele acredita que a ponte existe e que algo mais causou a queda. Um alvo afetado pode até sofrer dano da ilusão se o fantasma representar uma criatura ou perigo perigoso. Em cada um dos seus turnos, tal fantasma pode causar 2d8 de dano psíquico ao alvo se ele estiver na área do fantasma ou a até 1,5 m dele. O alvo percebe o dano como de um tipo apropriado à ilusão.","superior":""},
  {"en":"Gaseous Form","nome":"Forma gasosa","nivel":3,"escola":"Transmutação","tempo":"1 ação","alcance":"Toque","duracao":"Concentração, até 1 hora","componentes":"V, S, M (um pedaço de gaze)","concentracao":true,"ritual":false,"classes":["Feiticeiro","Bruxo","Mago"],"teste":"Salvaguarda de Constituição","dano":"","gatilho":"","texto":"Uma criatura voluntária que você tocar assume a forma de uma nuvem de névoa, junto com tudo o que ela estiver vestindo e carregando, pela duração. A magia termina no alvo se ele cair a 0 Pontos de Vida ou se ele usar uma ação Magia para encerrar a magia em si mesmo. Nessa forma, o único meio de movimento do alvo é um Deslocamento de Voo de 3 m, e ele pode pairar. O alvo pode entrar e ocupar o espaço de outra criatura. O alvo tem Resistência a dano Contundente, Perfurante e Cortante; tem Imunidade à condição Caído; e tem Vantagem em salvaguardas de Força, Destreza e Constituição. O alvo pode passar por aberturas estreitas, mas trata líquidos como se fossem superfícies sólidas. O alvo não pode falar nem manipular objetos, e quaisquer objetos que ele estivesse carregando ou segurando não podem ser largados, usados nem alvo de qualquer outra interação. Por fim, o alvo não pode atacar nem conjurar magias.","superior":"Você pode escolher uma criatura adicional como alvo para cada nível do espaço de magia acima de 3."},
  {"en":"Animal Shapes","nome":"Formas animais","nivel":8,"escola":"Transmutação","tempo":"1 ação","alcance":"9 m","duracao":"24 horas","componentes":"V, S","concentracao":false,"ritual":false,"classes":["Druida"],"teste":"","dano":"","gatilho":"","texto":"Escolha qualquer quantidade de criaturas dispostas que você possa ver ao alcance. Cada alvo se transforma em uma Fera Grande ou menor à sua escolha, com Nível de Desafio 4 ou menor. Você pode escolher uma forma diferente para cada alvo. Em turnos posteriores, você pode realizar uma ação Magia para transformar os alvos novamente. As estatísticas de jogo do alvo são substituídas pelas estatísticas da Fera escolhida, mas o alvo mantém seu tipo de criatura, Pontos de Vida, Dados de Vida, alinhamento, capacidade de comunicação e valores de Inteligência, Sabedoria e Carisma. As ações do alvo são limitadas pela anatomia da forma de Fera, e ele não pode conjurar magias. O equipamento do alvo se funde à nova forma, e o alvo não pode usar nenhum desse equipamento enquanto estiver nessa forma. O alvo ganha uma quantidade de Pontos de Vida Temporários igual aos Pontos de Vida da primeira forma em que se transforma. Esses Pontos de Vida Temporários desaparecem, caso restem, quando a magia acaba. A transformação dura pela duração ou até o alvo encerrá-la com uma ação bônus.","superior":""},
  {"en":"Meld into Stone","nome":"Fundir-se à pedra","nivel":3,"escola":"Transmutação","tempo":"1 ação","alcance":"Toque","duracao":"8 horas","componentes":"V, S","concentracao":false,"ritual":true,"classes":["Clérigo","Druida","Patrulheiro"],"teste":"","dano":"6d6 energia","gatilho":"","texto":"Você entra em um objeto ou superfície de pedra grande o bastante para conter totalmente o seu corpo, fundindo você e seu equipamento com a pedra pela duração. Você deve tocar a pedra para fazer isso. Nada da sua presença permanece visível ou de outro modo detectável por sentidos não mágicos. Enquanto fundido com a pedra, você não pode ver o que ocorre do lado de fora, e quaisquer testes de Sabedoria (Percepção) que fizer para ouvir sons do lado de fora são feitos com Desvantagem. Você continua ciente da passagem do tempo e pode conjurar magias em si mesmo enquanto fundido na pedra. Você pode usar 1,5 m de movimento para sair da pedra pelo lugar onde entrou, o que encerra a magia. Fora isso, você não pode se mover. Dano físico leve à pedra não o prejudica, mas sua destruição parcial ou uma mudança em sua forma (a ponto de você não caber mais nela) expulsa você e causa 6d6 de dano de energia a você. A destruição completa da pedra (ou sua transmutação em outra substância) expulsa você e causa 50 de dano de energia a você. Se for expulso, você se move para o espaço desocupado mais próximo de onde entrou e fica com a condição Caído.","superior":""},
  {"en":"Glyph of Warding","nome":"Glifo de proteção","nivel":3,"escola":"Abjuração","tempo":"1 hora","alcance":"Toque","duracao":"Até ser dissipada ou ativada","componentes":"V, S, M (diamante em pó que valha 200+ PO, que a magia consome)","concentracao":false,"ritual":false,"classes":["Bardo","Clérigo","Mago"],"teste":"","dano":"","gatilho":"","texto":"Você inscreve um glifo que mais tarde libera um efeito mágico. Você o inscreve em uma superfície (como uma mesa ou um trecho de piso) ou dentro de um objeto que possa ser fechado (como um livro ou baú) para ocultar o glifo. O glifo pode cobrir uma área de no máximo 3 m de diâmetro. Se a superfície ou o objeto for movido a mais de 3 m de onde você conjurou esta magia, o glifo se quebra, e a magia termina sem ser ativada.\n\nO glifo é quase imperceptível e exige um teste bem-sucedido de Sabedoria (Percepção) contra a CD de salvaguarda da sua magia para ser notado.\n\nAo inscrever o glifo, você define seu gatilho e escolhe se ele é uma runa explosiva ou um glifo de magia, conforme explicado abaixo.\n\n**_Definir o Gatilho._** Você decide o que ativa o glifo ao conjurar a magia. Para glifos inscritos em uma superfície, gatilhos comuns incluem tocar ou pisar no glifo, remover outro objeto que o cubra ou aproximar-se dele a uma certa distância. Para glifos inscritos dentro de um objeto, gatilhos comuns incluem abrir esse objeto ou ver o glifo. Quando um glifo é ativado, esta magia termina.\n\nVocê pode refinar o gatilho para que apenas criaturas de certos tipos o ativem (por exemplo, o glifo poderia ser definido para afetar Aberrações). Você também pode definir condições para criaturas que não ativam o glifo, como aquelas que disserem uma certa senha.\n\n**_Runa Explosiva._** Quando ativado, o glifo irrompe com energia mágica em uma Esfera de 6 m de raio centrada no glifo. Cada criatura na área faz uma salvaguarda de Destreza. Uma criatura sofre 5d8 de dano de ácido, frio, fogo, elétrico ou trovejante (à sua escolha ao criar o glifo) se falhar na salvaguarda, ou metade desse dano se tiver sucesso.\n\n**_Glifo de Magia._** Você pode armazenar no glifo uma magia preparada de nível 3 ou inferior, conjurando-a como parte da criação do glifo. A magia deve ter como alvo uma única criatura ou uma área. A magia armazenada não tem efeito imediato quando conjurada dessa forma.\n\nQuando o glifo é ativado, a magia armazenada entra em efeito. Se a magia tiver um alvo, ela tem como alvo a criatura que ativou o glifo. Se a magia afetar uma área, a área é centrada nessa criatura. Se a magia invocar criaturas Hostis ou criar objetos ou armadilhas nocivos, eles surgem o mais próximo possível do intruso e o atacam. Se a magia exigir Concentração, ela dura até o fim de sua duração completa.","superior":"O dano de uma runa explosiva aumenta em 1d8 para cada nível do espaço de magia acima de 3. Se você criar um glifo de magia, pode armazenar qualquer magia de até o mesmo nível do espaço de magia que você usar para Glifo de Proteção."},
  {"en":"Globe of Invulnerability","nome":"Globo de invulnerabilidade","nivel":6,"escola":"Abjuração","tempo":"1 ação","alcance":"Pessoal","duracao":"Concentração, até 1 minuto","componentes":"V, S, M (uma conta de vidro)","concentracao":true,"ritual":false,"classes":["Feiticeiro","Mago"],"teste":"","dano":"","gatilho":"","texto":"Uma barreira imóvel e cintilante surge em uma Emanação de 3 m ao seu redor e permanece pela duração. Qualquer magia de nível 5 ou inferior conjurada de fora da barreira não pode afetar nada dentro dela. Tal magia pode escolher como alvo criaturas e objetos dentro da barreira, mas não tem efeito sobre eles. Da mesma forma, a área dentro da barreira é excluída das áreas de efeito criadas por tais magias.","superior":"A barreira bloqueia magias de 1 nível a mais para cada nível do espaço de magia acima de 6."},
  {"en":"Searing Smite","nome":"Golpe ardente","nivel":1,"escola":"Evocação","tempo":"1 ação bônus","alcance":"Pessoal","duracao":"1 minuto","componentes":"V","concentracao":false,"ritual":false,"classes":["Paladino"],"teste":"Salvaguarda de Constituição","dano":"1d6 fogo","gatilho":"","texto":"Ao acertar o alvo, ele sofre 1d6 extra de dano de fogo do ataque. No início de cada um de seus turnos até a magia terminar, o alvo sofre 1d6 de dano de fogo e depois realiza uma salvaguarda de Constituição. Em caso de falha, a magia continua. Em caso de sucesso, a magia termina.","superior":"Todo o dano aumenta em 1d6 para cada nível do espaço de magia acima de 1."},
  {"en":"True Strike","nome":"Golpe verdadeiro","nivel":0,"escola":"Adivinhação","tempo":"1 ação","alcance":"Pessoal","duracao":"Instantânea","componentes":"S, M (uma arma com a qual você tenha proficiência e que valha 1+ PC)","concentracao":false,"ritual":false,"classes":["Bardo","Feiticeiro","Bruxo","Mago"],"teste":"","dano":"","gatilho":"","texto":"Guiado por um lampejo de intuição mágica, você faz um ataque com a arma usada na conjuração da magia. O ataque usa o seu atributo de conjuração nas jogadas de ataque e de dano, em vez de usar Força ou Destreza. Se o ataque causar dano, ele pode ser dano radiante ou o tipo de dano normal da arma (à sua escolha).","superior":"Quer você cause dano radiante ou o tipo de dano normal da arma, o ataque causa dano radiante extra quando você alcança os níveis 5 (1d6), 11 (2d6) e 17 (3d6)."},
  {"en":"Goodberry","nome":"Goodberry","nivel":1,"escola":"Conjuração","tempo":"1 ação","alcance":"Pessoal","duracao":"24 horas","componentes":"V, S, M (um ramo de visco)","concentracao":false,"ritual":false,"classes":["Druida","Patrulheiro"],"teste":"","dano":"","gatilho":"","texto":"Dez bagas surgem em sua mão e são imbuídas de magia pela duração. Uma criatura pode usar uma ação bônus para comer uma baga. Comer uma baga restaura 1 Ponto de Vida, e a baga fornece nutrição suficiente para sustentar uma criatura por um dia. Bagas não comidas desaparecem quando a magia termina.","superior":""},
  {"en":"Grease","nome":"Graxa","nivel":1,"escola":"Conjuração","tempo":"1 ação","alcance":"18 m","duracao":"1 minuto","componentes":"V, S, M (um pedaço de toucinho ou manteiga)","concentracao":false,"ritual":false,"classes":["Feiticeiro","Mago"],"teste":"Salvaguarda de Destreza","dano":"","gatilho":"","texto":"Graxa não inflamável cobre o chão em um quadrado de 3 m centrado em um ponto ao alcance e o transforma em Terreno Difícil pela duração. Quando a graxa surge, cada criatura em pé em sua área deve ter sucesso em uma salvaguarda de Destreza ou ficará com a condição Caído. Uma criatura que entrar na área ou terminar seu turno nela também deve ter sucesso nessa salvaguarda ou cairá.","superior":""},
  {"en":"Guards and Wards","nome":"Guardas e proteções","nivel":6,"escola":"Abjuração","tempo":"1 hora","alcance":"Toque","duracao":"24 horas","componentes":"V, S, M (uma haste de prata que valha 10+ PO)","concentracao":false,"ritual":false,"classes":["Bardo","Mago"],"teste":"","dano":"","gatilho":"","texto":"Você cria uma proteção que resguarda até 225 metros quadrados de área de piso. A área protegida pode ter até 6 m de altura, e você a modela como um quadrado de 15 m, cem quadrados contíguos de 1,5 m ou vinte e cinco quadrados contíguos de 3 m.\n\nAo conjurar esta magia, você pode especificar indivíduos que não são afetados pelos efeitos da magia. Você também pode especificar uma senha que, quando dita em voz alta a até 1,5 m da área protegida, torna quem a disser imune aos efeitos dela.\n\nA magia cria os efeitos abaixo dentro da área protegida. Dissipar Magia não tem efeito sobre Guardas e Proteções em si, mas cada um dos efeitos a seguir pode ser dissipado. Se todos os quatro forem dissipados, Guardas e Proteções termina. Se você conjurar a magia todos os dias por 365 dias na mesma área, a magia passa a durar até que todos os seus efeitos sejam dissipados.\n\n**_Corredores._** Névoa preenche todos os corredores protegidos, deixando-os Muito Obscurecidos. Além disso, em cada interseção ou passagem bifurcada que ofereça uma escolha de direção, há 50 por cento de chance de que uma criatura que não seja você acredite estar indo na direção oposta à que escolheu.\n\n**_Portas._** Todas as portas da área protegida são trancadas magicamente, como se seladas pela magia *Tranca Arcana*. Além disso, você pode cobrir até dez portas com uma ilusão para que pareçam trechos comuns de parede.\n\n**_Escadas._** Teias preenchem todas as escadas da área protegida, de cima a baixo, como na magia *Teia*. Esses fios voltam a crescer em 10 minutos se forem destruídos enquanto *Guardas e Proteções* durar.\n\n**_Outro Efeito de Magia._** Coloque um dos seguintes efeitos mágicos dentro da área protegida:\n\n- *Luzes Dançantes* em quatro corredores, com um programa simples que as luzes repetem enquanto Guardas e Proteções durar\n- *Boca Mágica* em dois locais\n- *Nuvem Fétida* em dois locais (os vapores retornam em 10 minutos se forem dispersados enquanto Guardas e Proteções durar) - Lufada de Vento em um corredor ou sala (o vento sopra continuamente enquanto a magia durar)\n- *Sugestão* em um quadrado de 1,5 m; qualquer criatura que entrar nesse quadrado recebe a sugestão mentalmente","superior":""},
  {"en":"Guardian of Faith","nome":"Guardião da fé","nivel":4,"escola":"Conjuração","tempo":"1 ação","alcance":"9 m","duracao":"8 horas","componentes":"V","concentracao":false,"ritual":false,"classes":["Clérigo"],"teste":"Salvaguarda de Destreza","dano":"","gatilho":"","texto":"Um guardião espectral Grande surge e paira pela duração em um espaço desocupado que você possa ver ao alcance. O guardião ocupa esse espaço e é invulnerável, e surge em uma forma apropriada para a sua divindade ou panteão. Qualquer inimigo que se mover para um espaço a até 3 m do guardião pela primeira vez em um turno, ou iniciar seu turno ali, faz uma salvaguarda de Destreza, sofrendo 20 de dano Radiante se falhar ou metade desse dano se tiver sucesso. O guardião desaparece quando tiver causado um total de 60 de dano.","superior":""},
  {"en":"Harm","nome":"Harm","nivel":6,"escola":"Necromancia","tempo":"1 ação","alcance":"18 m","duracao":"Instantânea","componentes":"V, S","concentracao":false,"ritual":false,"classes":["Clérigo"],"teste":"Salvaguarda de Constituição","dano":"14d6 necrótico","gatilho":"","texto":"Você libera magia virulenta sobre uma criatura que você possa ver ao alcance. O alvo faz uma salvaguarda de Constituição. Se falhar, ele sofre 14d6 de dano Necrótico, e seu máximo de Pontos de Vida é reduzido em uma quantidade igual ao dano Necrótico sofrido. Se tiver sucesso, ele sofre apenas metade do dano. Esta magia não pode reduzir o máximo de Pontos de Vida de um alvo abaixo de 1.","superior":""},
  {"en":"Heroism","nome":"Heroísmo","nivel":1,"escola":"Encantamento","tempo":"1 ação","alcance":"Toque","duracao":"Concentração, até 1 minuto","componentes":"V, S","concentracao":true,"ritual":false,"classes":["Bardo","Paladino"],"teste":"","dano":"","gatilho":"","texto":"Uma criatura voluntária que você tocar é imbuída de bravura. Até a magia terminar, a criatura é imune à condição Amedrontado e recebe Pontos de Vida Temporários iguais ao seu modificador de atributo de conjuração no início de cada um de seus turnos.","superior":"Você pode escolher uma criatura adicional como alvo para cada nível do espaço de magia acima de 1."},
  {"en":"Identify","nome":"Identificação","nivel":1,"escola":"Adivinhação","tempo":"1 minuto","alcance":"Toque","duracao":"Instantânea","componentes":"V, S, M (uma pérola que valha 100+ PO)","concentracao":false,"ritual":true,"classes":["Bardo","Mago"],"teste":"","dano":"","gatilho":"","texto":"Você toca um objeto durante toda a conjuração da magia. Se o objeto for um item mágico ou algum outro objeto mágico, você descobre suas propriedades e como usá-las, se ele exige Sintonização e quantas cargas possui, se tiver alguma. Você descobre se alguma magia contínua está afetando o item e quais são. Se o item foi criado por uma magia, você descobre o nome dessa magia. Se, em vez disso, você tocar uma criatura durante toda a conjuração, descobre quais magias contínuas, se houver, estão afetando-a no momento.","superior":""},
  {"en":"Minor Illusion","nome":"Ilusão menor","nivel":0,"escola":"Ilusão","tempo":"1 ação","alcance":"9 m","duracao":"1 minuto","componentes":"S, M (um pedaço de lã)","concentracao":false,"ritual":false,"classes":["Bardo","Feiticeiro","Bruxo","Mago"],"teste":"","dano":"","gatilho":"","texto":"Você cria um som ou a imagem de um objeto ao alcance que dura pela duração. Veja as descrições abaixo para os efeitos de cada um. A ilusão termina se você conjurar esta magia novamente. Se uma criatura usar a ação Estudar para examinar o som ou a imagem, ela pode determinar que é uma ilusão com um teste bem-sucedido de Inteligência (Investigação) contra a CD da sua magia. Se uma criatura perceber que a ilusão é uma ilusão, ela se torna tênue para essa criatura.\n\n**_Som._** Se você criar um som, seu volume pode variar de um sussurro a um grito. Pode ser a sua voz, a voz de outra pessoa, o rugido de um leão, o rufar de tambores ou qualquer outro som que você escolher. O som continua sem diminuir durante toda a duração, ou você pode produzir sons distintos em momentos diferentes antes de a magia acabar.\n\n**_Imagem._** Se você criar a imagem de um objeto, como uma cadeira, pegadas de lama ou um pequeno baú, ela deve ter no máximo um Cubo de 1,5 m. A imagem não pode produzir som, luz, cheiro nem qualquer outro efeito sensorial. A interação física com a imagem revela que ela é uma ilusão, já que as coisas a atravessam.","superior":""},
  {"en":"Programmed Illusion","nome":"Ilusão programada","nivel":6,"escola":"Ilusão","tempo":"1 ação","alcance":"36 m","duracao":"Até ser dissipada","componentes":"V, S, M (pó de jade que valha 25+ PO)","concentracao":false,"ritual":false,"classes":["Bardo","Mago"],"teste":"","dano":"","gatilho":"","texto":"Você cria uma ilusão de um objeto, uma criatura ou algum outro fenômeno visível ao alcance que é ativada quando ocorre um gatilho específico. A ilusão é imperceptível até então. Ela não deve ser maior que um Cubo de 9 m, e você decide ao conjurar a magia como a ilusão se comporta e que sons ela emite. Essa performance roteirizada pode durar até 5 minutos. Quando o gatilho que você especificou ocorre, a ilusão passa a existir e se apresenta da maneira que você descreveu. Quando a ilusão termina a apresentação, ela desaparece e permanece dormente por 10 minutos, após os quais pode ser ativada novamente. O gatilho pode ser tão geral ou tão detalhado quanto você quiser, mas deve se basear em fenômenos visuais ou sonoros que ocorram a até 9 m da área. Por exemplo, você poderia criar uma ilusão de si mesmo que aparece e afasta outros que tentem abrir uma porta com armadilha. A interação física com a imagem revela que ela é ilusória, pois coisas podem atravessá-la. Uma criatura que realize a ação Estudar para examinar a imagem pode determinar que é uma ilusão com um teste bem-sucedido de Inteligência (Investigação) contra a CD de salvaguarda da sua magia. Se uma criatura perceber a ilusão como ela realmente é, a criatura pode ver através da imagem, e qualquer ruído que ela faça soa oco para a criatura.","superior":""},
  {"en":"Mirror Image","nome":"Imagem espelhada","nivel":2,"escola":"Ilusão","tempo":"1 ação","alcance":"Pessoal","duracao":"1 minuto","componentes":"V, S","concentracao":false,"ritual":false,"classes":["Bardo","Feiticeiro","Bruxo","Mago"],"teste":"Ataque de magia","dano":"","gatilho":"","texto":"Três duplicatas ilusórias de você aparecem no seu espaço. Até a magia acabar, as duplicatas se movem com você e imitam suas ações, trocando de posição de modo que é impossível saber qual imagem é a real. Cada vez que uma criatura acertar você com uma jogada de ataque durante a duração da magia, role um d6 para cada duplicata restante. Se qualquer um dos d6 resultar em 3 ou mais, uma das duplicatas é atingida no seu lugar, e a duplicata é destruída. Fora isso, as duplicatas ignoram todos os outros danos e efeitos. A magia termina quando as três duplicatas forem destruídas. Uma criatura não é afetada por esta magia se tiver a condição Cego, Visão às Cegas ou Visão Verdadeira.","superior":""},
  {"en":"Major Image","nome":"Imagem maior","nivel":3,"escola":"Ilusão","tempo":"1 ação","alcance":"36 m","duracao":"Concentração, até 10 minutos","componentes":"V, S, M (um pouco de lã)","concentracao":true,"ritual":false,"classes":["Bardo","Feiticeiro","Bruxo","Mago"],"teste":"","dano":"","gatilho":"","texto":"Você cria a imagem de um objeto, de uma criatura ou de algum outro fenômeno visível que não seja maior que um Cubo de 6 m. A imagem surge em um ponto que você possa ver ao alcance e dura pela duração. Ela parece real, incluindo sons, cheiros e temperatura apropriados à coisa retratada, mas não pode causar dano nem condições. Se você estiver ao alcance da ilusão, pode usar uma ação Magia para fazer a imagem se mover para qualquer outro ponto ao alcance. Conforme a imagem muda de lugar, você pode alterar a aparência dela para que seus movimentos pareçam naturais para a imagem. Por exemplo, se você criar a imagem de uma criatura e movê-la, pode alterá-la para que pareça estar andando. Da mesma forma, você pode fazer a ilusão emitir sons diferentes em momentos diferentes, chegando até a fazê-la manter uma conversa, por exemplo. A interação física com a imagem revela que ela é uma ilusão, pois as coisas a atravessam. Uma criatura que use a ação Estudar para examinar a imagem pode determinar que ela é uma ilusão com um sucesso em um teste de Inteligência (Investigação) contra a CD de salvaguarda da sua magia. Se uma criatura perceber a ilusão como ela é, a criatura enxerga através da imagem, e as outras qualidades sensoriais dela ficam tênues para a criatura.","superior":"A magia dura até ser dissipada, sem exigir Concentração, se conjurada com um espaço de magia de nível 4 ou superior."},
  {"en":"Silent Image","nome":"Imagem silenciosa","nivel":1,"escola":"Ilusão","tempo":"1 ação","alcance":"18 m","duracao":"Concentração, até 10 minutos","componentes":"V, S, M (um pedaço de lã)","concentracao":true,"ritual":false,"classes":["Bardo","Feiticeiro","Mago"],"teste":"","dano":"","gatilho":"","texto":"Você cria a imagem de um objeto, uma criatura ou algum outro fenômeno visível que não seja maior que um Cubo de 4,5 m. A imagem aparece em um ponto ao alcance e dura pela duração. A imagem é puramente visual; não é acompanhada de som, cheiro ou outros efeitos sensoriais. Com uma ação Magia, você pode fazer a imagem se mover para qualquer ponto ao alcance. Conforme a imagem muda de lugar, você pode alterar a aparência dela para que seus movimentos pareçam naturais para ela. Por exemplo, se você criar a imagem de uma criatura e movê-la, pode alterá-la para que pareça estar andando. A interação física com a imagem revela que ela é uma ilusão, pois as coisas a atravessam. Uma criatura que realize a ação Estudar para examinar a imagem pode determinar que ela é uma ilusão com um sucesso em um teste de Inteligência (Investigação) contra a CD da sua magia. Se uma criatura perceber a ilusão como tal, ela consegue enxergar através da imagem.","superior":""},
  {"en":"Hold Monster","nome":"Imobilizar monstro","nivel":5,"escola":"Encantamento","tempo":"1 ação","alcance":"27 m","duracao":"Concentração, até 1 minuto","componentes":"V, S, M (um pedaço reto de ferro)","concentracao":true,"ritual":false,"classes":["Bardo","Feiticeiro","Bruxo","Mago"],"teste":"Salvaguarda de Sabedoria","dano":"","gatilho":"","texto":"Escolha uma criatura que você possa ver ao alcance. O alvo deve ter sucesso em uma salvaguarda de Sabedoria ou ficará com a condição Paralisado pela duração. No final de cada um de seus turnos, o alvo repete a salvaguarda, encerrando a magia em si mesmo se tiver sucesso.","superior":"Você pode escolher uma criatura adicional como alvo para cada nível do espaço de magia acima de 5."},
  {"en":"Hold Person","nome":"Imobilizar pessoa","nivel":2,"escola":"Encantamento","tempo":"1 ação","alcance":"18 m","duracao":"Concentração, até 1 minuto","componentes":"V, S, M (um pedaço reto de ferro)","concentracao":true,"ritual":false,"classes":["Bardo","Clérigo","Druida","Feiticeiro","Bruxo","Mago"],"teste":"Salvaguarda de Sabedoria","dano":"","gatilho":"","texto":"Escolha um Humanoide que você possa ver ao alcance. O alvo deve ter sucesso em uma salvaguarda de Sabedoria ou ficará com a condição Paralisado pela duração. No final de cada um de seus turnos, o alvo repete a salvaguarda, encerrando a magia em si mesmo se tiver sucesso.","superior":"Você pode escolher um Humanoide adicional como alvo para cada nível do espaço de magia acima de 2."},
  {"en":"Inflict Wounds","nome":"Infligir ferimentos","nivel":1,"escola":"Necromancia","tempo":"1 ação","alcance":"Toque","duracao":"Instantânea","componentes":"V, S","concentracao":false,"ritual":false,"classes":["Clérigo"],"teste":"Salvaguarda de Constituição","dano":"2d10 necrótico","gatilho":"","texto":"Uma criatura que você toca faz uma salvaguarda de Constituição, sofrendo 2d10 de dano necrótico se falhar, ou metade desse dano se tiver sucesso.","superior":"O dano aumenta em 1d10 para cada nível do espaço de magia acima de 1."},
  {"en":"Giant Insect","nome":"Inseto gigante","nivel":4,"escola":"Conjuração","tempo":"1 ação","alcance":"18 m","duracao":"Concentração, até 10 minutos","componentes":"V, S","concentracao":true,"ritual":false,"classes":["Druida"],"teste":"","dano":"","gatilho":"","texto":"Você invoca uma centopeia, aranha ou vespa gigante (escolhida ao conjurar a magia). Ela se manifesta em um espaço desocupado que você possa ver ao alcance e usa o bloco de estatísticas Inseto Gigante. A forma que você escolher determina certos detalhes no bloco de estatísticas. A criatura desaparece quando cai a 0 Pontos de Vida ou quando a magia termina. A criatura é uma aliada sua e de seus aliados. Em combate, a criatura compartilha a sua contagem de Iniciativa, mas realiza o turno dela imediatamente após o seu. Ela obedece aos seus comandos verbais (nenhuma ação necessária da sua parte). Se você não der nenhum, ela realiza a ação Esquivar e usa seu movimento para evitar perigo.","superior":"Use o nível do espaço de magia como o nível da magia no bloco de estatísticas."},
  {"en":"Invisibility","nome":"Invisibilidade","nivel":2,"escola":"Ilusão","tempo":"1 ação","alcance":"Toque","duracao":"Concentração, até 1 hora","componentes":"V, S, M (um cílio em goma arábica)","concentracao":true,"ritual":false,"classes":["Bardo","Feiticeiro","Bruxo","Mago"],"teste":"Ataque de magia","dano":"","gatilho":"","texto":"Uma criatura que você toca tem a condição Invisível até a magia terminar. A magia termina antecipadamente logo depois que o alvo faz uma jogada de ataque, causa dano ou conjura uma magia.","superior":"Você pode escolher uma criatura adicional como alvo para cada nível do espaço de magia acima de 2."},
  {"en":"Greater Invisibility","nome":"Invisibilidade maior","nivel":4,"escola":"Ilusão","tempo":"1 ação","alcance":"Toque","duracao":"Concentração, até 1 minuto","componentes":"V, S","concentracao":true,"ritual":false,"classes":["Bardo","Feiticeiro","Mago"],"teste":"","dano":"","gatilho":"","texto":"Uma criatura que você tocar fica com a condição Invisível até a magia terminar.","superior":""},
  {"en":"Instant Summons","nome":"Invocação instantânea","nivel":6,"escola":"Conjuração","tempo":"1 minuto","alcance":"Toque","duracao":"Até ser dissipada","componentes":"V, S, M (uma safira que valha 1.000+ PO)","concentracao":false,"ritual":true,"classes":["Mago"],"teste":"","dano":"","gatilho":"","texto":"Você toca a safira usada na conjuração e um objeto que pese 5 kg ou menos e cuja maior dimensão seja 1,8 m ou menos. A magia deixa uma marca Invisível nesse objeto e inscreve invisivelmente o nome do objeto na safira. Cada vez que conjurar esta magia, você deve usar uma safira diferente. Depois disso, você pode usar uma ação Magia para dizer o nome do objeto e esmagar a safira. O objeto surge instantaneamente na sua mão, independentemente de distâncias físicas ou planares, e a magia termina. Se outra criatura estiver segurando ou carregando o objeto, esmagar a safira não o transporta; em vez disso, você descobre quem é essa criatura e onde ela está no momento.","superior":""},
  {"en":"Conjure Animals","nome":"Invocar animais","nivel":3,"escola":"Conjuração","tempo":"1 ação","alcance":"18 m","duracao":"Concentração, até 10 minutos","componentes":"V, S","concentracao":true,"ritual":false,"classes":["Druida","Patrulheiro"],"teste":"Salvaguarda de Força","dano":"3d10 cortante","gatilho":"","texto":"Você conjura espíritos da natureza que surgem como uma matilha Grande de animais espectrais e intangíveis em um espaço desocupado que você possa ver ao alcance. A matilha dura pela duração, e você escolhe a forma animal dos espíritos, como lobos, serpentes ou aves. Você tem Vantagem em salvaguardas de Força enquanto estiver a até 1,5 m da matilha e, quando você se move em seu turno, também pode mover a matilha até 9 m para um espaço desocupado que você possa ver. Sempre que a matilha se move para a até 3 m de uma criatura que você possa ver e sempre que uma criatura que você possa ver entra em um espaço a até 3 m da matilha ou termina seu turno ali, você pode forçar essa criatura a fazer uma salvaguarda de Destreza. Se falhar, a criatura sofre 3d10 de dano cortante. Uma criatura faz essa salvaguarda apenas uma vez por turno.","superior":"O dano aumenta em 1d10 para cada nível do espaço de magia acima de 3."},
  {"en":"Conjure Celestial","nome":"Invocar celestial","nivel":7,"escola":"Conjuração","tempo":"1 ação","alcance":"27 m","duracao":"Concentração, até 10 minutos","componentes":"V, S","concentracao":true,"ritual":false,"classes":["Clérigo"],"teste":"","dano":"","gatilho":"","texto":"Você conjura um espírito dos Planos Superiores, que se manifesta como um pilar de luz em um Cilindro de 3 m de raio e 12 m de altura centrado em um ponto ao alcance. Para cada criatura que você possa ver no Cilindro, escolha qual dessas luzes brilha sobre ela: Até a magia terminar, Luz Plena preenche o Cilindro e, quando você se move em seu turno, também pode mover o Cilindro até 9 m. Sempre que o Cilindro se move para o espaço de uma criatura que você possa ver e sempre que uma criatura que você possa ver entra no Cilindro ou termina seu turno ali, você pode banhá-la em uma das luzes. Uma criatura pode ser afetada por esta magia apenas uma vez por turno.","superior":"A cura e o dano aumentam em 1d12 para cada nível do espaço de magia acima de 7."},
  {"en":"Conjure Minor Elementals","nome":"Invocar elementais menores","nivel":4,"escola":"Conjuração","tempo":"1 ação","alcance":"Pessoal","duracao":"Concentração, até 10 minutos","componentes":"V, S","concentracao":true,"ritual":false,"classes":["Druida","Mago"],"teste":"","dano":"2d8","gatilho":"","texto":"Você conjura espíritos dos Planos Elementais que esvoaçam ao seu redor em uma Emanação de 4,5 m pela duração. Até a magia terminar, qualquer ataque que você faça causa 2d8 de dano extra quando você acerta uma criatura na Emanação. Esse dano é de ácido, frio, fogo ou elétrico (à sua escolha quando você faz o ataque). Além disso, o solo na Emanação é Terreno Difícil para seus inimigos.","superior":"O dano aumenta em 1d8 para cada nível do espaço de magia acima de 4."},
  {"en":"Conjure Elemental","nome":"Invocar elemental","nivel":5,"escola":"Conjuração","tempo":"1 ação","alcance":"18 m","duracao":"Concentração, até 10 minutos","componentes":"V, S","concentracao":true,"ritual":false,"classes":["Druida","Mago"],"teste":"Salvaguarda de Destreza","dano":"8d8","gatilho":"","texto":"Você conjura um espírito Grande e intangível dos Planos Elementais que surge em um espaço desocupado ao alcance. Escolha o elemento do espírito, que determina seu tipo de dano: ar (elétrico), terra (trovejante), fogo (fogo) ou água (frio). O espírito dura pela duração. Sempre que uma criatura que você possa ver entra no espaço do espírito ou começa seu turno a até 1,5 m dele, você pode forçar essa criatura a fazer uma salvaguarda de Destreza se o espírito não tiver nenhuma criatura Contida. Se falhar, o alvo sofre 8d8 de dano do tipo do espírito e tem a condição Contido até a magia terminar. No início de cada um de seus turnos, o alvo Contido repete a salvaguarda. Se falhar, o alvo sofre 4d8 de dano do tipo do espírito. Se tiver sucesso, o alvo não fica Contido pelo espírito.","superior":"O dano aumenta em 1d8 para cada nível do espaço de magia acima de 5."},
  {"en":"Conjure Fey","nome":"Invocar feérico","nivel":6,"escola":"Conjuração","tempo":"1 ação","alcance":"18 m","duracao":"Concentração, até 10 minutos","componentes":"V, S","concentracao":true,"ritual":false,"classes":["Druida"],"teste":"","dano":"3d12 psíquico","gatilho":"","texto":"Você conjura um espírito Médio da Agrestia Feérica em um espaço desocupado que você possa ver ao alcance. O espírito dura pela duração e tem a aparência de uma criatura Feérica de sua escolha. Quando o espírito surge, você pode fazer uma jogada de ataque de magia corpo a corpo contra uma criatura a até 1,5 m dele. Se acertar, o alvo sofre dano psíquico igual a 3d12 mais o modificador do seu atributo de conjuração, e o alvo tem a condição Amedrontado até o início do seu próximo turno, sendo você e o espírito a fonte do medo. Com uma ação bônus em seus turnos seguintes, você pode teletransportar o espírito para um espaço desocupado que você possa ver a até 9 m do espaço que ele deixou e fazer o ataque contra uma criatura a até 1,5 m dele.","superior":"O dano aumenta em 1d12 para cada nível do espaço de magia acima de 6."},
  {"en":"Conjure Woodland Beings","nome":"Invocar seres da floresta","nivel":4,"escola":"Conjuração","tempo":"1 ação","alcance":"Pessoal","duracao":"Concentração, até 10 minutos","componentes":"V, S","concentracao":true,"ritual":false,"classes":["Druida","Patrulheiro"],"teste":"Salvaguarda de Sabedoria","dano":"5d8 energia","gatilho":"","texto":"Você conjura espíritos da natureza que esvoaçam ao seu redor em uma Emanação de 3 m pela duração. Sempre que a Emanação entra no espaço de uma criatura que você possa ver e sempre que uma criatura que você possa ver entra na Emanação ou termina seu turno ali, você pode forçar essa criatura a fazer uma salvaguarda de Sabedoria. A criatura sofre 5d8 de dano de energia se falhar ou metade desse dano se tiver sucesso. Uma criatura faz essa salvaguarda apenas uma vez por turno. Além disso, você pode realizar a ação Desengajar como ação bônus pela duração da magia.","superior":"O dano aumenta em 1d8 para cada nível do espaço de magia acima de 4."},
  {"en":"Sequester","nome":"Isolar","nivel":7,"escola":"Transmutação","tempo":"1 ação","alcance":"Toque","duracao":"Até ser dissipada","componentes":"V, S, M (pó de gema que valha 5.000+ PO, que a magia consome)","concentracao":false,"ritual":false,"classes":["Mago"],"teste":"","dano":"","gatilho":"","texto":"Com um toque, você isola magicamente um objeto ou uma criatura voluntária. Pela duração, o alvo tem a condição Invisível e não pode ser alvo de magias de Adivinhação, detectado por magia nem observado remotamente com magia. Se o alvo for uma criatura, ela entra em estado de animação suspensa; fica com a condição Inconsciente, não envelhece e não precisa de comida, água nem ar. Você pode definir uma condição para a magia terminar antes. A condição pode ser qualquer uma que você escolher, mas deve ocorrer ou ser visível a até 1,5 km do alvo. Exemplos incluem \"após 1.000 anos\" ou \"quando a tarrasque despertar\". Esta magia também termina se o alvo sofrer qualquer dano.","superior":""},
  {"en":"Forcecage","nome":"Jaula de força","nivel":7,"escola":"Evocação","tempo":"1 ação","alcance":"30 m","duracao":"Concentração, até 1 hora","componentes":"V, S, M (pó de rubi que valha 1.500+ PO, que a magia consome)","concentracao":true,"ritual":false,"classes":["Bardo","Bruxo","Mago"],"teste":"Salvaguarda de Carisma","dano":"","gatilho":"","texto":"Uma prisão imóvel, Invisível, em forma de Cubo, composta de energia mágica, surge ao redor de uma área que você escolher ao alcance. A prisão pode ser uma gaiola ou uma caixa sólida, à sua escolha.\n\nUma prisão em forma de gaiola pode ter até 6 m de lado e é feita de barras de 1,25 cm de diâmetro espaçadas 1,25 cm entre si. Uma prisão em forma de caixa pode ter até 3 m de lado, criando uma barreira sólida que impede a passagem de qualquer matéria e bloqueia quaisquer magias conjuradas para dentro ou para fora da área.\n\nQuando você conjura a magia, qualquer criatura que esteja completamente dentro da área da gaiola fica presa. Criaturas apenas parcialmente dentro da área, ou grandes demais para caber nela, são empurradas para longe do centro da área até ficarem completamente fora dela.\n\nUma criatura dentro da gaiola não pode sair por meios não mágicos. Se a criatura tentar usar teletransporte ou viagem interplanar para sair, ela deve primeiro fazer uma salvaguarda de Carisma. Se tiver sucesso, a criatura pode usar essa magia para sair da gaiola. Se falhar, a criatura não sai da gaiola e desperdiça a magia ou o efeito. A gaiola também se estende ao Plano Etéreo, bloqueando a viagem etérea.\n\nEsta magia não pode ser dissipada por Dissipar Magia.","superior":""},
  {"en":"Maze","nome":"Labirinto","nivel":8,"escola":"Conjuração","tempo":"1 ação","alcance":"18 m","duracao":"Concentração, até 10 minutos","componentes":"V, S","concentracao":true,"ritual":false,"classes":["Mago"],"teste":"","dano":"","gatilho":"","texto":"Você bane uma criatura que possa ver ao alcance para um semiplano labiríntico. O alvo permanece lá pela duração ou até escapar do labirinto. O alvo pode usar a ação Estudar para tentar escapar. Ao fazê-lo, ele faz um teste de Inteligência (Investigação) CD 20. Com um sucesso, ele escapa, e a magia termina. Quando a magia termina, o alvo reaparece no espaço que deixou ou, se esse espaço estiver ocupado, no espaço desocupado mais próximo.","superior":""},
  {"en":"Flame Blade","nome":"Lâmina de fogo","nivel":2,"escola":"Evocação","tempo":"1 ação bônus","alcance":"Pessoal","duracao":"Concentração, até 10 minutos","componentes":"V, S, M (uma folha de sumagre)","concentracao":true,"ritual":false,"classes":["Druida","Feiticeiro"],"teste":"Ataque de magia","dano":"3d6 fogo","gatilho":"","texto":"Você evoca uma lâmina flamejante na sua mão livre. A lâmina tem tamanho e forma semelhantes aos de uma cimitarra e dura pela duração. Se você soltar a lâmina, ela desaparece, mas você pode evocá-la novamente com uma ação bônus. Com uma ação Magia, você pode fazer um ataque de magia corpo a corpo com a lâmina flamejante. Em um acerto, o alvo sofre dano de fogo igual a 3d6 mais o modificador do seu atributo de conjuração. A lâmina flamejante emite Luz Plena em um raio de 3 m e Penumbra por mais 3 m.","superior":"O dano aumenta em 1d6 para cada nível do espaço de magia acima de 2."},
  {"en":"Slow","nome":"Lentidão","nivel":3,"escola":"Transmutação","tempo":"1 ação","alcance":"36 m","duracao":"Concentração, até 1 minuto","componentes":"V, S, M (uma gota de melaço)","concentracao":true,"ritual":false,"classes":["Bardo","Feiticeiro","Mago"],"teste":"Salvaguarda de Sabedoria","dano":"","gatilho":"","texto":"Você altera o tempo ao redor de até seis criaturas à sua escolha em um Cubo de 12 m ao alcance. Cada alvo deve ter sucesso em uma salvaguarda de Sabedoria ou será afetado por esta magia pela duração. O Deslocamento de um alvo afetado é reduzido à metade, ele sofre uma penalidade de −2 na CA e nas salvaguardas de Destreza e não pode realizar reações. Nos turnos dele, ele pode realizar uma ação ou uma ação bônus, não ambas, e só pode fazer um ataque se realizar a ação Atacar. Se ele conjurar uma magia com um componente Somático, há 25 por cento de chance de a magia falhar porque o alvo faz os gestos da magia devagar demais. Um alvo afetado repete a salvaguarda no final de cada um dos turnos dele, encerrando a magia sobre si com um sucesso.","superior":""},
  {"en":"Levitate","nome":"Levitação","nivel":2,"escola":"Transmutação","tempo":"1 ação","alcance":"18 m","duracao":"Concentração, até 10 minutos","componentes":"V, S, M (uma mola de metal)","concentracao":true,"ritual":false,"classes":["Feiticeiro","Mago"],"teste":"Salvaguarda de Constituição","dano":"","gatilho":"","texto":"Uma criatura ou objeto solto à sua escolha que você possa ver ao alcance sobe verticalmente até 6 m e permanece suspenso ali pela duração. A magia pode levitar um objeto que pese até 250 kg. Uma criatura involuntária que tenha sucesso em uma salvaguarda de Constituição não é afetada. O alvo só pode se mover empurrando ou puxando um objeto ou superfície fixa ao alcance (como uma parede ou um teto), o que lhe permite se mover como se estivesse escalando. Você pode mudar a altitude do alvo em até 6 m em qualquer direção no seu turno. Se você for o alvo, pode subir ou descer como parte do seu movimento. Caso contrário, você pode usar uma ação Magia para mover o alvo, que deve permanecer dentro do alcance da magia. Quando a magia termina, o alvo flutua suavemente até o chão, se ainda estiver no ar.","superior":""},
  {"en":"Freedom of Movement","nome":"Liberdade de movimento","nivel":4,"escola":"Abjuração","tempo":"1 ação","alcance":"Toque","duracao":"1 hora","componentes":"V, S, M (uma tira de couro)","concentracao":false,"ritual":false,"classes":["Bardo","Clérigo","Druida","Patrulheiro"],"teste":"Salvaguarda de Constituição","dano":"10d6 frio","gatilho":"","texto":"Você toca uma criatura disposta. Pela duração, o movimento do alvo não é afetado por Terreno Difícil, e magias e outros efeitos mágicos não podem reduzir o Deslocamento do alvo nem fazer com que ele fique com as condições Paralisado ou Contido. O alvo também tem Deslocamento de Natação igual ao seu Deslocamento.\n\nAlém disso, o alvo pode gastar 1,5 m de movimento para escapar automaticamente de amarras não mágicas, como algemas ou uma criatura que lhe imponha a condição Agarrado.","superior":"Você pode escolher uma criatura adicional para cada nível do espaço de magia acima de 4."},
  {"en":"Tongues","nome":"Línguas","nivel":3,"escola":"Adivinhação","tempo":"1 ação","alcance":"Toque","duracao":"1 hora","componentes":"V, M (um zigurate em miniatura)","concentracao":false,"ritual":false,"classes":["Bardo","Clérigo","Feiticeiro","Bruxo","Mago"],"teste":"","dano":"","gatilho":"","texto":"Esta magia concede à criatura que você tocar a capacidade de entender qualquer idioma falado ou por sinais que ela ouça ou veja. Além disso, quando o alvo se comunica falando ou por sinais, qualquer criatura que conheça pelo menos um idioma consegue entendê-lo se puder ouvir a fala ou ver os sinais.","superior":""},
  {"en":"Locate Animals or Plants","nome":"Localizar animais ou plantas","nivel":2,"escola":"Adivinhação","tempo":"1 ação","alcance":"Pessoal","duracao":"Instantânea","componentes":"V, S, M (pelo de um cão de caça)","concentracao":false,"ritual":true,"classes":["Bardo","Druida","Patrulheiro"],"teste":"","dano":"","gatilho":"","texto":"Descreva ou diga o nome de um tipo específico de Fera, criatura Planta ou planta não mágica. Você descobre a direção e a distância até a criatura ou planta mais próxima desse tipo em um raio de 7,5 km, se houver alguma presente.","superior":""},
  {"en":"Locate Creature","nome":"Localizar criatura","nivel":4,"escola":"Adivinhação","tempo":"1 ação","alcance":"Pessoal","duracao":"Concentração, até 1 hora","componentes":"V, S, M (pelo de um cão de caça)","concentracao":true,"ritual":false,"classes":["Bardo","Clérigo","Druida","Paladino","Patrulheiro","Mago"],"teste":"","dano":"","gatilho":"","texto":"Descreva ou diga o nome de uma criatura que lhe seja familiar. Você sente a direção até a localização da criatura se ela estiver a até 300 m de você. Se a criatura estiver se movendo, você sabe a direção do movimento dela. A magia pode localizar uma criatura específica conhecida por você ou a criatura mais próxima de um tipo específico (como um humano ou um unicórnio), se você já tiver visto uma criatura assim de perto, a até 9 m, pelo menos uma vez. Se a criatura que você descreveu ou nomeou estiver em outra forma, como sob os efeitos de uma magia Carne para Pedra ou Metamorfose, esta magia não localiza a criatura. Esta magia não pode localizar uma criatura se qualquer espessura de chumbo bloquear um caminho direto entre você e a criatura.","superior":""},
  {"en":"Locate Object","nome":"Localizar objeto","nivel":2,"escola":"Adivinhação","tempo":"1 ação","alcance":"Pessoal","duracao":"Concentração, até 10 minutos","componentes":"V, S, M (um galho bifurcado)","concentracao":true,"ritual":false,"classes":["Bardo","Clérigo","Druida","Paladino","Patrulheiro","Mago"],"teste":"","dano":"","gatilho":"","texto":"Descreva ou diga o nome de um objeto que lhe seja familiar. Você sente a direção até a localização do objeto se ele estiver a até 300 m de você. Se o objeto estiver em movimento, você sabe a direção do movimento dele. A magia pode localizar um objeto específico conhecido por você se você já o tiver visto de perto, a até 9 m, pelo menos uma vez. Como alternativa, a magia pode localizar o objeto mais próximo de um tipo específico, como certo tipo de vestimenta, joia, mobília, ferramenta ou arma. Esta magia não pode localizar um objeto se qualquer espessura de chumbo bloquear um caminho direto entre você e o objeto.","superior":""},
  {"en":"Gust of Wind","nome":"Lufada de vento","nivel":2,"escola":"Evocação","tempo":"1 ação","alcance":"Pessoal","duracao":"Concentração, até 1 minuto","componentes":"V, S, M (uma semente de leguminosa)","concentracao":true,"ritual":false,"classes":["Druida","Patrulheiro","Feiticeiro","Mago"],"teste":"Salvaguarda de Força","dano":"","gatilho":"","texto":"Uma Linha de vento forte com 18 m de comprimento e 3 m de largura sopra de você em uma direção que você escolher pela duração. Cada criatura na Linha deve ter sucesso em uma salvaguarda de Força ou será empurrada 4,5 m para longe de você em uma direção que acompanhe a Linha. Uma criatura que terminar seu turno na Linha deve fazer a mesma salvaguarda. Qualquer criatura na Linha deve gastar 0,6 m de movimento para cada 0,3 m que se mover ao se aproximar de você. A rajada dispersa gás ou vapor e apaga velas e chamas desprotegidas semelhantes na área. Ela faz chamas protegidas, como as de lanternas, dançarem violentamente e tem 50 por cento de chance de apagá-las. Como ação bônus em seus turnos seguintes, você pode mudar a direção em que a Linha sopra de você.","superior":""},
  {"en":"Light","nome":"Luz","nivel":0,"escola":"Evocação","tempo":"1 ação","alcance":"Toque","duracao":"1 hora","componentes":"V, M (um vaga-lume ou musgo fosforescente)","concentracao":false,"ritual":false,"classes":["Bardo","Clérigo","Feiticeiro","Mago"],"teste":"","dano":"","gatilho":"","texto":"Você toca um objeto Grande ou menor que não esteja sendo vestido nem carregado por outra pessoa. Até a magia terminar, o objeto emite Luz Plena em um raio de 6 m e Penumbra por mais 6 m. A luz pode ter a cor que você quiser. Cobrir o objeto com algo opaco bloqueia a luz. A magia termina se você a conjurar novamente.","superior":""},
  {"en":"Daylight","nome":"Luz do dia","nivel":3,"escola":"Evocação","tempo":"1 ação","alcance":"18 m","duracao":"1 hora","componentes":"V, S","concentracao":false,"ritual":false,"classes":["Clérigo","Druida","Paladino","Patrulheiro","Feiticeiro"],"teste":"","dano":"","gatilho":"","texto":"Pela duração, luz solar se espalha a partir de um ponto ao alcance e preenche uma Esfera de 18 m de raio. A área da luz solar é de Luz Plena e emite Penumbra por mais 18 m. Como alternativa, você conjura a magia sobre um objeto que não esteja sendo vestido nem carregado, fazendo a luz solar preencher uma Emanação de 18 m com origem nesse objeto. Cobrir esse objeto com algo opaco, como uma tigela ou um elmo, bloqueia a luz solar. Se qualquer parte da área desta magia se sobrepuser a uma área de Escuridão criada por uma magia de nível 3 ou inferior, essa outra magia é dissipada.","superior":""},
  {"en":"Dancing Lights","nome":"Luzes dançantes","nivel":0,"escola":"Ilusão","tempo":"1 ação","alcance":"36 m","duracao":"Concentração, até 1 minuto","componentes":"V, S, M (um pouco de fósforo)","concentracao":true,"ritual":false,"classes":["Bardo","Feiticeiro","Mago"],"teste":"","dano":"","gatilho":"","texto":"Você cria até quatro luzes do tamanho de tochas ao alcance, fazendo-as parecer tochas, lanternas ou orbes brilhantes que flutuam pela duração. Como alternativa, você combina as quatro luzes em uma única forma Média brilhante, vagamente humanoide. Qualquer que seja a forma escolhida, cada luz emite Penumbra em um raio de 3 m. Como ação bônus, você pode mover as luzes até 18 m para um espaço ao alcance. Uma luz deve estar a até 6 m de outra luz criada por esta magia, e uma luz se dissipa se ultrapassar o alcance da magia.","superior":""},
  {"en":"Magic Jar","nome":"Magic Jar","nivel":6,"escola":"Necromancia","tempo":"1 minuto","alcance":"Pessoal","duracao":"Até ser dissipada","componentes":"V, S, M (uma gema, cristal ou relicário que valha 500+ PO)","concentracao":false,"ritual":false,"classes":["Mago"],"teste":"Salvaguarda de Carisma","dano":"","gatilho":"","texto":"Seu corpo cai em estado catatônico enquanto sua alma o deixa e entra no recipiente que você usou como componente material da magia. Enquanto sua alma habita o recipiente, você tem consciência do que o cerca como se estivesse no espaço do recipiente. Você não pode se mover nem usar reações. A única ação que você pode realizar é projetar sua alma até 30 m para fora do recipiente, seja retornando ao seu corpo vivo (encerrando a magia) ou tentando possuir o corpo de um Humanoide. Você pode tentar possuir qualquer Humanoide a até 30 m de você que possa ver (criaturas protegidas por uma magia Proteção Contra o Bem e o Mal ou Círculo Mágico não podem ser possuídas). O alvo faz uma salvaguarda de Carisma. Com uma falha, sua alma entra no corpo do alvo, e a alma do alvo fica presa no recipiente. Com um sucesso, o alvo resiste aos seus esforços de possuí-lo, e você não pode tentar possuí-lo novamente por 24 horas. Ao possuir o corpo de uma criatura, você o controla. Seus Pontos de Vida, Dados de Vida, Força, Destreza, Constituição, Deslocamento e sentidos são substituídos pelos da criatura. Você mantém, de resto, suas estatísticas de jogo. Enquanto isso, a alma da criatura possuída pode perceber a partir do recipiente usando seus próprios sentidos, mas não pode se mover e fica Incapacitada. Enquanto possui um corpo, você pode usar uma ação Magia para retornar do corpo hospedeiro ao recipiente, se ele estiver a até 30 m de você, devolvendo a alma da criatura hospedeira ao corpo dela. Se o corpo hospedeiro morrer enquanto você estiver nele, a criatura morre, e você faz uma salvaguarda de Carisma contra a sua própria CD de conjuração. Com um sucesso, você retorna ao recipiente se ele estiver a até 30 m de você. Caso contrário, você morre. Se o recipiente for destruído ou a magia terminar, sua alma retorna ao seu corpo. Se o seu corpo estiver a mais de 30 m de você ou estiver morto, você morre. Se a alma de outra criatura estiver no recipiente quando ele for destruído, a alma da criatura retorna ao corpo dela se o corpo estiver vivo e a até 30 m. Caso contrário, essa criatura morre. Quando a magia termina, o recipiente é destruído.","superior":""},
  {"en":"Hex","nome":"Maldição","nivel":1,"escola":"Encantamento","tempo":"1 ação bônus","alcance":"27 m","duracao":"Concentração, até 1 hora","componentes":"V, S, M (o olho petrificado de uma salamandra)","concentracao":true,"ritual":false,"classes":["Bruxo"],"teste":"Ataque de magia","dano":"1d6 necrótico","gatilho":"","texto":"Você lança uma maldição sobre uma criatura que você possa ver ao alcance. Até a magia terminar, você causa 1d6 de dano Necrótico extra ao alvo sempre que o acertar com uma jogada de ataque. Além disso, escolha um atributo ao conjurar a magia. O alvo tem Desvantagem em testes de atributo feitos com o atributo escolhido. Se o alvo cair a 0 Pontos de Vida antes de esta magia terminar, você pode usar uma ação bônus em um turno posterior para amaldiçoar uma nova criatura.","superior":"Sua Concentração pode durar mais com um espaço de magia de nível 2 (até 4 horas), 3–4 (até 8 horas) ou 5+ (24 horas)."},
  {"en":"Magnificent Mansion","nome":"Mansão magnífica","nivel":7,"escola":"Conjuração","tempo":"1 minuto","alcance":"90 m","duracao":"24 horas","componentes":"V, S, M (uma porta em miniatura que valha 15+ PO)","concentracao":false,"ritual":false,"classes":["Bardo","Mago"],"teste":"","dano":"","gatilho":"","texto":"Você conjura uma porta cintilante ao alcance que dura pela duração. A porta leva a uma morada extradimensional e tem 1,5 m de largura e 3 m de altura. Você e qualquer criatura que designar ao conjurar a magia podem entrar na morada extradimensional enquanto a porta permanecer aberta. Você pode abri-la ou fechá-la (sem precisar de ação) se estiver a até 9 m dela. Enquanto fechada, a porta é imperceptível. Além da porta há um magnífico saguão com inúmeros aposentos adiante. A atmosfera da morada é limpa, fresca e quente. Você pode criar a planta que quiser para a morada, mas ela não pode exceder 50 Cubos de 3 m contíguos. O lugar é mobiliado e decorado como você escolher. Ele contém comida suficiente para servir um banquete de nove pratos para até 100 pessoas. Mobílias e outros objetos criados por esta magia se dissipam em fumaça se forem removidos dela. Uma equipe de 100 servos quase transparentes atende todos que entram. Você determina a aparência desses servos e suas vestes. Eles são invulneráveis e obedecem aos seus comandos. Cada servo pode realizar tarefas que um humano poderia realizar, mas não pode atacar nem realizar qualquer ação que prejudique diretamente outra criatura. Assim, os servos podem buscar coisas, limpar, remendar, dobrar roupas, acender fogueiras, servir comida, servir vinho e assim por diante. Os servos não podem sair da morada. Quando a magia termina, quaisquer criaturas ou objetos deixados dentro do espaço extradimensional são expulsos para os espaços desocupados mais próximos da entrada.","superior":""},
  {"en":"Arcane Hand","nome":"Mão arcana","nivel":5,"escola":"Evocação","tempo":"1 ação","alcance":"36 m","duracao":"Concentração, até 1 minuto","componentes":"V, S, M (uma casca de ovo e uma luva)","concentracao":true,"ritual":false,"classes":["Feiticeiro","Mago"],"teste":"","dano":"","gatilho":"","texto":"Você cria uma mão Grande de energia mágica cintilante em um espaço desocupado que você possa ver ao alcance. A mão dura pela duração e se move sob seu comando, imitando os movimentos da sua própria mão. A mão é um objeto que tem CA 20 e Pontos de Vida iguais ao seu máximo de Pontos de Vida. Se ela cair a 0 Pontos de Vida, a magia termina. A mão não ocupa o espaço dela. Ao conjurar a magia e com uma ação bônus em seus turnos posteriores, você pode mover a mão até 18 m e então causar um dos seguintes efeitos:\n\n**Punho Cerrado.** A mão golpeia um alvo a até 1,5 m dela. Faça uma jogada de ataque de magia corpo a corpo. Em um acerto, o alvo sofre 5d8 de dano de energia.\n\n**Mão Poderosa.** A mão tenta empurrar uma criatura Enorme ou menor a até 1,5 m dela. O alvo deve ter sucesso em uma salvaguarda de Força, ou a mão empurra o alvo até 1,5 m mais uma quantidade de metros igual a 1,5 vez o modificador do seu atributo de conjuração. A mão se move com o alvo, permanecendo a até 1,5 m dele.\n\n**Mão Agarradora.** A mão tenta agarrar uma criatura Enorme ou menor a até 1,5 m dela. O alvo deve ter sucesso em uma salvaguarda de Destreza, ou o alvo fica com a condição Agarrado, com uma CD de escape igual à CD de salvaguarda da sua magia. Enquanto a mão agarra o alvo, você pode usar uma ação bônus para fazer a mão esmagá-lo, causando ao alvo dano contundente igual a 4d6 mais o modificador do seu atributo de conjuração.\n\n**Mão Interposta.** A mão concede a você Cobertura Parcial contra ataques e outros efeitos que se originem do espaço dela ou que passem por ele. Além disso, o espaço dela conta como Terreno Difícil para seus inimigos.","superior":"O dano do Punho Cerrado aumenta em 2d8 e o dano da Mão Agarradora aumenta em 2d6 para cada nível do espaço de magia acima de 5."},
  {"en":"Burning Hands","nome":"Mãos flamejantes","nivel":1,"escola":"Evocação","tempo":"1 ação","alcance":"Pessoal","duracao":"Instantânea","componentes":"V, S","concentracao":false,"ritual":false,"classes":["Feiticeiro","Mago"],"teste":"Salvaguarda de Destreza","dano":"3d6 fogo","gatilho":"","texto":"Uma fina lâmina de chamas jorra de você. Cada criatura em um Cone de 4,5 m faz uma salvaguarda de Destreza, sofrendo 3d6 de dano de fogo se falhar ou metade desse dano se tiver sucesso. Objetos inflamáveis no Cone que não estejam sendo vestidos ou carregados começam a queimar.","superior":"O dano aumenta em 1d6 para cada nível do espaço de magia acima de 1."},
  {"en":"Mage Hand","nome":"Mãos mágicas","nivel":0,"escola":"Conjuração","tempo":"1 ação","alcance":"9 m","duracao":"1 minuto","componentes":"V, S","concentracao":false,"ritual":false,"classes":["Bardo","Feiticeiro","Bruxo","Mago"],"teste":"","dano":"","gatilho":"","texto":"Uma mão espectral e flutuante surge em um ponto que você escolher ao alcance. A mão dura pela duração. A mão desaparece se algum dia ficar a mais de 9 m de você ou se você conjurar esta magia novamente. Quando você conjura a magia, pode usar a mão para manipular um objeto, abrir uma porta ou recipiente destrancado, guardar ou retirar um item de um recipiente aberto, ou derramar o conteúdo de um frasco. Como uma ação Magia nos seus turnos seguintes, você pode controlar a mão dessa forma novamente. Como parte dessa ação, você pode mover a mão até 9 m. A mão não pode atacar, ativar itens mágicos nem carregar mais de 5 kg.","superior":""},
  {"en":"Hunter's Mark","nome":"Marca do caçador","nivel":1,"escola":"Adivinhação","tempo":"1 ação bônus","alcance":"27 m","duracao":"Concentração, até 1 hora","componentes":"V","concentracao":true,"ritual":false,"classes":["Patrulheiro"],"teste":"Ataque de magia","dano":"1d6 energia","gatilho":"","texto":"Você marca magicamente uma criatura que você possa ver ao alcance como sua presa. Até a magia terminar, você causa 1d6 de dano de Energia extra ao alvo sempre que o acertar com uma jogada de ataque. Você também tem Vantagem em qualquer teste de Sabedoria (Percepção ou Sobrevivência) que fizer para encontrá-lo. Se o alvo cair a 0 Pontos de Vida antes de esta magia terminar, você pode usar uma ação bônus para mover a marca para uma nova criatura que você possa ver ao alcance.","superior":"Sua Concentração pode durar mais com um espaço de magia de nível 3–4 (até 8 horas) ou 5+ (até 24 horas)."},
  {"en":"Fear","nome":"Medo","nivel":3,"escola":"Ilusão","tempo":"1 ação","alcance":"Pessoal","duracao":"Concentração, até 1 minuto","componentes":"V, S, M (uma pena branca)","concentracao":true,"ritual":false,"classes":["Bardo","Feiticeiro","Bruxo","Mago"],"teste":"Salvaguarda de Sabedoria","dano":"","gatilho":"","texto":"Cada criatura em um Cone de 9 m deve ter sucesso em uma salvaguarda de Sabedoria ou largará o que estiver segurando e ficará com a condição Amedrontado pela duração. Uma criatura Amedrontada realiza a ação Disparada e se afasta de você pela rota mais segura em cada um dos seus turnos, a menos que não haja para onde se mover. Se a criatura terminar o turno em um espaço onde não tenha linha de visão para você, ela faz uma salvaguarda de Sabedoria. Se tiver sucesso, a magia termina nessa criatura.","superior":""},
  {"en":"Animal Messenger","nome":"Mensageiro animal","nivel":2,"escola":"Encantamento","tempo":"1 ação","alcance":"9 m","duracao":"24 horas","componentes":"V, S, M (um pedaço de comida)","concentracao":false,"ritual":true,"classes":["Bardo","Druida","Patrulheiro"],"teste":"Salvaguarda de Carisma","dano":"","gatilho":"","texto":"Uma Fera Miúda à sua escolha que você possa ver ao alcance deve ter sucesso em uma salvaguarda de Carisma, ou tentará entregar uma mensagem por você (se o Nível de Desafio do alvo não for 0, ele tem sucesso automaticamente). Você especifica um local que já visitou e um destinatário que corresponda a uma descrição geral, como \"uma pessoa vestida com o uniforme da guarda da cidade\" ou \"um anão ruivo usando um chapéu pontudo\". Você também comunica uma mensagem de até vinte e cinco palavras. A Fera viaja pela duração em direção ao local especificado, percorrendo cerca de 37,5 km por 24 horas, ou 75 km se a Fera puder voar. Quando a Fera chega, ela entrega sua mensagem à criatura que você descreveu, imitando a sua comunicação. Se a Fera não chegar ao destino antes de a magia acabar, a mensagem é perdida, e a Fera retorna ao local onde você conjurou a magia.","superior":"A duração da magia aumenta em 48 horas para cada nível do espaço de magia acima de 2."},
  {"en":"Message","nome":"Mensagem","nivel":0,"escola":"Transmutação","tempo":"1 ação","alcance":"36 m","duracao":"1 rodada","componentes":"S, M (um fio de cobre)","concentracao":false,"ritual":false,"classes":["Bardo","Druida","Feiticeiro","Mago"],"teste":"","dano":"","gatilho":"","texto":"Você aponta para uma criatura ao alcance e sussurra uma mensagem. O alvo (e somente o alvo) ouve a mensagem e pode responder com um sussurro que apenas você ouve. Você pode conjurar esta magia através de objetos sólidos se conhecer o alvo e souber que ele está além da barreira. Silêncio mágico; 30 cm de pedra, metal ou madeira; ou uma fina folha de chumbo bloqueiam a magia.","superior":""},
  {"en":"Mind Blank","nome":"Mente vazia","nivel":8,"escola":"Abjuração","tempo":"1 ação","alcance":"Toque","duracao":"24 horas","componentes":"V, S","concentracao":false,"ritual":false,"classes":["Bardo","Mago"],"teste":"","dano":"","gatilho":"","texto":"Até a magia acabar, uma criatura voluntária que você tocar tem Imunidade a dano psíquico e à condição Enfeitiçado. O alvo também não é afetado por nada que perceba suas emoções ou alinhamento, leia seus pensamentos ou detecte magicamente sua localização, e nenhuma magia, nem mesmo Desejo, pode obter informações sobre o alvo, observá-lo à distância ou controlar sua mente.","superior":""},
  {"en":"Polymorph","nome":"Metamorfose","nivel":4,"escola":"Transmutação","tempo":"1 ação","alcance":"18 m","duracao":"Concentração, até 1 hora","componentes":"V, S, M (um casulo de lagarta)","concentracao":true,"ritual":false,"classes":["Bardo","Druida","Feiticeiro","Mago"],"teste":"Salvaguarda de Sabedoria","dano":"","gatilho":"","texto":"Você tenta transformar uma criatura que você possa ver ao alcance em uma Fera. O alvo deve ter sucesso em uma salvaguarda de Sabedoria ou assume a forma de uma Fera pela duração. Essa forma pode ser qualquer Fera que você escolher que tenha um Nível de Desafio igual ou menor que o do alvo (ou o nível do alvo se ele não tiver Nível de Desafio). As estatísticas de jogo do alvo são substituídas pelo bloco de estatísticas da Fera escolhida, mas o alvo mantém seu alinhamento, personalidade, tipo de criatura, Pontos de Vida e Dados de Pontos de Vida. Veja a seção \"Animais\" de \"Monstros\" para uma amostra de blocos de estatísticas de Feras. O alvo recebe um número de Pontos de Vida Temporários igual aos Pontos de Vida da forma de Fera. Esses Pontos de Vida Temporários desaparecem, se restar algum, quando a magia termina. A magia termina antes para o alvo se ele não tiver mais Pontos de Vida Temporários. O alvo é limitado nas ações que pode realizar pela anatomia de sua nova forma, e não pode falar nem conjurar magias. Os equipamentos do alvo se fundem à nova forma. A criatura não pode usar nem se beneficiar de nenhum desses equipamentos.","superior":""},
  {"en":"True Polymorph","nome":"Metamorfose verdadeira","nivel":9,"escola":"Transmutação","tempo":"1 ação","alcance":"9 m","duracao":"Concentração, até 1 hora","componentes":"V, S, M (uma gota de mercúrio, uma porção de goma arábica e um fio de fumaça)","concentracao":true,"ritual":false,"classes":["Bardo","Bruxo","Mago"],"teste":"Salvaguarda de Sabedoria","dano":"","gatilho":"","texto":"Escolha uma criatura ou um objeto não mágico que você possa ver ao alcance. A criatura se transforma em uma criatura diferente ou em um objeto não mágico, ou o objeto se transforma em uma criatura (o objeto não pode estar vestido nem carregado). A transformação dura pela duração ou até o alvo morrer ou ser destruído, mas, se você mantiver Concentração nesta magia pela duração completa, ela dura até ser dissipada.\n\nUma criatura involuntária pode fazer uma salvaguarda de Sabedoria e, se tiver sucesso, não é afetada por esta magia.\n\n**_Criatura em Criatura._** Se você transformar uma criatura em outro tipo de criatura, a nova forma pode ser de qualquer tipo que você escolher que tenha um Nível de Desafio igual ou inferior ao Nível de Desafio ou nível do alvo. As estatísticas de jogo do alvo são substituídas pelo bloco de estatísticas da nova forma, mas ele mantém seus Pontos de Vida, Dados de Vida, alinhamento e personalidade.\n\nO alvo ganha uma quantidade de Pontos de Vida Temporários igual aos Pontos de Vida da nova forma. Esses Pontos de Vida Temporários desaparecem, caso restem, quando a magia termina. O alvo fica limitado, nas ações que pode realizar, pela anatomia de sua nova forma, e não pode falar nem conjurar magias.\n\nO equipamento do alvo se funde à nova forma. A criatura não pode usar nem se beneficiar de nenhum desses equipamentos.\n\n**_Objeto em Criatura._** Você pode transformar um objeto em qualquer tipo de criatura, desde que o tamanho da criatura não seja maior que o do objeto e que a criatura tenha Nível de Desafio 9 ou inferior. A criatura é Amistosa para você e seus aliados. Em combate, ela age imediatamente após o seu turno e obedece aos seus comandos.\n\nSe a magia durar mais de uma hora, você deixa de controlar a criatura. Ela pode continuar Amistosa para você, dependendo de como você a tratou.\n\n**_Criatura em Objeto._** Se você transformar uma criatura em um objeto, ela se transforma nessa forma junto com tudo o que veste e carrega, desde que o tamanho do objeto não seja maior que o da criatura. As estatísticas da criatura se tornam as do objeto, e a criatura não tem memória do tempo passado nessa forma depois que a magia termina e ela volta ao normal.","superior":""},
  {"en":"Mind Spike","nome":"Mind Spike","nivel":2,"escola":"Adivinhação","tempo":"1 ação","alcance":"36 m","duracao":"Concentração, até 1 hora","componentes":"S","concentracao":true,"ritual":false,"classes":["Feiticeiro","Bruxo","Mago"],"teste":"Salvaguarda de Sabedoria","dano":"3d8 psíquico","gatilho":"","texto":"Você crava um espinho de energia psiônica na mente de uma criatura que você possa ver ao alcance. O alvo faz uma salvaguarda de Sabedoria, sofrendo 3d8 de dano psíquico se falhar, ou metade desse dano se tiver sucesso. Se falhar na salvaguarda, você também sempre sabe a localização do alvo até a magia acabar, mas apenas enquanto vocês dois estiverem no mesmo plano de existência. Enquanto você tiver esse conhecimento, o alvo não pode se esconder de você, e, se tiver a condição Invisível, não recebe nenhum benefício dessa condição contra você.","superior":"O dano aumenta em 1d8 para cada nível do espaço de magia acima de 2."},
  {"en":"Mirage Arcane","nome":"Miragem arcana","nivel":7,"escola":"Ilusão","tempo":"1 minuto","alcance":"Visão","duracao":"10 dias","componentes":"V, S","concentracao":false,"ritual":false,"classes":["Bardo","Druida","Mago"],"teste":"","dano":"","gatilho":"","texto":"Você faz o terreno em uma área de até 1,5 km quadrado parecer, soar, cheirar e até ser sentido como outro tipo de terreno. Campos abertos ou uma estrada podem ser feitos para parecer um pântano, colina, fenda ou algum outro terreno acidentado ou intransponível. Um lago pode parecer um prado gramado, um precipício uma encosta suave, ou uma ravina cheia de pedras uma estrada larga e lisa. Da mesma forma, você pode alterar a aparência de estruturas ou acrescentá-las onde não haja nenhuma. A magia não disfarça, oculta nem acrescenta criaturas. A ilusão inclui elementos audíveis, visuais, táteis e olfativos, então pode transformar terreno limpo em Terreno Difícil (ou vice-versa) ou de outra forma impedir o movimento pela área. Qualquer pedaço do terreno ilusório (como uma pedra ou graveto) que seja removido da área da magia desaparece imediatamente. Criaturas com Visão Verdadeira enxergam através da ilusão a forma real do terreno; porém, todos os outros elementos da ilusão permanecem, então, embora a criatura saiba da presença da ilusão, ela ainda pode interagir fisicamente com ela.","superior":""},
  {"en":"Geas","nome":"Missão","nivel":5,"escola":"Encantamento","tempo":"1 minuto","alcance":"18 m","duracao":"30 dias","componentes":"V","concentracao":false,"ritual":false,"classes":["Bardo","Clérigo","Druida","Paladino","Mago"],"teste":"Salvaguarda de Sabedoria","dano":"5d10 psíquico","gatilho":"","texto":"Você dá um comando verbal a uma criatura que você possa ver ao alcance, ordenando que ela execute algum serviço ou se abstenha de uma ação ou de uma linha de atividade, conforme você decidir. O alvo deve ter sucesso em uma salvaguarda de Sabedoria ou ficará com a condição Enfeitiçado pela duração. O alvo tem sucesso automaticamente se não puder entender o seu comando. Enquanto Enfeitiçada, a criatura sofre 5d10 de dano Psíquico se agir de maneira diretamente contrária ao seu comando. Ela sofre esse dano no máximo uma vez por dia. Você pode dar qualquer comando que escolher, exceto uma atividade que resultaria em morte certa. Se você der um comando suicida, a magia termina. Uma magia Remover Maldição, Restauração Maior ou Desejo encerra esta magia.","superior":"Se você usar um espaço de magia de nível 7 ou 8, a duração é de 365 dias. Se você usar um espaço de magia de nível 9, a magia dura até ser encerrada por uma das magias mencionadas acima."},
  {"en":"Magic Missile","nome":"Mísseis mágicos","nivel":1,"escola":"Evocação","tempo":"1 ação","alcance":"36 m","duracao":"Instantânea","componentes":"V, S","concentracao":false,"ritual":false,"classes":["Feiticeiro","Mago"],"teste":"","dano":"1d4 + 1 energia","gatilho":"","texto":"Você cria três dardos brilhantes de energia mágica. Cada dardo atinge uma criatura à sua escolha que você possa ver ao alcance. Um dardo causa 1d4 + 1 de dano de energia ao alvo. Os dardos atingem simultaneamente, e você pode direcioná-los para atingir uma criatura ou várias.","superior":"A magia cria um dardo a mais para cada nível do espaço de magia acima de 1."},
  {"en":"Modify Memory","nome":"Modificar memória","nivel":5,"escola":"Encantamento","tempo":"1 ação","alcance":"9 m","duracao":"Concentração, até 1 minuto","componentes":"V, S","concentracao":true,"ritual":false,"classes":["Bardo","Mago"],"teste":"Salvaguarda de Sabedoria","dano":"","gatilho":"","texto":"Você tenta remodelar as memórias de outra criatura. Uma criatura que você possa ver ao alcance faz uma salvaguarda de Sabedoria. Se você estiver lutando contra a criatura, ela tem Vantagem na salvaguarda. Se falhar, o alvo tem a condição Enfeitiçado pela duração. Enquanto Enfeitiçado dessa forma, o alvo também tem a condição Incapacitado e não percebe o que o cerca, embora possa ouvir você. Se sofrer qualquer dano ou for alvo de outra magia, esta magia termina e nenhuma memória é modificada. Enquanto este encantamento durar, você pode afetar a memória do alvo sobre um evento que ele vivenciou nas últimas 24 horas e que durou no máximo 10 minutos. Você pode eliminar permanentemente toda a memória do evento, permitir que o alvo se lembre do evento com perfeita clareza, mudar a memória dele sobre os detalhes do evento ou criar uma memória de algum outro evento. Você deve falar com o alvo para descrever como as memórias dele são afetadas, e ele deve ser capaz de entender seu idioma para que as memórias modificadas se fixem. A mente dele preenche quaisquer lacunas nos detalhes da sua descrição. Se a magia terminar antes de você terminar de descrever as memórias modificadas, a memória da criatura não é alterada. Caso contrário, as memórias modificadas se fixam quando a magia termina. Uma memória modificada não afeta necessariamente o comportamento de uma criatura, particularmente se a memória contradiz as inclinações naturais, o alinhamento ou as crenças da criatura. Uma memória modificada ilógica, como uma falsa lembrança de quanto a criatura gostou de nadar em ácido, é descartada como um pesadelo. O Mestre pode considerar uma memória modificada absurda demais para afetar uma criatura. Uma magia Remover Maldição ou Restauração Maior conjurada no alvo restaura a verdadeira memória da criatura.","superior":"Você pode alterar as memórias do alvo sobre um evento ocorrido até 7 dias atrás (espaço de magia de nível 6), 30 dias atrás (espaço de magia de nível 7), 365 dias atrás (espaço de magia de nível 8) ou em qualquer momento do passado da criatura (espaço de magia de nível 9)."},
  {"en":"Stone Shape","nome":"Moldar rochas","nivel":4,"escola":"Transmutação","tempo":"1 ação","alcance":"Toque","duracao":"Instantânea","componentes":"V, S, M (argila macia)","concentracao":false,"ritual":false,"classes":["Clérigo","Druida","Mago"],"teste":"","dano":"","gatilho":"","texto":"Você toca um objeto de pedra de tamanho Médio ou menor ou uma seção de pedra de no máximo 1,5 m em qualquer dimensão e o molda na forma que quiser. Por exemplo, você poderia moldar uma rocha grande em uma arma, estátua ou arca, ou abrir uma pequena passagem em uma parede de 1,5 m de espessura. Você também poderia moldar uma porta de pedra ou seu batente para selar a porta. O objeto que você criar pode ter até duas dobradiças e um trinco, mas detalhes mecânicos mais finos não são possíveis.","superior":""},
  {"en":"Phantom Steed","nome":"Montaria fantasmagórica","nivel":3,"escola":"Ilusão","tempo":"1 minuto","alcance":"9 m","duracao":"1 hora","componentes":"V, S","concentracao":false,"ritual":true,"classes":["Mago"],"teste":"","dano":"","gatilho":"","texto":"Uma criatura Grande, quase real, semelhante a um cavalo aparece no chão em um espaço desocupado à sua escolha ao alcance. Você decide a aparência da criatura, e ela está equipada com sela, freio e rédeas. Qualquer equipamento criado pela magia some em uma nuvem de fumaça se for levado a mais de 3 m de distância do corcel. Pela duração, você ou uma criatura que você escolher pode montar o corcel. O corcel usa o bloco de estatísticas do Cavalo de Montaria (veja \"Monstros\"), exceto que tem Deslocamento de 30 m e pode percorrer 20 km em uma hora. Quando a magia termina, o corcel desaparece gradualmente, dando ao cavaleiro 1 minuto para desmontar. A magia termina antes se o corcel sofrer qualquer dano.","superior":""},
  {"en":"Move Earth","nome":"Mover terra","nivel":6,"escola":"Transmutação","tempo":"1 ação","alcance":"36 m","duracao":"Concentração, até 2 horas","componentes":"V, S, M (uma pá em miniatura)","concentracao":true,"ritual":false,"classes":["Druida","Feiticeiro","Mago"],"teste":"","dano":"","gatilho":"","texto":"Escolha uma área de terreno de no máximo 12 m de lado ao alcance. Você pode remodelar terra, areia ou argila na área da maneira que escolher pela duração. Você pode elevar ou rebaixar o nível da área, criar ou aterrar uma vala, erguer ou nivelar uma parede ou formar um pilar. A extensão dessas mudanças não pode exceder metade da maior dimensão da área. Por exemplo, se você afetar um quadrado de 12 m, pode criar um pilar de até 6 m de altura, elevar ou rebaixar o nível do quadrado em até 6 m, cavar uma vala de até 6 m de profundidade, e assim por diante. Essas mudanças levam 10 minutos para se completar. Como a transformação do terreno ocorre lentamente, as criaturas na área normalmente não podem ser presas ou feridas pelo movimento do solo. No final de cada 10 minutos que você passar concentrado na magia, você pode escolher uma nova área de terreno para afetar ao alcance. Esta magia não pode manipular pedra natural nem construções de pedra. Rochas e estruturas se deslocam para acomodar o novo terreno. Se a forma como você modela o terreno tornar uma estrutura instável, ela pode desabar. Da mesma forma, esta magia não afeta diretamente o crescimento das plantas. A terra movida leva consigo quaisquer plantas.","superior":""},
  {"en":"Plane Shift","nome":"Mudança de plano","nivel":7,"escola":"Conjuração","tempo":"1 ação","alcance":"Toque","duracao":"Instantânea","componentes":"V, S, M (uma haste de metal bifurcada que valha 250+ PO e sintonizada a um plano de existência)","concentracao":false,"ritual":false,"classes":["Clérigo","Druida","Feiticeiro","Bruxo","Mago"],"teste":"","dano":"","gatilho":"","texto":"Você e até oito criaturas voluntárias que deem as mãos em círculo são transportados para um plano de existência diferente. Você pode especificar um destino em termos gerais, como uma cidade específica no Plano Elemental do Fogo ou um palácio no segundo nível dos Nove Infernos, e você aparece nesse destino ou perto dele, conforme determinado pelo Mestre. Como alternativa, se você conhecer a sequência de sigilos de um círculo de teletransporte em outro plano de existência, esta magia pode levar você a esse círculo. Se o círculo de teletransporte for pequeno demais para abrigar todas as criaturas que você transportou, elas aparecem nos espaços desocupados mais próximos ao lado do círculo.","superior":""},
  {"en":"Shapechange","nome":"Mudar de forma","nivel":9,"escola":"Transmutação","tempo":"1 ação","alcance":"Pessoal","duracao":"Concentração, até 1 hora","componentes":"V, S, M (um diadema de jade que valha 1.500+ PO)","concentracao":true,"ritual":false,"classes":["Druida","Mago"],"teste":"","dano":"","gatilho":"","texto":"Você se transforma em outra criatura pela duração ou até realizar uma ação Magia para se transformar em uma forma elegível diferente. A nova forma deve ser de uma criatura que tenha um Nível de Desafio não superior ao seu nível ou Nível de Desafio. Você deve ter visto esse tipo de criatura antes, e ela não pode ser um Constructo nem um Morto-vivo. Ao conjurar a magia, você ganha um número de Pontos de Vida Temporários igual aos Pontos de Vida da primeira forma em que se transformar. Esses Pontos de Vida Temporários desaparecem, se restar algum, quando a magia termina. Suas estatísticas de jogo são substituídas pelo bloco de estatísticas da forma escolhida, mas você mantém seu tipo de criatura; alinhamento; personalidade; valores de Inteligência, Sabedoria e Carisma; Pontos de Vida; Dados de Vida; proficiências; e capacidade de comunicação. Se você tiver a característica Conjuração, também a mantém. Ao se transformar, você determina se seu equipamento cai no chão ou muda de tamanho e formato para se ajustar à nova forma enquanto você estiver nela.","superior":""},
  {"en":"Wall of Force","nome":"Muralha de energia","nivel":5,"escola":"Evocação","tempo":"1 ação","alcance":"36 m","duracao":"Concentração, até 10 minutos","componentes":"V, S, M (um caco de vidro)","concentracao":true,"ritual":false,"classes":["Mago"],"teste":"","dano":"","gatilho":"","texto":"Uma parede de energia Invisível surge em um ponto que você escolher ao alcance. A parede aparece na orientação que você escolher, como uma barreira horizontal ou vertical ou inclinada. Ela pode flutuar livremente ou repousar sobre uma superfície sólida. Você pode moldá-la como uma cúpula hemisférica ou um globo com raio de até 3 m, ou pode formar uma superfície plana composta de dez painéis de 3 m por 3 m. Cada painel deve ser contíguo a outro painel. Em qualquer forma, a parede tem 6 mm de espessura e dura pela duração. Se a parede cortar o espaço de uma criatura quando aparecer, a criatura é empurrada para um lado da parede (você escolhe qual). Nada pode atravessar fisicamente a parede. Ela é imune a todo dano e não pode ser dissipada por Dissipar Magia. Porém, a magia Desintegrar destrói a parede instantaneamente. A parede também se estende até o Plano Etéreo e bloqueia a viagem etérea através dela.","superior":""},
  {"en":"Wall of Thorns","nome":"Muralha de espinhos","nivel":6,"escola":"Conjuração","tempo":"1 ação","alcance":"36 m","duracao":"Concentração, até 10 minutos","componentes":"V, S, M (um punhado de espinhos)","concentracao":true,"ritual":false,"classes":["Druida"],"teste":"Salvaguarda de Destreza","dano":"7d8 cortante perfurante","gatilho":"","texto":"Você cria uma parede de arbustos emaranhados repletos de espinhos afiados como agulhas. A parede aparece ao alcance sobre uma superfície sólida e dura pela duração. Você escolhe fazer a parede com até 18 m de comprimento, 3 m de altura e 1,5 m de espessura, ou um círculo com 6 m de diâmetro, até 6 m de altura e 1,5 m de espessura. A parede bloqueia a linha de visão. Quando a parede aparece, cada criatura em sua área faz uma salvaguarda de Destreza, sofrendo 7d8 de dano perfurante em caso de falha ou metade desse dano em caso de sucesso. Uma criatura pode atravessar a parede, embora de forma lenta e dolorosa. Para cada 30 cm que uma criatura se move através da parede, ela deve gastar 1,2 m de movimento. Além disso, na primeira vez que uma criatura entra em um espaço da parede em um turno ou termina seu turno nele, ela faz uma salvaguarda de Destreza, sofrendo 7d8 de dano cortante em caso de falha ou metade desse dano em caso de sucesso. Uma criatura faz essa salvaguarda apenas uma vez por turno.","superior":"Ambos os tipos de dano aumentam em 1d8 para cada nível do espaço de magia acima de 6."},
  {"en":"Wall of Fire","nome":"Muralha de fogo","nivel":4,"escola":"Evocação","tempo":"1 ação","alcance":"36 m","duracao":"Concentração, até 1 minuto","componentes":"V, S, M (um pedaço de carvão)","concentracao":true,"ritual":false,"classes":["Druida","Feiticeiro","Mago"],"teste":"Salvaguarda de Destreza","dano":"5d8 fogo","gatilho":"","texto":"Você cria uma parede de fogo em uma superfície sólida ao alcance. Você pode fazer a parede ter até 18 m de comprimento, 6 m de altura e 30 cm de espessura, ou uma parede em anel com até 6 m de diâmetro, 6 m de altura e 30 cm de espessura. A parede é opaca e dura pela duração. Quando a parede aparece, cada criatura em sua área faz uma salvaguarda de Destreza, sofrendo 5d8 de dano de fogo em caso de falha ou metade desse dano em caso de sucesso. Um lado da parede, escolhido por você ao conjurar a magia, causa 5d8 de dano de fogo a cada criatura que termine seu turno a até 3 m desse lado ou dentro da parede. Uma criatura sofre o mesmo dano quando entra na parede pela primeira vez em um turno ou termina seu turno nela. O outro lado da parede não causa dano.","superior":"O dano aumenta em 1d8 para cada nível do espaço de magia acima de 4."},
  {"en":"Wall of Ice","nome":"Muralha de gelo","nivel":6,"escola":"Evocação","tempo":"1 ação","alcance":"36 m","duracao":"Concentração, até 10 minutos","componentes":"V, S, M (um pedaço de quartzo)","concentracao":true,"ritual":false,"classes":["Mago"],"teste":"Salvaguarda de Destreza","dano":"10d6 fogo psíquico frio","gatilho":"","texto":"Você cria uma parede de gelo em uma superfície sólida ao alcance. Você pode moldá-la como uma cúpula hemisférica ou um globo com raio de até 3 m, ou pode formar uma superfície plana composta de dez painéis quadrados de 3 m. Cada painel deve ser contíguo a outro painel. Em qualquer forma, a parede tem 30 cm de espessura e dura pela duração. Se a parede cortar o espaço de uma criatura quando aparecer, a criatura é empurrada para um lado da parede (você escolhe qual) e faz uma salvaguarda de Destreza, sofrendo 10d6 de dano de frio em caso de falha ou metade desse dano em caso de sucesso. A parede é um objeto que pode ser danificado e, portanto, rompido. Ela tem CA 12 e 30 Pontos de Vida por seção de 3 m, além de Imunidade a dano de frio, veneno e psíquico e Vulnerabilidade a dano de fogo. Reduzir uma seção de 3 m da parede a 0 Pontos de Vida a destrói e deixa para trás uma lâmina de ar gélido no espaço que a parede ocupava. Uma criatura que atravesse a lâmina de ar gélido pela primeira vez em um turno faz uma salvaguarda de Constituição, sofrendo 5d6 de dano de frio em caso de falha ou metade desse dano em caso de sucesso.","superior":"O dano que a parede causa quando aparece aumenta em 2d6, e o dano por atravessar a lâmina de ar gélido aumenta em 1d6, para cada nível do espaço de magia acima de 6."},
  {"en":"Wall of Stone","nome":"Muralha de pedra","nivel":5,"escola":"Evocação","tempo":"1 ação","alcance":"36 m","duracao":"Concentração, até 10 minutos","componentes":"V, S, M (um cubo de granito)","concentracao":true,"ritual":false,"classes":["Druida","Feiticeiro","Mago"],"teste":"Salvaguarda de Destreza","dano":"","gatilho":"","texto":"Uma parede não mágica de pedra sólida surge em um ponto que você escolher ao alcance. A parede tem 15 cm de espessura e é composta de dez painéis de 3 m por 3 m. Cada painel deve ser contíguo a outro painel. Como alternativa, você pode criar painéis de 3 m por 6 m com apenas 7,5 cm de espessura. Se a parede cortar o espaço de uma criatura quando aparecer, a criatura é empurrada para um lado da parede (você escolhe qual). Se uma criatura fosse cercada por todos os lados pela parede (ou pela parede e outra superfície sólida), essa criatura pode fazer uma salvaguarda de Destreza. Em caso de sucesso, ela pode usar sua reação para se mover até seu Deslocamento, de modo a não ficar mais cercada pela parede. A parede pode ter qualquer forma que você desejar, embora não possa ocupar o mesmo espaço que uma criatura ou objeto. A parede não precisa ser vertical nem se apoiar em uma base firme. Ela deve, no entanto, se fundir com a pedra existente e ser sustentada solidamente por ela. Assim, você pode usar esta magia para atravessar um abismo ou criar uma rampa. Se você criar um vão com mais de 6 m de comprimento, deve reduzir à metade o tamanho de cada painel para criar apoios. Você pode moldar grosseiramente a parede para criar ameias e similares. A parede é um objeto de pedra que pode ser danificado e, portanto, rompido. Cada painel tem CA 15 e 30 Pontos de Vida para cada 2,5 cm de espessura, além de Imunidade a dano de veneno e psíquico. Reduzir um painel a 0 Pontos de Vida o destrói e pode fazer painéis conectados desabarem, a critério do Mestre. Se você mantiver sua Concentração nesta magia pela duração completa, a parede se torna permanente e não pode ser dissipada. Caso contrário, a parede desaparece quando a magia termina.","superior":""},
  {"en":"Wind Wall","nome":"Muralha de vento","nivel":3,"escola":"Evocação","tempo":"1 ação","alcance":"36 m","duracao":"Concentração, até 1 minuto","componentes":"V, S, M (um leque e uma pena)","concentracao":true,"ritual":false,"classes":["Druida","Patrulheiro"],"teste":"Salvaguarda de Força","dano":"4d8 contundente","gatilho":"","texto":"Uma parede de vento forte se ergue do chão em um ponto que você escolher ao alcance. Você pode fazer a parede ter até 15 m de comprimento, 4,5 m de altura e 30 cm de espessura. Você pode moldar a parede da forma que quiser, desde que ela forme um caminho contínuo ao longo do chão. A parede dura pela duração. Quando a parede aparece, cada criatura em sua área faz uma salvaguarda de Força, sofrendo 4d8 de dano contundente em caso de falha ou metade desse dano em caso de sucesso. O vento forte mantém névoa, fumaça e outros gases afastados. Criaturas ou objetos voadores de tamanho Pequeno ou menor não podem atravessar a parede. Materiais soltos e leves levados para dentro da parede voam para cima. Flechas, virotes e outros projéteis comuns lançados contra alvos atrás da parede são desviados para cima e erram automaticamente. Rochedos arremessados por Gigantes ou máquinas de cerco, e projéteis semelhantes, não são afetados. Criaturas em forma gasosa não podem atravessá-la.","superior":""},
  {"en":"Prismatic Wall","nome":"Muralha prismática","nivel":9,"escola":"Abjuração","tempo":"1 ação","alcance":"18 m","duracao":"10 minutos","componentes":"V, S","concentracao":false,"ritual":false,"classes":["Bardo","Mago"],"teste":"Salvaguarda de Constituição","dano":"12d6 elétrico fogo energia veneno ácido frio","gatilho":"","texto":"Um plano de luz cintilante e multicolorido forma uma parede vertical opaca, com até 27 m de comprimento, 9 m de altura e 2,5 cm de espessura, centrada em um ponto ao alcance. Como alternativa, você molda a parede em um globo de até 9 m de diâmetro centrado em um ponto ao alcance. A parede dura pela duração. Se você posicionar a parede em um espaço ocupado por uma criatura, a magia termina instantaneamente sem efeito.\n\nA parede emite Luz Plena a até 30 m e Penumbra por mais 30 m. Você e as criaturas que designar ao conjurar a magia podem atravessar a parede e ficar perto dela sem sofrer dano. Se outra criatura que possa ver a parede se mover a até 6 m dela ou começar seu turno ali, ela deve ter sucesso em uma salvaguarda de Constituição ou ficará com a condição Cego por 1 minuto.\n\nA parede é formada por sete camadas, cada uma de uma cor diferente. Quando uma criatura alcança o interior da parede ou a atravessa, ela o faz uma camada por vez, passando por todas as camadas. Cada camada obriga a criatura a realizar uma salvaguarda de Destreza ou ser afetada pelas propriedades daquela camada, conforme descrito na tabela Camadas Prismáticas.\n\nA parede, que tem CA 10, pode ser destruída uma camada por vez, em ordem do vermelho ao violeta, por meios específicos de cada camada. Se uma camada for destruída, ela desaparece pela duração. Campo Antimagia não tem efeito sobre a parede, e Dissipar Magia pode afetar apenas a camada violeta.\n\n| Ordem | Efeitos |\n|---|---|\n| 1 | **Vermelha.** *Falha na Salvaguarda:* 12d6 de dano de fogo. *Sucesso na Salvaguarda:* metade do dano. Efeitos Adicionais: ataques à distância não mágicos não conseguem atravessar esta camada, que é destruída se sofrer pelo menos 25 de dano de frio. |\n| 2 | **Laranja.** *Falha na Salvaguarda:* 12d6 de dano de ácido. *Sucesso na Salvaguarda:* metade do dano. Efeitos Adicionais: ataques à distância mágicos não conseguem atravessar esta camada, que é destruída por um vento forte (como o criado por Lufada de Vento). |\n| 3 | **Amarela.** *Falha na Salvaguarda:* 12d6 de dano elétrico. *Sucesso na Salvaguarda:* metade do dano. Efeitos Adicionais: a camada é destruída se sofrer pelo menos 60 de dano de energia. |\n| 4 | **Verde.** *Falha na Salvaguarda:* 12d6 de dano de veneno. *Sucesso na Salvaguarda:* metade do dano. Efeitos Adicionais: uma magia Passa-Parede, ou outra magia de nível igual ou superior que possa abrir um portal em uma superfície sólida, destrói esta camada. |\n| 5 | **Azul.** *Falha na Salvaguarda:* 12d6 de dano de frio. *Sucesso na Salvaguarda:* metade do dano. Efeitos Adicionais: a camada é destruída se sofrer pelo menos 25 de dano de fogo. |\n| 6 | **Anil.** *Falha na Salvaguarda:* o alvo fica com a condição Contido e realiza uma salvaguarda de Constituição no final de cada um de seus turnos. Se tiver sucesso três vezes, a condição termina. Se falhar três vezes, o alvo fica com a condição Petrificado até ser libertado por um efeito como a magia Restauração Maior. Os sucessos e as falhas não precisam ser consecutivos; mantenha a contagem de ambos até que o alvo acumule três de um mesmo tipo. Efeitos Adicionais: magias não podem ser conjuradas através desta camada, que é destruída pela Luz Plena emitida pela magia Luz do Dia. |\n| 7 | **Violeta.** *Falha na Salvaguarda:* o alvo fica com a condição Cego e realiza uma salvaguarda de Sabedoria no início do seu próximo turno. Em caso de sucesso, a condição termina. Em caso de falha, a condição termina e a criatura é teletransportada para outro plano de existência (à escolha do Mestre). Efeitos Adicionais: esta camada é destruída por Dissipar Magia. |","superior":""},
  {"en":"Nondetection","nome":"Não detecção","nivel":3,"escola":"Abjuração","tempo":"1 ação","alcance":"Toque","duracao":"8 horas","componentes":"V, S, M (uma pitada de pó de diamante que valha 25+ PO, que a magia consome)","concentracao":false,"ritual":false,"classes":["Bardo","Patrulheiro","Mago"],"teste":"","dano":"","gatilho":"","texto":"Pela duração, você esconde um alvo que tocar de magias de Adivinhação. O alvo pode ser uma criatura voluntária, ou um lugar ou objeto de no máximo 3 m em qualquer dimensão. O alvo não pode ser alvo de nenhuma magia de Adivinhação nem ser percebido por sensores mágicos de vidência.","superior":""},
  {"en":"Fog Cloud","nome":"Névoa","nivel":1,"escola":"Conjuração","tempo":"1 ação","alcance":"36 m","duracao":"Concentração, até 1 hora","componentes":"V, S","concentracao":true,"ritual":false,"classes":["Druida","Patrulheiro","Feiticeiro","Mago"],"teste":"","dano":"","gatilho":"","texto":"Você cria uma Esfera de névoa de 6 m de raio centrada em um ponto ao alcance. A Esfera é Fortemente Obscurecida. Ela dura pela duração ou até um vento forte (como o criado por Lufada de Vento) dispersá-la.","superior":"O raio da névoa aumenta em 6 m para cada nível do espaço de magia acima de 1."},
  {"en":"Stinking Cloud","nome":"Nuvem fedorenta","nivel":3,"escola":"Conjuração","tempo":"1 ação","alcance":"27 m","duracao":"Concentração, até 1 minuto","componentes":"V, S, M (um ovo podre)","concentracao":true,"ritual":false,"classes":["Bardo","Feiticeiro","Mago"],"teste":"Salvaguarda de Constituição","dano":"","gatilho":"","texto":"Você cria uma Esfera de 6 m de raio de gás amarelo e nauseante centrada em um ponto ao alcance. A nuvem é Muito Obscurecida. A nuvem permanece no ar pela duração ou até que um vento forte (como o criado por Lufada de Vento) a disperse. Cada criatura que começar seu turno na Esfera deve ter sucesso em uma salvaguarda de Constituição ou ficará com a condição Envenenado até o final do turno atual. Enquanto estiver Envenenada dessa forma, a criatura não pode realizar uma ação nem uma ação bônus.","superior":""},
  {"en":"Incendiary Cloud","nome":"Nuvem incendiária","nivel":8,"escola":"Conjuração","tempo":"1 ação","alcance":"45 m","duracao":"Concentração, até 1 minuto","componentes":"V, S","concentracao":true,"ritual":false,"classes":["Druida","Feiticeiro","Mago"],"teste":"Salvaguarda de Destreza","dano":"10d8 fogo","gatilho":"","texto":"Uma nuvem rodopiante de brasas e fumaça preenche uma Esfera de 6 m de raio centrada em um ponto ao alcance. A área da nuvem é Fortemente Obscurecida. Ela dura pela duração ou até que um vento forte (como o criado por Lufada de Vento) a disperse. Quando a nuvem surge, cada criatura nela faz uma salvaguarda de Destreza, sofrendo 10d8 de dano de fogo se falhar, ou metade desse dano se tiver sucesso. Uma criatura também deve fazer essa salvaguarda quando a Esfera se move para o espaço dela e quando ela entra na Esfera ou termina o turno ali. Uma criatura faz essa salvaguarda apenas uma vez por turno. A nuvem se move 3 m para longe de você, em uma direção à sua escolha, no início de cada um dos seus turnos.","superior":""},
  {"en":"Cloudkill","nome":"Nuvem mortal","nivel":5,"escola":"Conjuração","tempo":"1 ação","alcance":"36 m","duracao":"Concentração, até 10 minutos","componentes":"V, S","concentracao":true,"ritual":false,"classes":["Feiticeiro","Mago"],"teste":"Salvaguarda de Constituição","dano":"5d8 veneno","gatilho":"","texto":"Você cria uma Esfera de 6 m de raio de névoa amarelo-esverdeada centrada em um ponto ao alcance. A névoa dura pela duração ou até um vento forte (como o criado por Lufada de Vento) dispersá-la, encerrando a magia. Sua área é Fortemente Obscurecida. Cada criatura na Esfera faz uma salvaguarda de Constituição, sofrendo 5d8 de dano de veneno se falhar ou metade desse dano se tiver sucesso. Uma criatura também deve fazer essa salvaguarda quando a Esfera se move para o espaço dela e quando ela entra na Esfera ou termina seu turno nela. Uma criatura faz essa salvaguarda apenas uma vez por turno. A Esfera se move 3 m para longe de você no início de cada um dos seus turnos.","superior":"O dano aumenta em 1d8 para cada nível do espaço de magia acima de 5."},
  {"en":"Arcane Eye","nome":"Olho arcano","nivel":4,"escola":"Adivinhação","tempo":"1 ação","alcance":"9 m","duracao":"Concentração, até 1 hora","componentes":"V, S, M (um pouco de pelo de morcego)","concentracao":true,"ritual":false,"classes":["Mago"],"teste":"","dano":"","gatilho":"","texto":"Você cria um olho Invisível e invulnerável ao alcance, que paira pela duração. Você recebe mentalmente informações visuais do olho, que pode ver em todas as direções. Ele também tem Visão no Escuro com alcance de 9 m. Com uma ação bônus, você pode mover o olho até 9 m em qualquer direção. Uma barreira sólida bloqueia o movimento do olho, mas ele pode passar por uma abertura de apenas 2,5 cm de diâmetro.","superior":""},
  {"en":"Thunderwave","nome":"Onda trovejante","nivel":1,"escola":"Evocação","tempo":"1 ação","alcance":"Pessoal","duracao":"Instantânea","componentes":"V, S","concentracao":false,"ritual":false,"classes":["Bardo","Druida","Feiticeiro","Mago"],"teste":"Salvaguarda de Constituição","dano":"2d8 trovejante","gatilho":"","texto":"Você libera uma onda de energia trovejante. Cada criatura em um Cubo de 4,5 m originado em você faz uma salvaguarda de Constituição. Em caso de falha, a criatura sofre 2d8 de dano trovejante e é empurrada 3 m para longe de você. Em caso de sucesso, a criatura sofre apenas metade do dano.\n\nAlém disso, objetos não fixados que estejam inteiramente dentro do Cubo são empurrados 3 m para longe de você, e um estrondo trovejante é audível a até 90 m.","superior":"O dano aumenta em 1d8 para cada nível do espaço de magia acima de 1."},
  {"en":"Prayer of Healing","nome":"Oração de cura","nivel":2,"escola":"Abjuração","tempo":"1 minuto","alcance":"9 m","duracao":"Instantânea","componentes":"V","concentracao":false,"ritual":false,"classes":["Clérigo","Paladino"],"teste":"","dano":"2d8","gatilho":"","texto":"Até cinco criaturas à sua escolha que permaneçam ao alcance durante toda a conjuração da magia recebem os benefícios de um Descanso Curto e também recuperam 2d8 Pontos de Vida. Uma criatura não pode ser afetada por esta magia novamente até terminar um Descanso Longo.","superior":"A cura aumenta em 1d8 para cada nível do espaço de magia acima de 2."},
  {"en":"Chromatic Orb","nome":"Orbe cromática","nivel":1,"escola":"Evocação","tempo":"1 ação","alcance":"27 m","duracao":"Instantânea","componentes":"V, S, M (um diamante que valha 50+ PO)","concentracao":false,"ritual":false,"classes":["Feiticeiro","Mago"],"teste":"Ataque de magia","dano":"3d8","gatilho":"","texto":"Você arremessa um orbe de energia contra um alvo ao alcance. Escolha ácido, frio, fogo, elétrico, veneno ou trovejante como o tipo de orbe que você cria e então faça uma jogada de ataque de magia à distância contra o alvo. Se acertar, o alvo sofre 3d8 de dano do tipo escolhido. Se você tirar o mesmo número em dois ou mais dos d8, o orbe salta para um alvo diferente de sua escolha a até 9 m do alvo. Faça uma jogada de ataque contra o novo alvo e faça uma nova jogada de dano. O orbe não pode saltar novamente, a menos que você conjure a magia com um espaço de magia de nível 2 ou superior.","superior":"O dano aumenta em 1d8 para cada nível do espaço de magia acima de 1. O orbe pode saltar um número máximo de vezes igual ao nível do espaço gasto, e uma criatura pode ser alvo apenas uma vez por conjuração desta magia."},
  {"en":"Guidance","nome":"Orientação","nivel":0,"escola":"Adivinhação","tempo":"1 ação","alcance":"Toque","duracao":"Concentração, até 1 minuto","componentes":"V, S","concentracao":true,"ritual":false,"classes":["Clérigo","Druida"],"teste":"","dano":"1d4","gatilho":"","texto":"Você toca uma criatura voluntária e escolhe uma perícia. Até a magia terminar, a criatura soma 1d4 a qualquer teste de atributo que use a perícia escolhida.","superior":""},
  {"en":"Hypnotic Pattern","nome":"Padrão hipnótico","nivel":3,"escola":"Ilusão","tempo":"1 ação","alcance":"36 m","duracao":"Concentração, até 1 minuto","componentes":"S, M (uma pitada de confete)","concentracao":true,"ritual":false,"classes":["Bardo","Feiticeiro","Bruxo","Mago"],"teste":"Salvaguarda de Sabedoria","dano":"","gatilho":"","texto":"Você cria um padrão ondulante de cores em um Cubo de 9 m ao alcance. O padrão aparece por um instante e desaparece. Cada criatura na área que possa ver o padrão deve ter sucesso em uma salvaguarda de Sabedoria ou ficará com a condição Enfeitiçado pela duração. Enquanto Enfeitiçada, a criatura tem a condição Incapacitado e Deslocamento 0. A magia termina para uma criatura afetada se ela sofrer qualquer dano ou se outra pessoa usar uma ação para sacudi-la de seu torpor.","superior":""},
  {"en":"Healing Word","nome":"Palavra de cura","nivel":1,"escola":"Abjuração","tempo":"1 ação bônus","alcance":"18 m","duracao":"Instantânea","componentes":"V","concentracao":false,"ritual":false,"classes":["Bardo","Clérigo","Druida"],"teste":"","dano":"2d4","gatilho":"","texto":"Uma criatura à sua escolha que você possa ver ao alcance recupera Pontos de Vida iguais a 2d4 mais o seu modificador de atributo de conjuração.","superior":"A cura aumenta em 2d4 para cada nível do espaço de magia acima de 1."},
  {"en":"Mass Healing Word","nome":"Palavra de cura em massa","nivel":3,"escola":"Abjuração","tempo":"1 ação bônus","alcance":"18 m","duracao":"Instantânea","componentes":"V","concentracao":false,"ritual":false,"classes":["Bardo","Clérigo"],"teste":"","dano":"2d4","gatilho":"","texto":"Até seis criaturas à sua escolha que você possa ver ao alcance recuperam Pontos de Vida iguais a 2d4 mais o seu modificador de atributo de conjuração.","superior":"A cura aumenta em 1d4 para cada nível do espaço de magia acima de 3."},
  {"en":"Power Word Stun","nome":"Palavra de poder: atordoar","nivel":8,"escola":"Encantamento","tempo":"1 ação","alcance":"18 m","duracao":"Instantânea","componentes":"V","concentracao":false,"ritual":false,"classes":["Bardo","Feiticeiro","Bruxo","Mago"],"teste":"Salvaguarda de Constituição","dano":"","gatilho":"","texto":"Você domina a mente de uma criatura que você possa ver ao alcance. Se o alvo tiver 150 Pontos de Vida ou menos, ele tem a condição Atordoado. Caso contrário, seu Deslocamento é 0 até o início do seu próximo turno. O alvo Atordoado faz uma salvaguarda de Constituição no final de cada um dos seus turnos, encerrando a condição em si mesmo se tiver sucesso.","superior":""},
  {"en":"Power Word Heal","nome":"Palavra de poder: curar","nivel":9,"escola":"Encantamento","tempo":"1 ação","alcance":"18 m","duracao":"Instantânea","componentes":"V","concentracao":false,"ritual":false,"classes":["Bardo","Clérigo"],"teste":"","dano":"","gatilho":"","texto":"Uma onda de energia curativa envolve uma criatura que você possa ver ao alcance. O alvo recupera todos os seus Pontos de Vida. Se a criatura tiver a condição Enfeitiçado, Amedrontado, Paralisado, Envenenado ou Atordoado, a condição termina. Se a criatura tiver a condição Caído, ela pode usar sua reação para se levantar.","superior":""},
  {"en":"Power Word Kill","nome":"Palavra de poder: matar","nivel":9,"escola":"Encantamento","tempo":"1 ação","alcance":"18 m","duracao":"Instantânea","componentes":"V","concentracao":false,"ritual":false,"classes":["Bardo","Feiticeiro","Bruxo","Mago"],"teste":"","dano":"12d12 psíquico","gatilho":"","texto":"Você obriga uma criatura que você possa ver ao alcance a morrer. Se o alvo tiver 100 Pontos de Vida ou menos, ele morre. Caso contrário, sofre 12d12 de dano psíquico.","superior":""},
  {"en":"Word of Recall","nome":"Palavra de recordação","nivel":6,"escola":"Conjuração","tempo":"1 ação","alcance":"1,5 m","duracao":"Instantânea","componentes":"V","concentracao":false,"ritual":false,"classes":["Clérigo"],"teste":"","dano":"","gatilho":"","texto":"Você e até cinco criaturas dispostas a 1,5 m de você se teletransportam instantaneamente para um santuário previamente designado. Você e quaisquer criaturas que se teletransportem com você surgem no espaço desocupado mais próximo do local que você designou ao preparar seu santuário (veja abaixo). Se você conjurar esta magia sem antes preparar um santuário, a magia não tem efeito. Você deve designar um local, como um templo, como santuário conjurando esta magia ali.","superior":""},
  {"en":"Divine Word","nome":"Palavra divina","nivel":7,"escola":"Evocação","tempo":"1 ação bônus","alcance":"9 m","duracao":"Instantânea","componentes":"V","concentracao":false,"ritual":false,"classes":["Clérigo"],"teste":"Salvaguarda de Carisma","dano":"","gatilho":"","texto":"Você pronuncia uma palavra imbuída de poder dos Planos Superiores. Cada criatura à sua escolha no alcance faz uma salvaguarda de Carisma. Se falhar, um alvo que tenha 50 Pontos de Vida ou menos sofre um efeito baseado em seus Pontos de Vida atuais, conforme mostra a tabela Efeitos de Palavra Divina. Independentemente de seus Pontos de Vida, um alvo Celestial, Elemental, Feérico ou Ínfero que falhe na salvaguarda é forçado a retornar ao seu plano de origem (se já não estiver lá) e não pode retornar ao plano atual por 24 horas por nenhum meio, exceto uma magia Desejo.\n\n| Pontos de Vida | Efeito |\n|---|---|\n| 0–20 | O alvo morre. |\n| 21–30 | O alvo tem as condições Cego, Surdo e Atordoado por 1 hora. |\n| 31–40 | O alvo tem as condições Cego e Surdo por 10 minutos. |\n| 41–50 | O alvo tem a condição Surdo por 1 minuto. |","superior":""},
  {"en":"Time Stop","nome":"Parar o tempo","nivel":9,"escola":"Transmutação","tempo":"1 ação","alcance":"Pessoal","duracao":"Instantânea","componentes":"V","concentracao":false,"ritual":false,"classes":["Feiticeiro","Mago"],"teste":"","dano":"1d4 + 1","gatilho":"","texto":"Você interrompe brevemente o fluxo do tempo para todos, exceto você. Nenhum tempo passa para as outras criaturas, enquanto você tem 1d4 + 1 turnos seguidos, durante os quais pode usar ações e se mover normalmente. Esta magia termina se uma das ações que você usar nesse período, ou quaisquer efeitos que você criar durante ele, afetar uma criatura que não seja você ou um objeto vestido ou carregado por alguém que não seja você. Além disso, a magia termina se você se mover para um lugar a mais de 300 m do local onde a conjurou.","superior":""},
  {"en":"Passwall","nome":"Passa-parede","nivel":5,"escola":"Transmutação","tempo":"1 ação","alcance":"9 m","duracao":"1 hora","componentes":"V, S, M (uma pitada de sementes de gergelim)","concentracao":false,"ritual":false,"classes":["Mago"],"teste":"","dano":"","gatilho":"","texto":"Uma passagem aparece em um ponto que você possa ver em uma superfície de madeira, gesso ou pedra (como uma parede, teto ou piso) ao alcance e dura pela duração. Você escolhe as dimensões da abertura: até 1,5 m de largura, 2,4 m de altura e 6 m de profundidade. A passagem não cria instabilidade na estrutura ao redor. Quando a abertura desaparece, quaisquer criaturas ou objetos ainda na passagem criada pela magia são ejetados com segurança para o espaço desocupado mais próximo da superfície em que você conjurou a magia.","superior":""},
  {"en":"Pass without Trace","nome":"Passar sem rastro","nivel":2,"escola":"Abjuração","tempo":"1 ação","alcance":"Pessoal","duracao":"Concentração, até 1 hora","componentes":"V, S, M (cinzas de visco queimado)","concentracao":true,"ritual":false,"classes":["Druida","Patrulheiro"],"teste":"","dano":"","gatilho":"","texto":"Você emana uma aura de ocultação em uma Emanação de 9 m pela duração. Enquanto estiver na aura, você e cada criatura que você escolher têm um bônus de +10 em testes de Destreza (Furtividade) e não deixam rastros.","superior":""},
  {"en":"Misty Step","nome":"Passo nebuloso","nivel":2,"escola":"Conjuração","tempo":"1 ação bônus","alcance":"Pessoal","duracao":"Instantânea","componentes":"V","concentracao":false,"ritual":false,"classes":["Feiticeiro","Bruxo","Mago"],"teste":"","dano":"","gatilho":"","texto":"Brevemente cercado por névoa prateada, você se teletransporta até 9 m para um espaço desocupado que você possa ver.","superior":""},
  {"en":"Longstrider","nome":"Passos largos","nivel":1,"escola":"Transmutação","tempo":"1 ação","alcance":"Toque","duracao":"1 hora","componentes":"V, S, M (uma pitada de terra)","concentracao":false,"ritual":false,"classes":["Bardo","Druida","Patrulheiro","Mago"],"teste":"","dano":"","gatilho":"","texto":"Você toca uma criatura. O Deslocamento do alvo aumenta em 3 m até a magia terminar.","superior":"Você pode escolher uma criatura adicional como alvo para cada nível do espaço de magia acima de 1."},
  {"en":"Barkskin","nome":"Pele de árvore","nivel":2,"escola":"Transmutação","tempo":"1 ação bônus","alcance":"Toque","duracao":"1 hora","componentes":"V, S, M (um punhado de casca de árvore)","concentracao":false,"ritual":false,"classes":["Druida","Patrulheiro"],"teste":"","dano":"","gatilho":"","texto":"Você toca uma criatura disposta. Até a magia acabar, a pele do alvo assume uma aparência de casca de árvore, e o alvo tem Classe de Armadura 17 se a CA dele for menor que isso.","superior":""},
  {"en":"Stoneskin","nome":"Pele-rocha","nivel":4,"escola":"Transmutação","tempo":"1 ação","alcance":"Toque","duracao":"Concentração, até 1 hora","componentes":"V, S, M (pó de diamante que valha 100+ PO, que a magia consome)","concentracao":true,"ritual":false,"classes":["Druida","Patrulheiro","Feiticeiro","Mago"],"teste":"","dano":"","gatilho":"","texto":"Até a magia terminar, uma criatura voluntária que você tocar tem Resistência a dano contundente, perfurante e cortante.","superior":""},
  {"en":"Bane","nome":"Perdição","nivel":1,"escola":"Encantamento","tempo":"1 ação","alcance":"9 m","duracao":"Concentração, até 1 minuto","componentes":"V, S, M (uma gota de sangue)","concentracao":true,"ritual":false,"classes":["Bardo","Clérigo","Bruxo"],"teste":"Ataque de magia + Salvaguarda de Carisma","dano":"1d4","gatilho":"","texto":"Até três criaturas à sua escolha que você possa ver ao alcance devem fazer, cada uma, uma salvaguarda de Carisma. Sempre que um alvo que falhou nessa salvaguarda fizer uma jogada de ataque ou uma salvaguarda antes de a magia acabar, ele deve subtrair 1d4 da jogada de ataque ou da salvaguarda.","superior":"Você pode escolher uma criatura adicional como alvo para cada nível do espaço de magia acima de 1."},
  {"en":"Blink","nome":"Piscar","nivel":3,"escola":"Transmutação","tempo":"1 ação","alcance":"Pessoal","duracao":"1 minuto","componentes":"V, S","concentracao":false,"ritual":false,"classes":["Feiticeiro","Mago"],"teste":"","dano":"1d6","gatilho":"","texto":"Role 1d6 no final de cada um dos seus turnos pela duração. Com um resultado de 4–6, você desaparece do seu plano de existência atual e aparece no Plano Etéreo (a magia termina instantaneamente se você já estiver nesse plano). Enquanto estiver no Plano Etéreo, você pode perceber o plano que deixou, que é representado em tons de cinza, mas não pode ver nada ali a mais de 18 m de distância. Você pode afetar e ser afetado apenas por outras criaturas no Plano Etéreo, e criaturas no outro plano não podem perceber você, a menos que tenham uma habilidade especial que lhes permita perceber coisas no Plano Etéreo. Você retorna ao outro plano no início do seu próximo turno e quando a magia termina, se estiver no Plano Etéreo. Você retorna a um espaço desocupado à sua escolha que possa ver a até 3 m do espaço que deixou. Se não houver espaço desocupado disponível dentro desse alcance, você aparece no espaço desocupado mais próximo.","superior":""},
  {"en":"Dimension Door","nome":"Porta dimensional","nivel":4,"escola":"Conjuração","tempo":"1 ação","alcance":"150 m","duracao":"Instantânea","componentes":"V","concentracao":false,"ritual":false,"classes":["Bardo","Feiticeiro","Bruxo","Mago"],"teste":"","dano":"4d6 energia","gatilho":"","texto":"Você se teletransporta para um local ao alcance. Você chega exatamente ao ponto desejado. Pode ser um lugar que você possa ver, um que você possa visualizar ou um que você possa descrever informando distância e direção, como \"60 metros diretamente para baixo\" ou \"90 metros para cima, a noroeste, em um ângulo de 45 graus\". Você também pode teletransportar uma criatura voluntária. A criatura deve estar a até 1,5 m de você quando você se teletransportar, e ela se teletransporta para um espaço a até 1,5 m do seu espaço de destino. Se você, a outra criatura ou ambos chegarem a um espaço ocupado por uma criatura ou completamente preenchido por um ou mais objetos, você e qualquer criatura que viaje com você sofrem 4d6 de dano de energia cada, e o teletransporte falha.","superior":""},
  {"en":"Gate","nome":"Portal","nivel":9,"escola":"Conjuração","tempo":"1 ação","alcance":"18 m","duracao":"Concentração, até 1 minuto","componentes":"V, S, M (um diamante que valha 5.000+ PO)","concentracao":true,"ritual":false,"classes":["Clérigo","Feiticeiro","Bruxo","Mago"],"teste":"","dano":"","gatilho":"","texto":"Você conjura um portal que liga um espaço desocupado que você possa ver ao alcance a um local preciso em um plano de existência diferente. O portal é uma abertura circular, que você pode fazer com 1,5 a 6 m de diâmetro. Você pode orientar o portal em qualquer direção que escolher. O portal dura pela duração, e o destino do portal é visível através dele. O portal tem uma frente e um verso em cada plano em que aparece. Só é possível atravessar o portal movendo-se pela sua frente. Qualquer coisa que o faça é transportada instantaneamente para o outro plano, aparecendo no espaço desocupado mais próximo do portal. Divindades e outros governantes planares podem impedir que portais criados por esta magia se abram em sua presença ou em qualquer lugar dentro de seus domínios. Ao conjurar esta magia, você pode dizer o nome de uma criatura específica (um pseudônimo, título ou apelido não funciona). Se essa criatura estiver em um plano diferente do seu, o portal se abre ao lado da criatura nomeada e a transporta para o espaço desocupado mais próximo do seu lado do portal. Você não obtém nenhum poder especial sobre a criatura, e ela é livre para agir como o Mestre julgar apropriado. Ela pode ir embora, atacar você ou ajudá-lo.","superior":""},
  {"en":"Spare the Dying","nome":"Poupar os moribundos","nivel":0,"escola":"Necromancia","tempo":"1 ação","alcance":"4,5 m","duracao":"Instantânea","componentes":"V, S","concentracao":false,"ritual":false,"classes":["Clérigo","Druida"],"teste":"","dano":"","gatilho":"","texto":"Escolha uma criatura ao alcance que tenha 0 Pontos de Vida e não esteja morta. A criatura fica Estável.","superior":"O alcance dobra quando você alcança os níveis 5 (9 m), 11 (18 m) e 17 (36 m)."},
  {"en":"Insect Plague","nome":"Praga de insetos","nivel":5,"escola":"Conjuração","tempo":"1 ação","alcance":"90 m","duracao":"Concentração, até 10 minutos","componentes":"V, S, M (um gafanhoto)","concentracao":true,"ritual":false,"classes":["Clérigo","Druida","Feiticeiro"],"teste":"Salvaguarda de Constituição","dano":"4d10 perfurante","gatilho":"","texto":"Gafanhotos em enxame preenchem uma Esfera de 6 m de raio centrada em um ponto que você escolher ao alcance. A Esfera permanece pela duração, e sua área é Levemente Obscurecida e Terreno Difícil. Quando o enxame surge, cada criatura nele faz uma salvaguarda de Constituição, sofrendo 4d10 de dano perfurante se falhar, ou metade desse dano se tiver sucesso. Uma criatura também faz essa salvaguarda quando entra na área da magia pela primeira vez em um turno ou termina o turno ali. Uma criatura faz essa salvaguarda apenas uma vez por turno.","superior":"O dano aumenta em 1d10 para cada nível do espaço de magia acima de 5."},
  {"en":"Foresight","nome":"Presciência","nivel":9,"escola":"Adivinhação","tempo":"1 minuto","alcance":"Toque","duracao":"8 horas","componentes":"V, S, M (uma pena de beija-flor)","concentracao":false,"ritual":false,"classes":["Bardo","Druida","Bruxo","Mago"],"teste":"Ataque de magia","dano":"","gatilho":"","texto":"Você toca uma criatura disposta e concede a ela uma capacidade limitada de ver o futuro imediato. Pela duração, o alvo tem Vantagem em Testes de D20, e outras criaturas têm Desvantagem em jogadas de ataque contra ele. A magia termina antes se você a conjurar novamente.","superior":""},
  {"en":"Prestidigitation","nome":"Prestidigitação","nivel":0,"escola":"Transmutação","tempo":"1 ação","alcance":"3 m","duracao":"1 hora","componentes":"V, S","concentracao":false,"ritual":false,"classes":["Bardo","Feiticeiro","Bruxo","Mago"],"teste":"","dano":"","gatilho":"","texto":"Você cria um efeito mágico ao alcance. Escolha o efeito entre as opções abaixo. Se você conjurar esta magia várias vezes, pode ter até três dos seus efeitos não instantâneos ativos ao mesmo tempo.\n\n**_Efeito Sensorial._** Você cria um efeito sensorial instantâneo e inofensivo, como uma chuva de faíscas, uma lufada de vento, notas musicais tênues ou um odor estranho.\n\n**_Brincadeira com Fogo._** Você acende ou apaga instantaneamente uma vela, uma tocha ou uma pequena fogueira.\n\n**_Limpar ou Sujar._** Você limpa ou suja instantaneamente um objeto de no máximo 30 cm de aresta.\n\n**_Sensação Menor._** Você esfria, aquece ou dá sabor a até 30 cm de aresta de material não vivo por 1 hora.\n\n**_Marca Mágica._** Você faz uma cor, uma pequena marca ou um símbolo aparecer em um objeto ou superfície por 1 hora.\n\n**_Criação Menor._** Você cria uma bugiganga não mágica ou uma imagem ilusória que caiba na sua mão. Ela dura até o final do seu próximo turno. Uma bugiganga não pode causar dano e não tem valor monetário.","superior":""},
  {"en":"Forbiddance","nome":"Proibição","nivel":6,"escola":"Abjuração","tempo":"10 minutos","alcance":"Toque","duracao":"1 dia","componentes":"V, S, M (pó de rubi que valha 1.000+ PO)","concentracao":false,"ritual":true,"classes":["Clérigo"],"teste":"","dano":"5d10 necrótico","gatilho":"","texto":"Você cria uma proteção contra viagem mágica que protege até 3.600 metros quadrados de piso, até uma altura de 9 m acima do piso. Pela duração, criaturas não podem se teletransportar para a área nem usar portais, como os criados pela magia Portal, para entrar nela. A magia protege a área contra viagem planar e, portanto, impede que criaturas acessem a área pelo Plano Astral, pelo Plano Etéreo, pelo Feywild, pelo Shadowfell ou pela magia Mudança de Plano. Além disso, a magia causa dano aos tipos de criatura que você escolher ao conjurá-la. Escolha um ou mais dos seguintes: Aberrações, Celestiais, Elementais, Feéricos, Ínferos e Mortos-vivos. Quando uma criatura de um tipo escolhido entra na área da magia pela primeira vez em um turno ou termina o turno ali, ela sofre 5d10 de dano radiante ou necrótico (à sua escolha ao conjurar esta magia). Você pode designar uma senha ao conjurar a magia. Uma criatura que diga a senha ao entrar na área não sofre dano da magia. A área da magia não pode se sobrepor à área de outra magia Forbiddance. Se você conjurar Forbiddance todos os dias por 30 dias no mesmo local, a magia dura até ser dissipada, e os componentes materiais são consumidos na última conjuração.","superior":""},
  {"en":"Astral Projection","nome":"Projeção astral","nivel":9,"escola":"Necromancia","tempo":"1 hora","alcance":"3 m","duracao":"Até ser dissipada","componentes":"V, S, M (para cada alvo da magia, um jacinto que valha 1.000+ PO e uma barra de prata que valha 100+ PO, todos consumidos pela magia)","concentracao":false,"ritual":false,"classes":["Clérigo","Bruxo","Mago"],"teste":"","dano":"","gatilho":"","texto":"Você e até oito criaturas dispostas ao alcance projetam seus corpos astrais no Plano Astral (a magia termina instantaneamente se você já estiver nesse plano). O corpo de cada alvo é deixado para trás em estado de animação suspensa; ele fica com a condição Inconsciente, não precisa de comida nem de ar e não envelhece. A forma astral de um alvo se assemelha ao seu corpo em quase todos os aspectos, replicando suas estatísticas de jogo e posses. A principal diferença é o acréscimo de um cordão prateado que se estende entre as omoplatas da forma astral. O cordão desaparece de vista após 30 cm. Se o cordão for cortado, o que só acontece quando um efeito declara que o faz, o corpo e a forma astral do alvo morrem. A forma astral de um alvo pode viajar pelo Plano Astral. No momento em que uma forma astral deixa esse plano, o corpo e as posses do alvo viajam ao longo do cordão de prata, fazendo o alvo reentrar em seu corpo no novo plano. Qualquer dano ou outros efeitos que se apliquem a uma forma astral não têm efeito sobre o corpo do alvo, e vice-versa. Se o corpo ou a forma astral de um alvo cair a 0 Pontos de Vida, a magia termina para esse alvo. A magia termina para todos os alvos se você realizar uma ação Magia para dispensá-la. Quando a magia termina para um alvo que não está morto, o alvo reaparece em seu corpo e sai do estado de animação suspensa.","superior":""},
  {"en":"Project Image","nome":"Projetar imagem","nivel":7,"escola":"Ilusão","tempo":"1 ação","alcance":"750 km","duracao":"Concentração, até 1 dia","componentes":"V, S, M (uma estatueta de você mesmo que valha 5+ PO)","concentracao":true,"ritual":false,"classes":["Bardo","Mago"],"teste":"","dano":"","gatilho":"","texto":"Você cria uma cópia ilusória de si mesmo que dura pela duração. A cópia pode aparecer em qualquer local ao alcance que você já tenha visto antes, independentemente de obstáculos intermediários. A ilusão tem sua aparência e sua voz, mas é intangível. Se a ilusão sofrer qualquer dano, ela desaparece e a magia termina. Você pode ver através dos olhos da ilusão e ouvir através de seus ouvidos como se estivesse no espaço dela. Com uma ação Magia, você pode movê-la até 18 m e fazê-la gesticular, falar e se comportar da maneira que escolher. Ela imita seus maneirismos perfeitamente. A interação física com a imagem revela que ela é ilusória, pois coisas podem atravessá-la. Uma criatura que realize a ação Estudar para examinar a imagem pode determinar que é uma ilusão com um teste bem-sucedido de Inteligência (Investigação) contra a CD de salvaguarda da sua magia. Se uma criatura perceber a ilusão como ela realmente é, a criatura pode ver através da imagem, e qualquer ruído que ela faça soa oco para a criatura.","superior":""},
  {"en":"Death Ward","nome":"Proteção contra a morte","nivel":4,"escola":"Abjuração","tempo":"1 ação","alcance":"Toque","duracao":"8 horas","componentes":"V, S","concentracao":false,"ritual":false,"classes":["Clérigo","Paladino"],"teste":"","dano":"","gatilho":"","texto":"Você toca uma criatura e lhe concede certa proteção contra a morte. Na primeira vez em que o alvo cair a 0 Pontos de Vida antes de a magia terminar, ele cai a 1 Ponto de Vida, e a magia termina. Se a magia ainda estiver em efeito quando o alvo for submetido a um efeito que o mataria instantaneamente sem causar dano, esse efeito é anulado contra o alvo, e a magia termina.","superior":""},
  {"en":"Protection from Energy","nome":"Proteção contra energia","nivel":3,"escola":"Abjuração","tempo":"1 ação","alcance":"Toque","duracao":"Concentração, até 1 hora","componentes":"V, S","concentracao":true,"ritual":false,"classes":["Clérigo","Druida","Patrulheiro","Feiticeiro","Mago"],"teste":"","dano":"","gatilho":"","texto":"Pela duração, a criatura voluntária que você tocar tem Resistência a um tipo de dano à sua escolha: ácido, frio, fogo, elétrico ou trovejante.","superior":""},
  {"en":"Protection from Evil and Good","nome":"Proteção contra o bem e o mal","nivel":1,"escola":"Abjuração","tempo":"1 ação","alcance":"Toque","duracao":"Concentração, até 10 minutos","componentes":"V, S, M (um frasco de Água Benta que valha 25+ PO, que a magia consome)","concentracao":true,"ritual":false,"classes":["Clérigo","Druida","Paladino","Bruxo","Mago"],"teste":"Ataque de magia","dano":"","gatilho":"","texto":"Até a magia terminar, uma criatura voluntária que você tocar fica protegida contra criaturas que sejam Aberrações, Celestiais, Elementais, Feéricos, Ínferos ou Mortos-vivos. A proteção concede vários benefícios. Criaturas desses tipos têm Desvantagem em jogadas de ataque contra o alvo. O alvo também não pode ser possuído por elas nem receber delas as condições Enfeitiçado ou Amedrontado. Se o alvo já estiver possuído, Enfeitiçado ou Amedrontado por uma dessas criaturas, ele tem Vantagem em qualquer nova salvaguarda contra o efeito em questão.","superior":""},
  {"en":"Protection from Poison","nome":"Proteção contra veneno","nivel":2,"escola":"Abjuração","tempo":"1 ação","alcance":"Toque","duracao":"1 hora","componentes":"V, S","concentracao":false,"ritual":false,"classes":["Clérigo","Druida","Paladino","Patrulheiro"],"teste":"","dano":"","gatilho":"","texto":"Você toca uma criatura e encerra nela a condição Envenenado. Pela duração, o alvo tem Vantagem em salvaguardas para evitar ou encerrar a condição Envenenado e tem Resistência a dano de veneno.","superior":""},
  {"en":"Divine Smite","nome":"Punição divina","nivel":1,"escola":"Evocação","tempo":"1 ação bônus","alcance":"Pessoal","duracao":"Instantânea","componentes":"V","concentracao":false,"ritual":false,"classes":["Paladino"],"teste":"","dano":"2d8 radiante","gatilho":"","texto":"O alvo sofre 2d8 de dano radiante extra do ataque. O dano aumenta em 1d8 se o alvo for um Ínfero ou um Morto-vivo.","superior":"O dano aumenta em 1d8 para cada nível do espaço de magia acima de 1."},
  {"en":"Purify Food and Drink","nome":"Purificar alimentos e bebidas","nivel":1,"escola":"Transmutação","tempo":"1 ação","alcance":"3 m","duracao":"Instantânea","componentes":"V, S","concentracao":false,"ritual":true,"classes":["Clérigo","Druida","Paladino"],"teste":"","dano":"","gatilho":"","texto":"Você remove veneno e podridão de comida e bebida não mágicas em uma Esfera de 1,5 m de raio centrada em um ponto ao alcance.","superior":""},
  {"en":"Feather Fall","nome":"Queda suave","nivel":1,"escola":"Transmutação","tempo":"1 reação","alcance":"18 m","duracao":"1 minuto","componentes":"V, M (uma pequena pena ou um pedaço de penugem)","concentracao":false,"ritual":false,"classes":["Bardo","Feiticeiro","Mago"],"teste":"","dano":"","gatilho":"que você realiza quando você ou uma criatura que você possa ver a até 18 m de você cai","texto":"Escolha até cinco criaturas em queda ao alcance. A velocidade de descida de uma criatura em queda diminui para 18 m por rodada até a magia acabar. Se a criatura pousar antes de a magia acabar, ela não sofre dano da queda, e a magia termina para essa criatura.","superior":""},
  {"en":"Scorching Ray","nome":"Raio ardente","nivel":2,"escola":"Evocação","tempo":"1 ação","alcance":"36 m","duracao":"Instantânea","componentes":"V, S","concentracao":false,"ritual":false,"classes":["Feiticeiro","Mago"],"teste":"Ataque de magia","dano":"2d6 fogo","gatilho":"","texto":"Você arremessa três raios flamejantes. Você pode arremessá-los contra um alvo ao alcance ou contra vários. Faça uma jogada de ataque de magia à distância para cada raio. Em um acerto, o alvo sofre 2d6 de dano de fogo.","superior":"Você cria um raio adicional para cada nível do espaço de magia acima de 2."},
  {"en":"Fire Bolt","nome":"Raio de fogo","nivel":0,"escola":"Evocação","tempo":"1 ação","alcance":"36 m","duracao":"Instantânea","componentes":"V, S","concentracao":false,"ritual":false,"classes":["Feiticeiro","Mago"],"teste":"Ataque de magia","dano":"1d10 fogo","gatilho":"","texto":"Você arremessa uma fagulha de fogo contra uma criatura ou um objeto ao alcance. Faça uma jogada de ataque de magia à distância contra o alvo. Em um acerto, o alvo sofre 1d10 de dano de fogo. Um objeto inflamável atingido por esta magia começa a queimar se não estiver sendo vestido nem carregado.","superior":"O dano aumenta em 1d10 quando você alcança os níveis 5 (2d10), 11 (3d10) e 17 (4d10)."},
  {"en":"Ray of Frost","nome":"Raio de gelo","nivel":0,"escola":"Evocação","tempo":"1 ação","alcance":"18 m","duracao":"Instantânea","componentes":"V, S","concentracao":false,"ritual":false,"classes":["Feiticeiro","Mago"],"teste":"Ataque de magia","dano":"1d8 frio","gatilho":"","texto":"Um raio gélido de luz branco-azulada dispara em direção a uma criatura ao alcance. Faça uma jogada de ataque de magia à distância contra o alvo. Em um acerto, ele sofre 1d8 de dano de frio e seu Deslocamento é reduzido em 3 m até o início do seu próximo turno.","superior":"O dano aumenta em 1d8 quando você alcança os níveis 5 (2d8), 11 (3d8) e 17 (4d8)."},
  {"en":"Moonbeam","nome":"Raio de luar","nivel":2,"escola":"Evocação","tempo":"1 ação","alcance":"36 m","duracao":"Concentração, até 1 minuto","componentes":"V, S, M (uma folha de menisperma)","concentracao":true,"ritual":false,"classes":["Druida"],"teste":"Salvaguarda de Constituição","dano":"2d10 radiante","gatilho":"","texto":"Quando o Cilindro aparece, cada criatura nele faz uma salvaguarda de Constituição. Se falhar, a criatura sofre 2d10 de dano radiante e, se estiver transformada (como resultado da magia Metamorfose, por exemplo), ela volta à sua forma verdadeira e não pode mudar de forma até sair do Cilindro. Se tiver sucesso, a criatura sofre apenas metade do dano. Uma criatura também faz esta salvaguarda quando a área da magia se move para o espaço dela e quando ela entra na área da magia ou termina seu turno nela. Uma criatura faz esta salvaguarda apenas uma vez por turno.","superior":"O dano aumenta em 1d10 para cada nível do espaço de magia acima de 2."},
  {"en":"Ray of Enfeeblement","nome":"Raio do enfraquecimento","nivel":2,"escola":"Necromancia","tempo":"1 ação","alcance":"18 m","duracao":"Concentração, até 1 minuto","componentes":"V, S","concentracao":true,"ritual":false,"classes":["Bruxo","Mago"],"teste":"Ataque de magia + Salvaguarda de Constituição","dano":"1d8","gatilho":"","texto":"Um raio de energia debilitante é disparado de você em direção a uma criatura ao alcance. O alvo deve realizar uma salvaguarda de Constituição. Em caso de sucesso, o alvo tem Desvantagem na próxima jogada de ataque que fizer até o início do seu próximo turno. Em caso de falha, o alvo tem Desvantagem em Testes de D20 baseados em Força pela duração. Durante esse tempo, ele também subtrai 1d8 de todas as suas jogadas de dano. O alvo repete a salvaguarda no final de cada um de seus turnos, encerrando a magia em caso de sucesso.","superior":""},
  {"en":"Guiding Bolt","nome":"Raio guia","nivel":1,"escola":"Evocação","tempo":"1 ação","alcance":"36 m","duracao":"1 rodada","componentes":"V, S","concentracao":false,"ritual":false,"classes":["Clérigo"],"teste":"Ataque de magia","dano":"4d6 radiante","gatilho":"","texto":"Você arremessa um raio de luz em direção a uma criatura ao alcance. Faça uma jogada de ataque de magia à distância contra o alvo. Se acertar, ele sofre 4d6 de dano Radiante, e a próxima jogada de ataque feita contra ele antes do final do seu próximo turno tem Vantagem.","superior":"O dano aumenta em 1d6 para cada nível do espaço de magia acima de 1."},
  {"en":"Ray of Sickness","nome":"Raio nauseante","nivel":1,"escola":"Necromancia","tempo":"1 ação","alcance":"18 m","duracao":"Instantânea","componentes":"V, S","concentracao":false,"ritual":false,"classes":["Feiticeiro","Mago"],"teste":"Ataque de magia","dano":"2d8 veneno","gatilho":"","texto":"Você dispara um raio esverdeado em uma criatura ao alcance. Faça uma jogada de ataque de magia à distância contra o alvo. Em um acerto, o alvo sofre 2d8 de dano de veneno e fica com a condição Envenenado até o final do seu próximo turno.","superior":"O dano aumenta em 1d8 para cada nível do espaço de magia acima de 1."},
  {"en":"Sunbeam","nome":"Raio solar","nivel":6,"escola":"Evocação","tempo":"1 ação","alcance":"Pessoal","duracao":"Concentração, até 1 minuto","componentes":"V, S, M (uma lupa)","concentracao":true,"ritual":false,"classes":["Clérigo","Druida","Feiticeiro","Mago"],"teste":"Salvaguarda de Constituição","dano":"6d8 radiante","gatilho":"","texto":"Você lança um raio de sol em uma Linha de 1,5 m de largura e 18 m de comprimento. Cada criatura na Linha faz uma salvaguarda de Constituição. Se falhar, a criatura sofre 6d8 de dano radiante e fica com a condição Cego até o início do seu próximo turno. Se tiver sucesso, sofre apenas metade do dano. Até a magia terminar, você pode realizar uma ação Magia para criar uma nova Linha de radiância. Pela duração, uma centelha de radiância brilhante resplandece acima de você. Ela emite Luz Plena em um raio de 9 m e Penumbra por mais 9 m. Essa luz é luz solar.","superior":""},
  {"en":"Eldritch Blast","nome":"Rajada mística","nivel":0,"escola":"Evocação","tempo":"1 ação","alcance":"36 m","duracao":"Instantânea","componentes":"V, S","concentracao":false,"ritual":false,"classes":["Bruxo"],"teste":"Ataque de magia","dano":"1d10 energia","gatilho":"","texto":"Você arremessa um feixe de energia crepitante. Faça uma jogada de ataque de magia à distância contra uma criatura ou objeto no alcance. Se acertar, o alvo sofre 1d10 de dano de energia.","superior":"A magia cria dois feixes no nível 5, três feixes no nível 11 e quatro feixes no nível 17. Você pode direcionar os feixes ao mesmo alvo ou a alvos diferentes. Faça uma jogada de ataque separada para cada feixe."},
  {"en":"Reincarnate","nome":"Reencarnar","nivel":5,"escola":"Necromancia","tempo":"1 hora","alcance":"Toque","duracao":"Instantânea","componentes":"V, S, M (óleos raros que valham 1.000+ PO, que a magia consome)","concentracao":false,"ritual":false,"classes":["Druida"],"teste":"","dano":"1d10","gatilho":"","texto":"Você toca um Humanoide morto ou um pedaço de um. Se a criatura estiver morta há no máximo 10 dias, a magia forma um novo corpo para ela e chama a alma para entrar nesse corpo. Role 1d10 e consulte a tabela abaixo para determinar a espécie do corpo, ou o Mestre escolhe outra espécie jogável.\n\n| 1d10 | Espécie |\n|---|---|\n| 1 | Role novamente. |\n| 2 | Draconato |\n| 3 | Anão |\n| 4 | Elfo |\n| 5 | Gnomo |\n| 6 | Golias |\n| 7 | Halfling |\n| 8 | Humano |\n| 9 | Orc |\n| 10 | Tiefling |\n\nA criatura reencarnada faz quaisquer escolhas que a descrição de uma espécie oferece, e a criatura se lembra de sua vida anterior. Ela mantém as capacidades que tinha em sua forma original, exceto que perde as características de sua espécie anterior e ganha as de sua nova espécie.","superior":""},
  {"en":"Regenerate","nome":"Regenerar","nivel":7,"escola":"Transmutação","tempo":"1 minuto","alcance":"Toque","duracao":"1 hora","componentes":"V, S, M (uma roda de oração)","concentracao":false,"ritual":false,"classes":["Bardo","Clérigo","Druida"],"teste":"","dano":"4d8 + 15","gatilho":"","texto":"Uma criatura que você tocar recupera 4d8 + 15 Pontos de Vida. Pela duração, o alvo recupera 1 Ponto de Vida no início de cada um de seus turnos, e quaisquer partes do corpo decepadas voltam a crescer após 2 minutos.","superior":""},
  {"en":"Lightning Bolt","nome":"Relâmpago","nivel":3,"escola":"Evocação","tempo":"1 ação","alcance":"Pessoal","duracao":"Instantânea","componentes":"V, S, M (um pouco de pelo e uma haste de cristal)","concentracao":false,"ritual":false,"classes":["Feiticeiro","Mago"],"teste":"Salvaguarda de Destreza","dano":"8d6 elétrico","gatilho":"","texto":"Um raio formando uma Linha de 30 m de comprimento e 1,5 m de largura irrompe de você em uma direção à sua escolha. Cada criatura na Linha faz uma salvaguarda de Destreza, sofrendo 8d6 de dano elétrico se falhar, ou metade desse dano se tiver sucesso.","superior":"O dano aumenta em 1d6 para cada nível do espaço de magia acima de 3."},
  {"en":"Chain Lightning","nome":"Relâmpago encadeado","nivel":6,"escola":"Evocação","tempo":"1 ação","alcance":"45 m","duracao":"Instantânea","componentes":"V, S, M (três alfinetes de prata)","concentracao":false,"ritual":false,"classes":["Feiticeiro","Mago"],"teste":"Salvaguarda de Destreza","dano":"10d8 elétrico","gatilho":"","texto":"Você lança um raio contra um alvo que você possa ver ao alcance. Três raios então saltam desse alvo para até três outros alvos de sua escolha, cada um dos quais deve estar a até 9 m do primeiro alvo. Um alvo pode ser uma criatura ou um objeto e só pode ser alvo de um dos raios. Cada alvo faz uma salvaguarda de Destreza, sofrendo 10d8 de dano elétrico se falhar ou metade desse dano se tiver sucesso.","superior":""},
  {"en":"Remove Curse","nome":"Remover maldição","nivel":3,"escola":"Abjuração","tempo":"1 ação","alcance":"Toque","duracao":"Instantânea","componentes":"V, S","concentracao":false,"ritual":false,"classes":["Clérigo","Paladino","Bruxo","Mago"],"teste":"","dano":"","gatilho":"","texto":"Ao seu toque, todas as maldições que afetam uma criatura ou um objeto terminam. Se o objeto for um item mágico amaldiçoado, sua maldição permanece, mas a magia rompe a Sintonização do dono com o objeto, de modo que ele possa ser removido ou descartado.","superior":""},
  {"en":"Mending","nome":"Reparar","nivel":0,"escola":"Transmutação","tempo":"1 minuto","alcance":"Toque","duracao":"Instantânea","componentes":"V, S, M (duas pedras-ímã)","concentracao":false,"ritual":false,"classes":["Bardo","Clérigo","Druida","Feiticeiro","Mago"],"teste":"","dano":"","gatilho":"","texto":"Esta magia repara uma única quebra ou rasgo em um objeto que você toca, como um elo de corrente quebrado, as duas metades de uma chave partida, uma capa rasgada ou um odre furado. Desde que a quebra ou o rasgo não seja maior que 30 cm em qualquer dimensão, você o conserta, sem deixar vestígio do dano anterior. Esta magia pode reparar fisicamente um item mágico, mas não pode restaurar a magia desse objeto.","superior":""},
  {"en":"Hellish Rebuke","nome":"Repreensão diabólica","nivel":1,"escola":"Evocação","tempo":"1 reação","alcance":"18 m","duracao":"Instantânea","componentes":"V, S","concentracao":false,"ritual":false,"classes":["Bruxo"],"teste":"Salvaguarda de Destreza","dano":"2d10 fogo","gatilho":"que você realiza em resposta a sofrer dano de uma criatura que você possa ver a até 18 m de você","texto":"A criatura que causou dano a você é momentaneamente envolvida por chamas verdes. Ela faz uma salvaguarda de Destreza, sofrendo 2d10 de dano de Fogo se falhar ou metade desse dano se tiver sucesso.","superior":"O dano aumenta em 1d10 para cada nível do espaço de magia acima de 1."},
  {"en":"Resistance","nome":"Resistência","nivel":0,"escola":"Abjuração","tempo":"1 ação","alcance":"Toque","duracao":"Concentração, até 1 minuto","componentes":"V, S","concentracao":true,"ritual":false,"classes":["Clérigo","Druida"],"teste":"","dano":"1d4","gatilho":"","texto":"Você toca uma criatura voluntária e escolhe um tipo de dano: ácido, contundente, frio, fogo, elétrico, necrótico, perfurante, veneno, radiante, cortante ou trovejante. Quando a criatura sofre dano do tipo escolhido antes de a magia terminar, ela reduz o dano total sofrido em 1d4. Uma criatura pode se beneficiar desta magia apenas uma vez por turno.","superior":""},
  {"en":"Acid Splash","nome":"Respingo ácido","nivel":0,"escola":"Evocação","tempo":"1 ação","alcance":"18 m","duracao":"Instantânea","componentes":"V, S","concentracao":false,"ritual":false,"classes":["Feiticeiro","Mago"],"teste":"Salvaguarda de Destreza","dano":"1d6 ácido","gatilho":"","texto":"Você cria uma bolha ácida em um ponto ao alcance, onde ela explode em uma Esfera de 1,5 m de raio. Cada criatura nessa Esfera deve ter sucesso em uma salvaguarda de Destreza ou sofrer 1d6 de dano de ácido.","superior":"O dano aumenta em 1d6 quando você alcança os níveis 5 (2d6), 11 (3d6) e 17 (4d6)."},
  {"en":"Water Breathing","nome":"Respirar na água","nivel":3,"escola":"Transmutação","tempo":"1 ação","alcance":"9 m","duracao":"24 horas","componentes":"V, S, M (um junco curto)","concentracao":false,"ritual":true,"classes":["Druida","Patrulheiro","Feiticeiro","Mago"],"teste":"","dano":"","gatilho":"","texto":"Esta magia concede a até dez criaturas voluntárias à sua escolha ao alcance a capacidade de respirar debaixo d'água até a magia terminar. As criaturas afetadas também mantêm seu modo normal de respiração.","superior":""},
  {"en":"Resurrection","nome":"Ressurreição","nivel":7,"escola":"Necromancia","tempo":"1 hora","alcance":"Toque","duracao":"Instantânea","componentes":"V, S, M (um diamante que valha 1.000+ PO, que a magia consome)","concentracao":false,"ritual":false,"classes":["Bardo","Clérigo"],"teste":"","dano":"","gatilho":"","texto":"Com um toque, você revive uma criatura morta que esteja morta há no máximo um século, não tenha morrido de velhice e não era Morto-vivo quando morreu. A criatura volta à vida com todos os seus Pontos de Vida. Esta magia também neutraliza quaisquer venenos que afetavam a criatura no momento da morte. Esta magia fecha todos os ferimentos mortais e restaura quaisquer partes do corpo ausentes. Voltar dos mortos é uma provação. O alvo sofre uma penalidade de −4 em Testes de D20. Toda vez que o alvo termina um Descanso Longo, a penalidade é reduzida em 1 até chegar a 0. Conjurar esta magia para reviver uma criatura morta há 365 dias ou mais exige muito de você. Até terminar um Descanso Longo, você não pode conjurar magias novamente e tem Desvantagem em Testes de D20.","superior":""},
  {"en":"True Resurrection","nome":"Ressurreição verdadeira","nivel":9,"escola":"Necromancia","tempo":"1 hora","alcance":"Toque","duracao":"Instantânea","componentes":"V, S, M (diamantes que valham 25.000+ PO, os quais a magia consome)","concentracao":false,"ritual":false,"classes":["Clérigo","Druida"],"teste":"","dano":"","gatilho":"","texto":"Você toca uma criatura que esteja morta há no máximo 200 anos e que tenha morrido por qualquer causa, exceto velhice. A criatura é revivida com todos os seus Pontos de Vida. Esta magia fecha todos os ferimentos, neutraliza qualquer veneno, cura todos os contágios mágicos e remove quaisquer maldições que afetassem a criatura quando ela morreu. A magia substitui órgãos e membros danificados ou ausentes. Se a criatura era um Morto-vivo, ela é restaurada à sua forma não Morto-vivo. A magia pode fornecer um novo corpo se o original não existir mais, caso em que você deve dizer o nome da criatura. A criatura então aparece em um espaço desocupado à sua escolha a até 3 m de você.","superior":""},
  {"en":"Greater Restoration","nome":"Restauração maior","nivel":5,"escola":"Abjuração","tempo":"1 ação","alcance":"Toque","duracao":"Instantânea","componentes":"V, S, M (pó de diamante que valha 100+ PO, que a magia consome)","concentracao":false,"ritual":false,"classes":["Bardo","Clérigo","Druida","Paladino","Patrulheiro"],"teste":"","dano":"","gatilho":"","texto":"Você toca uma criatura e remove magicamente dela um dos seguintes efeitos:\n\n- 1 nível de Exaustão\n- A condição Enfeitiçado ou Petrificado\n- Uma maldição, incluindo a Sintonização do alvo a um item mágico amaldiçoado\n- Qualquer redução em um dos valores de atributo do alvo\n- Qualquer redução no máximo de Pontos de Vida do alvo","superior":""},
  {"en":"Lesser Restoration","nome":"Restauração menor","nivel":2,"escola":"Abjuração","tempo":"1 ação bônus","alcance":"Toque","duracao":"Instantânea","componentes":"V, S","concentracao":false,"ritual":false,"classes":["Bardo","Clérigo","Druida","Paladino","Patrulheiro"],"teste":"","dano":"","gatilho":"","texto":"Você toca uma criatura e encerra uma condição nela: Cego, Surdo, Paralisado ou Envenenado.","superior":""},
  {"en":"Expeditious Retreat","nome":"Retirada acelerada","nivel":1,"escola":"Transmutação","tempo":"1 ação bônus","alcance":"Pessoal","duracao":"Concentração, até 10 minutos","componentes":"V, S","concentracao":true,"ritual":false,"classes":["Feiticeiro","Bruxo","Mago"],"teste":"","dano":"","gatilho":"","texto":"Você realiza a ação Disparada e, até a magia acabar, pode realizar essa ação novamente como ação bônus.","superior":""},
  {"en":"Reverse Gravity","nome":"Reverse Gravity","nivel":7,"escola":"Transmutação","tempo":"1 ação","alcance":"30 m","duracao":"Concentração, até 1 minuto","componentes":"V, S, M (uma magnetita e limalha de ferro)","concentracao":true,"ritual":false,"classes":["Druida","Feiticeiro","Mago"],"teste":"Salvaguarda de Destreza","dano":"","gatilho":"","texto":"Esta magia inverte a gravidade em um Cilindro de 15 m de raio e 30 m de altura centrado em um ponto ao alcance. Todas as criaturas e objetos nessa área que não estejam ancorados ao chão caem para cima e alcançam o topo do Cilindro. Uma criatura pode realizar uma salvaguarda de Destreza para agarrar um objeto fixo ao seu alcance, evitando assim a queda para cima. Se um teto ou um objeto ancorado for encontrado nessa queda para cima, criaturas e objetos colidem com ele como colidiriam em uma queda para baixo. Se uma criatura ou um objeto afetado alcançar o topo do Cilindro sem colidir com nada, ele flutua ali pela duração. Quando a magia termina, os objetos e criaturas afetados caem para baixo.","superior":""},
  {"en":"Raise Dead","nome":"Reviver os mortos","nivel":5,"escola":"Necromancia","tempo":"1 hora","alcance":"Toque","duracao":"Instantânea","componentes":"V, S, M (um diamante que valha 500+ PO, que a magia consome)","concentracao":false,"ritual":false,"classes":["Bardo","Clérigo","Paladino"],"teste":"","dano":"","gatilho":"","texto":"Com um toque, você revive uma criatura morta, se ela estiver morta há no máximo 10 dias e não era Morto-vivo quando morreu. A criatura volta à vida com 1 Ponto de Vida. Esta magia também neutraliza quaisquer venenos que afetavam a criatura no momento da morte. Esta magia fecha todos os ferimentos mortais, mas não restaura partes do corpo ausentes. Se à criatura faltarem partes do corpo ou órgãos essenciais para sua sobrevivência, como a cabeça, a magia falha automaticamente. Voltar dos mortos é uma provação. O alvo sofre uma penalidade de −4 em Testes de D20. Toda vez que o alvo termina um Descanso Longo, a penalidade é reduzida em 1 até chegar a 0.","superior":""},
  {"en":"Revivify","nome":"Revivificar","nivel":3,"escola":"Necromancia","tempo":"1 ação","alcance":"Toque","duracao":"Instantânea","componentes":"V, S, M (um diamante que valha 300+ PO, que a magia consome)","concentracao":false,"ritual":false,"classes":["Clérigo","Druida","Paladino","Patrulheiro"],"teste":"","dano":"","gatilho":"","texto":"Você toca uma criatura que morreu no último minuto. Essa criatura revive com 1 Ponto de Vida. Esta magia não pode reviver uma criatura que morreu de velhice, nem restaura quaisquer partes do corpo ausentes.","superior":""},
  {"en":"Hideous Laughter","nome":"Riso histérico","nivel":1,"escola":"Encantamento","tempo":"1 ação","alcance":"9 m","duracao":"Concentração, até 1 minuto","componentes":"V, S, M (uma torta e uma pena)","concentracao":true,"ritual":false,"classes":["Bardo","Bruxo","Mago"],"teste":"Salvaguarda de Sabedoria","dano":"","gatilho":"","texto":"Uma criatura à sua escolha que você possa ver ao alcance faz uma salvaguarda de Sabedoria. Se falhar, ela fica com as condições Caído e Incapacitado pela duração. Durante esse tempo, ela ri incontrolavelmente se for capaz de rir, e não pode encerrar em si mesma a condição Caído. No final de cada um de seus turnos e cada vez que sofrer dano, ela faz outra salvaguarda de Sabedoria. O alvo tem Vantagem na salvaguarda se ela for provocada por dano. Se tiver sucesso, a magia termina.","superior":"Você pode escolher uma criatura adicional como alvo para cada nível do espaço de magia acima de 1."},
  {"en":"Bestow Curse","nome":"Rogar maldição","nivel":3,"escola":"Necromancia","tempo":"1 ação","alcance":"Toque","duracao":"Concentração, até 1 minuto","componentes":"V, S","concentracao":true,"ritual":false,"classes":["Bardo","Clérigo","Mago"],"teste":"Ataque de magia + Salvaguarda de Sabedoria","dano":"1d8 necrótico","gatilho":"","texto":"Você toca uma criatura, que deve ter sucesso em uma salvaguarda de Sabedoria ou ficará amaldiçoada pela duração. Até a maldição terminar, o alvo sofre um dos seguintes efeitos à sua escolha: - Escolha um atributo. O alvo tem Desvantagem em testes de atributo e salvaguardas feitos com esse atributo. - O alvo tem Desvantagem em jogadas de ataque contra você. - Em combate, o alvo deve ter sucesso em uma salvaguarda de Sabedoria no início de cada turno dele, ou será forçado a realizar a ação Esquivar nesse turno. - Se você causar dano ao alvo com uma jogada de ataque ou uma magia, o alvo sofre 1d8 de dano necrótico adicional.","superior":"Se você conjurar esta magia usando um espaço de magia de nível 4, poderá manter Concentração nela por até 10 minutos. Se usar um espaço de magia de nível 5+, a magia não requer Concentração, e a duração passa a ser de 8 horas (espaço de nível 5–6) ou 24 horas (espaço de nível 7–8). Se usar um espaço de magia de nível 9, a magia dura até ser dissipada."},
  {"en":"Jump","nome":"Salto","nivel":1,"escola":"Transmutação","tempo":"1 ação bônus","alcance":"Toque","duracao":"1 minuto","componentes":"V, S, M","concentracao":false,"ritual":false,"classes":["Druida","Patrulheiro","Feiticeiro","Mago"],"teste":"","dano":"","gatilho":"","texto":"Você toca uma criatura disposta. Uma vez em cada um dos turnos dela até a magia terminar, essa criatura pode saltar até 9 m gastando 3 m de movimento.","superior":"Você pode escolher uma criatura adicional como alvo para cada nível do espaço de magia acima de 1."},
  {"en":"Hallow","nome":"Santificar","nivel":5,"escola":"Abjuração","tempo":"1 hora","alcance":"Toque","duracao":"Até ser dissipada","componentes":"V, S, M (incenso que valha 1.000+ PO, que a magia consome)","concentracao":false,"ritual":false,"classes":["Clérigo"],"teste":"","dano":"","gatilho":"","texto":"Você toca um ponto e imbui uma área ao redor dele com poder sagrado ou profano. A área pode ter um raio de até 18 m, e a magia falha se o raio incluir uma área que já esteja sob o efeito de Consagrar. A área afetada tem os seguintes efeitos.\n\n**_Proteção Consagrada._** Escolha qualquer destes tipos de criatura: Aberração, Celestial, Elemental, Feérico, Ínfero ou Morto-vivo. Criaturas dos tipos escolhidos não podem entrar voluntariamente na área, e qualquer criatura que esteja possuída por tais criaturas ou que tenha a condição Enfeitiçado ou Amedrontado por causa delas não está possuída, Enfeitiçada nem Amedrontada por elas enquanto estiver na área.\n\n**_Efeito Extra._** Você vincula um efeito extra à área, escolhido da lista abaixo:\n\n- **_Coragem._** Criaturas de quaisquer tipos que você escolher não podem receber a condição Amedrontado enquanto estiverem na área.\n- **_Escuridão._** Escuridão preenche a área. Luz normal, assim como luz mágica criada por magias de nível inferior ao desta magia, não pode iluminar a área.\n - **_Luz do Dia._** Luz plena preenche a área. Escuridão mágica criada por magias de nível inferior ao desta magia não pode apagar a luz.\n- **_Descanso Pacífico._** Corpos mortos sepultados na área não podem ser transformados em Mortos-vivos.\n- **_Interferência Extradimensional._** Criaturas de quaisquer tipos que você escolher não podem entrar na área nem sair dela usando teletransporte ou viagem interplanar.\n- **_Medo._** Criaturas de quaisquer tipos que você escolher ficam com a condição Amedrontado enquanto estiverem na área.\n- **_Silêncio._** Nenhum som pode emanar de dentro da área, e nenhum som pode chegar a ela.\n- **_Línguas._** Criaturas de quaisquer tipos que você escolher podem se comunicar com qualquer outra criatura na área, mesmo que não compartilhem um idioma comum.\n- **_Vulnerabilidade._** Criaturas de quaisquer tipos que você escolher têm Vulnerabilidade a um tipo de dano à sua escolha enquanto estiverem na área.","superior":""},
  {"en":"Sanctuary","nome":"Santuário","nivel":1,"escola":"Abjuração","tempo":"1 ação bônus","alcance":"9 m","duracao":"1 minuto","componentes":"V, S, M (um caco de vidro de um espelho)","concentracao":false,"ritual":false,"classes":["Clérigo"],"teste":"Ataque de magia + Salvaguarda de Sabedoria","dano":"","gatilho":"","texto":"Você protege uma criatura ao alcance. Até a magia terminar, qualquer criatura que tenha como alvo a criatura protegida com uma jogada de ataque ou uma magia que cause dano deve ter sucesso em uma salvaguarda de Sabedoria, ou escolherá um novo alvo ou perderá o ataque ou a magia. Esta magia não protege a criatura protegida de áreas de efeito. A magia termina se a criatura protegida fizer uma jogada de ataque, conjurar uma magia ou causar dano.","superior":""},
  {"en":"Private Sanctum","nome":"Santuário particular","nivel":4,"escola":"Abjuração","tempo":"1 minuto","alcance":"36 m","duracao":"24 horas","componentes":"V, S, M (uma folha fina de chumbo)","concentracao":false,"ritual":false,"classes":["Mago"],"teste":"","dano":"","gatilho":"","texto":"Você torna uma área ao alcance magicamente protegida. A área é um Cubo que pode ter de 1,5 m a 30 m de lado. A magia dura pela duração.\n\nAo conjurar a magia, você decide que tipo de proteção ela fornece, escolhendo qualquer uma das seguintes propriedades:\n\n- O som não consegue atravessar a barreira na borda da área protegida.\n- A barreira da área protegida parece escura e nebulosa, impedindo a visão (incluindo Visão no Escuro) através dela.\n- Sensores criados por magias de Adivinhação não podem aparecer dentro da área protegida nem atravessar a barreira em seu perímetro. - Criaturas na área não podem ser alvo de magias de Adivinhação.\n- Nada pode se teletransportar para dentro ou para fora da área protegida.\n- Viagem planar é bloqueada dentro da área protegida. Conjurar esta magia no mesmo local todos os dias por 365 dias faz a magia durar até ser dissipada.","superior":"Você pode aumentar o tamanho do Cubo em 30 m para cada nível do espaço de magia acima de 4."},
  {"en":"Secret Chest","nome":"Secret Chest","nivel":4,"escola":"Conjuração","tempo":"1 ação","alcance":"Toque","duracao":"Até ser dissipada","componentes":"V, S, M (um baú de 0,9 m por 0,6 m por 0,6 m, construído com materiais raros que valham 5.000+ PO, e uma réplica Miúda do baú feita dos mesmos materiais que valha 50+ PO)","concentracao":false,"ritual":false,"classes":["Mago"],"teste":"","dano":"","gatilho":"","texto":"Você esconde um baú e todo o seu conteúdo no Plano Etéreo. Você deve tocar o baú e a réplica em miniatura que servem como componentes materiais da magia. O baú pode conter até 0,34 metro cúbico de material não vivo (0,9 m por 0,6 m por 0,6 m). Enquanto o baú permanece no Plano Etéreo, você pode realizar uma ação Magia e tocar a réplica para recuperar o baú. Ele aparece em um espaço desocupado no chão a até 1,5 m de você. Você pode enviar o baú de volta ao Plano Etéreo realizando uma ação Magia para tocar o baú e a réplica. Após 60 dias, há uma chance cumulativa de 5 por cento, no final de cada dia, de a magia terminar. A magia também termina se você conjurá-la novamente ou se a réplica Miúda do baú for destruída. Se a magia terminar e o baú maior estiver no Plano Etéreo, o baú permanece lá para você ou outra pessoa encontrar.","superior":""},
  {"en":"Demiplane","nome":"Semiplano","nivel":8,"escola":"Conjuração","tempo":"1 ação","alcance":"18 m","duracao":"1 hora","componentes":"S","concentracao":false,"ritual":false,"classes":["Feiticeiro","Bruxo","Mago"],"teste":"","dano":"","gatilho":"","texto":"Você cria uma porta sombria Média em uma superfície sólida e plana que você possa ver ao alcance. Essa porta pode ser aberta e fechada, e leva a um semiplano que é uma sala vazia de 9 m em cada dimensão, feita de madeira ou pedra (à sua escolha). Quando a magia termina, a porta desaparece, e quaisquer objetos dentro do semiplano permanecem lá. Quaisquer criaturas dentro dele também permanecem, a menos que optem por ser expelidas pela porta enquanto ela desaparece, caindo com a condição Caído nos espaços desocupados mais próximos do antigo espaço da porta. Cada vez que você conjura esta magia, pode criar um novo semiplano ou conectar a porta sombria a um semiplano que tenha criado em uma conjuração anterior desta magia. Além disso, se você conhecer a natureza e o conteúdo de um semiplano criado por outra criatura com uma conjuração desta magia, pode conectar a porta sombria a esse semiplano.","superior":""},
  {"en":"Sending","nome":"Sending","nivel":3,"escola":"Adivinhação","tempo":"1 ação","alcance":"Ilimitado","duracao":"Instantânea","componentes":"V, S, M (um fio de cobre)","concentracao":false,"ritual":false,"classes":["Bardo","Clérigo","Mago"],"teste":"","dano":"","gatilho":"","texto":"Você envia uma mensagem curta de 25 palavras ou menos a uma criatura que você conheceu ou a uma criatura descrita a você por alguém que a conheceu. O alvo ouve a mensagem em sua mente, reconhece você como o remetente se o conhecer e pode responder de maneira semelhante imediatamente. A magia permite que os alvos compreendam o significado da sua mensagem. Você pode enviar a mensagem a qualquer distância e até para outros planos de existência, mas, se o alvo estiver em um plano diferente do seu, há 5 por cento de chance de a mensagem não chegar. Você sabe se a entrega falha. Ao receber sua mensagem, uma criatura pode bloquear sua capacidade de alcançá-la novamente com esta magia por 8 horas. Se você tentar enviar outra mensagem nesse período, descobre que está bloqueado e a magia falha.","superior":""},
  {"en":"Unseen Servant","nome":"Servo invisível","nivel":1,"escola":"Conjuração","tempo":"1 ação","alcance":"18 m","duracao":"1 hora","componentes":"V, S, M (um pedaço de barbante e de madeira)","concentracao":false,"ritual":true,"classes":["Bardo","Bruxo","Mago"],"teste":"","dano":"","gatilho":"","texto":"Esta magia cria uma força Invisível, sem mente, sem forma e de tamanho Médio que realiza tarefas simples sob seu comando até a magia terminar. O servo surge em um espaço desocupado no chão ao alcance. Ele tem CA 10, 1 Ponto de Vida e Força 2, e não pode atacar. Se cair a 0 Pontos de Vida, a magia termina. Uma vez em cada um dos seus turnos, com uma ação bônus, você pode comandar mentalmente o servo a se mover até 4,5 m e interagir com um objeto. O servo pode realizar tarefas simples que um humano poderia fazer, como buscar coisas, limpar, remendar, dobrar roupas, acender fogueiras, servir comida e servir bebidas. Depois que você dá o comando, o servo realiza a tarefa da melhor forma que puder até concluí-la, e então aguarda seu próximo comando. Se você comandar o servo a realizar uma tarefa que o moveria a mais de 18 m de você, a magia termina.","superior":""},
  {"en":"Shillelagh","nome":"Shillelagh","nivel":0,"escola":"Transmutação","tempo":"1 ação bônus","alcance":"Pessoal","duracao":"1 minuto","componentes":"V, S, M (visco)","concentracao":false,"ritual":false,"classes":["Druida"],"teste":"","dano":"","gatilho":"","texto":"Um Porrete ou Bordão que você esteja segurando é imbuído com o poder da natureza. Pela duração, você pode usar seu atributo de conjuração em vez de Força nas jogadas de ataque e de dano de ataques corpo a corpo com essa arma, e o dado de dano da arma se torna um d8. Se o ataque causar dano, ele pode ser dano de energia ou o tipo de dano normal da arma (à sua escolha). A magia termina antes se você a conjurar novamente ou se soltar a arma.","superior":"O dado de dano muda quando você alcança os níveis 5 (d10), 11 (d12) e 17 (2d6)."},
  {"en":"Shining Smite","nome":"Shining Smite","nivel":2,"escola":"Transmutação","tempo":"1 ação bônus","alcance":"Pessoal","duracao":"Concentração, até 1 minuto","componentes":"V","concentracao":true,"ritual":false,"classes":["Paladino"],"teste":"Ataque de magia","dano":"2d6 radiante","gatilho":"","texto":"O alvo atingido pelo golpe sofre 2d6 extra de dano radiante do ataque. Até a magia terminar, o alvo emite Luz Plena em um raio de 1,5 m, jogadas de ataque contra ele têm Vantagem e ele não pode se beneficiar da condição Invisível.","superior":"O dano aumenta em 1d6 para cada nível do espaço de magia acima de 2."},
  {"en":"Silence","nome":"Silêncio","nivel":2,"escola":"Ilusão","tempo":"1 ação","alcance":"36 m","duracao":"Concentração, até 10 minutos","componentes":"V, S","concentracao":true,"ritual":true,"classes":["Bardo","Clérigo","Patrulheiro"],"teste":"","dano":"","gatilho":"","texto":"Pela duração, nenhum som pode ser criado dentro de uma Esfera de 6 m de raio centrada em um ponto que você escolher ao alcance, nem atravessá-la. Qualquer criatura ou objeto inteiramente dentro da Esfera tem Imunidade a dano trovejante, e as criaturas têm a condição Surdo enquanto estiverem inteiramente dentro dela. Conjurar uma magia que inclua um componente Verbal é impossível ali.","superior":""},
  {"en":"Symbol","nome":"Símbolo","nivel":7,"escola":"Abjuração","tempo":"1 minuto","alcance":"Toque","duracao":"Até ser dissipada ou ativada","componentes":"V, S, M (diamante em pó que valha 1.000+ PO, que a magia consome)","concentracao":false,"ritual":false,"classes":["Bardo","Clérigo","Druida","Mago"],"teste":"","dano":"","gatilho":"","texto":"Você inscreve um glifo nocivo em uma superfície (como um trecho de piso ou parede) ou dentro de um objeto que possa ser fechado (como um livro ou baú). O glifo pode cobrir uma área de no máximo 3 m de diâmetro. Se você escolher um objeto, ele deve permanecer no lugar; se for movido mais de 3 m do local onde você conjurou esta magia, o glifo se quebra e a magia termina sem ser desencadeada.\n\nO glifo é quase imperceptível e exige um sucesso em um teste de Sabedoria (Percepção) contra a CD da sua magia para ser notado.\n\nAo inscrever o glifo, você define seu gatilho e escolhe qual efeito o símbolo carrega: Morte, Discórdia, Medo, Dor, Sono ou Atordoamento. Cada um é explicado abaixo.\n\n**_Definir o Gatilho._** Você decide o que desencadeia o glifo ao conjurar a magia. Para glifos inscritos em uma superfície, gatilhos comuns incluem tocar ou pisar no glifo, remover outro objeto que o cubra ou se aproximar dele a uma certa distância. Para glifos inscritos dentro de um objeto, gatilhos comuns incluem abrir esse objeto ou ver o glifo.\n\nVocê pode refinar o gatilho para que apenas criaturas de certos tipos o ativem (por exemplo, o glifo pode ser configurado para afetar Aberrações). Você também pode definir condições para criaturas que não desencadeiam o glifo, como as que dizem uma certa senha.\n\nUma vez desencadeado, o glifo brilha, preenchendo uma Esfera de 18 m de raio com Penumbra por 10 minutos, após os quais a magia termina. Cada criatura na Esfera quando o glifo é ativado é alvo do efeito dele, assim como uma criatura que entre na Esfera pela primeira vez em um turno ou termine seu turno ali. Uma criatura é alvo apenas uma vez por turno.\n\n**_Morte._** Cada alvo faz uma salvaguarda de Constituição, sofrendo 10d10 de dano necrótico se falhar ou metade desse dano se tiver sucesso.\n\n**_Discórdia._** Cada alvo faz uma salvaguarda de Sabedoria. Se falhar, o alvo discute com outras criaturas por 1 minuto. Durante esse tempo, ele é incapaz de comunicação significativa e tem Desvantagem em jogadas de ataque e testes de atributo.\n\n**_Medo._** Cada alvo deve ter sucesso em uma salvaguarda de Sabedoria ou ficará com a condição Amedrontado por 1 minuto. Enquanto estiver Amedrontado, o alvo deve se mover pelo menos 9 m para longe do glifo em cada um dos turnos dele, se puder.\n\n**_Dor._** Cada alvo deve ter sucesso em uma salvaguarda de Constituição ou ficará com a condição Incapacitado por 1 minuto.\n\n**_Sono._** Cada alvo deve ter sucesso em uma salvaguarda de Sabedoria ou ficará com a condição Inconsciente por 10 minutos. Uma criatura acorda se sofrer dano ou se alguém realizar uma ação para sacudi-la e despertá-la.\n\n**_Atordoamento._** Cada alvo deve ter sucesso em uma salvaguarda de Sabedoria ou ficará com a condição Atordoado por 1 minuto.","superior":""},
  {"en":"Simulacrum","nome":"Simulacro","nivel":7,"escola":"Ilusão","tempo":"1 hora","alcance":"Toque","duracao":"Até ser dissipada","componentes":"V, S, M (rubi em pó que valha 1.500+ PO, que a magia consome)","concentracao":false,"ritual":false,"classes":["Mago"],"teste":"","dano":"","gatilho":"","texto":"Você cria um simulacro de uma Fera ou Humanoide que esteja a até 3 m de você durante toda a conjuração da magia. Você conclui a conjuração tocando tanto a criatura quanto um monte de gelo ou neve do mesmo tamanho dela, e o monte se transforma no simulacro, que é uma criatura. Ele usa as estatísticas de jogo da criatura original no momento da conjuração, exceto que é um Constructo, seu máximo de Pontos de Vida é metade e ele não pode conjurar esta magia. O simulacro é Amistoso com você e com as criaturas que você designar. Ele obedece aos seus comandos e age no seu turno em combate. O simulacro não pode ganhar níveis nem fazer Descansos Curtos ou Longos. Se o simulacro sofrer dano, a única forma de restaurar seus Pontos de Vida é repará-lo enquanto você faz um Descanso Longo, durante o qual você gasta componentes que valham 100 PO por Ponto de Vida restaurado. O simulacro deve permanecer a até 1,5 m de você durante o reparo. O simulacro dura até cair a 0 Pontos de Vida, quando volta a ser neve e derrete. Se você conjurar esta magia novamente, qualquer simulacro que você tenha criado com ela é destruído instantaneamente.","superior":""},
  {"en":"Sleet Storm","nome":"Sleet Storm","nivel":3,"escola":"Conjuração","tempo":"1 ação","alcance":"45 m","duracao":"Concentração, até 1 minuto","componentes":"V, S, M (um guarda-chuva em miniatura)","concentracao":true,"ritual":false,"classes":["Druida","Feiticeiro","Mago"],"teste":"Salvaguarda de Destreza","dano":"","gatilho":"","texto":"Até a magia terminar, granizo fino cai em um Cilindro de 12 m de altura e 6 m de raio centrado em um ponto que você escolher ao alcance. A área fica Muito Obscurecida, e chamas expostas na área são apagadas. O chão no Cilindro é Terreno Difícil. Quando uma criatura entra no Cilindro pela primeira vez em um turno ou começa seu turno ali, ela deve ter sucesso em uma salvaguarda de Destreza ou ficará com a condição Caído e perderá a Concentração.","superior":""},
  {"en":"Dream","nome":"Sonho","nivel":5,"escola":"Ilusão","tempo":"1 minuto","alcance":"Especial","duracao":"8 horas","componentes":"V, S, M (um punhado de areia)","concentracao":false,"ritual":false,"classes":["Bardo","Bruxo","Mago"],"teste":"Salvaguarda de Sabedoria","dano":"3d6 psíquico","gatilho":"","texto":"Você escolhe como alvo uma criatura que você conheça no mesmo plano de existência. Você ou uma criatura voluntária que você tocar entra em estado de transe para agir como mensageiro de sonhos. Enquanto estiver em transe, o mensageiro fica Incapacitado e tem Deslocamento 0. Se o alvo estiver dormindo, o mensageiro aparece nos sonhos do alvo e pode conversar com ele enquanto ele permanecer dormindo, durante a duração da magia. O mensageiro também pode moldar o ambiente do sonho, criando paisagens, objetos e outras imagens. O mensageiro pode sair do transe a qualquer momento, encerrando a magia. O alvo recorda o sonho perfeitamente ao acordar. Se o alvo estiver acordado quando você conjurar a magia, o mensageiro sabe disso e pode encerrar o transe (e a magia) ou esperar o alvo dormir, momento em que o mensageiro entra nos sonhos dele. Você pode tornar o mensageiro aterrorizante para o alvo. Se fizer isso, o mensageiro pode transmitir uma mensagem de no máximo dez palavras, e então o alvo faz uma salvaguarda de Sabedoria. Se falhar, o alvo não obtém nenhum benefício do descanso e sofre 3d6 de dano psíquico ao acordar.","superior":""},
  {"en":"Sleep","nome":"Sono","nivel":1,"escola":"Encantamento","tempo":"1 ação","alcance":"18 m","duracao":"Concentração, até 1 minuto","componentes":"V, S, M (uma pitada de areia ou pétalas de rosa)","concentracao":true,"ritual":false,"classes":["Bardo","Feiticeiro","Mago"],"teste":"Salvaguarda de Sabedoria","dano":"","gatilho":"","texto":"Cada criatura à sua escolha em uma Esfera de 1,5 m de raio centrada em um ponto ao alcance deve ter sucesso em uma salvaguarda de Sabedoria ou ficará com a condição Incapacitado até o final do próximo turno dela, quando deverá repetir a salvaguarda. Se o alvo falhar na segunda salvaguarda, ele fica com a condição Inconsciente pela duração. A magia termina sobre um alvo se ele sofrer dano ou se alguém a até 1,5 m dele realizar uma ação para sacudi-lo e tirá-lo do efeito da magia. Criaturas que não dormem, como os elfos, ou que tenham Imunidade à condição Exaustão têm sucesso automático nas salvaguardas contra esta magia.","superior":""},
  {"en":"Dragon's Breath","nome":"Sopro do dragão","nivel":2,"escola":"Transmutação","tempo":"1 ação bônus","alcance":"Toque","duracao":"Concentração, até 1 minuto","componentes":"V, S, M (uma pimenta ardida)","concentracao":true,"ritual":false,"classes":["Feiticeiro","Mago"],"teste":"Salvaguarda de Destreza","dano":"3d6","gatilho":"","texto":"Você toca uma criatura voluntária e escolhe ácido, frio, fogo, elétrico ou veneno. Até a magia terminar, o alvo pode realizar a ação Magia para exalar um Cone de 4,5 m. Cada criatura nessa área faz uma salvaguarda de Destreza, sofrendo 3d6 de dano do tipo escolhido se falhar, ou metade desse dano se tiver sucesso.","superior":"O dano aumenta em 1d6 para cada nível do espaço de magia acima de 2."},
  {"en":"Sorcerous Burst","nome":"Sorcerous Burst","nivel":0,"escola":"Evocação","tempo":"1 ação","alcance":"36 m","duracao":"Instantânea","componentes":"V, S","concentracao":false,"ritual":false,"classes":["Feiticeiro"],"teste":"Ataque de magia","dano":"1d8","gatilho":"","texto":"Você lança energia feiticeira contra uma criatura ou objeto ao alcance. Faça uma jogada de ataque de magia à distância contra o alvo. Se acertar, o alvo sofre 1d8 de dano de um tipo à sua escolha: ácido, frio, fogo, elétrico, veneno, psíquico ou trovejante. Se você tirar um 8 em um d8 para esta magia, pode rolar outro d8 e somá-lo ao dano. Quando você conjura esta magia, o número máximo desses d8 que você pode somar ao dano da magia é igual ao seu modificador de atributo de conjuração.","superior":"O dano aumenta em 1d8 quando você alcança os níveis 5 (2d8), 11 (3d8) e 17 (4d8)."},
  {"en":"Color Spray","nome":"Spray colorido","nivel":1,"escola":"Ilusão","tempo":"1 ação","alcance":"Pessoal","duracao":"Instantânea","componentes":"V, S, M (uma pitada de areia colorida)","concentracao":false,"ritual":false,"classes":["Bardo","Feiticeiro","Mago"],"teste":"Salvaguarda de Constituição","dano":"","gatilho":"","texto":"Você lança uma rajada deslumbrante de luz colorida e cintilante. Cada criatura em um Cone de 4,5 m com origem em você deve ter sucesso em uma salvaguarda de Constituição ou terá a condição Cego até o final do seu próximo turno.","superior":""},
  {"en":"Prismatic Spray","nome":"Spray prismático","nivel":7,"escola":"Evocação","tempo":"1 ação","alcance":"Pessoal","duracao":"Instantânea","componentes":"V, S","concentracao":false,"ritual":false,"classes":["Bardo","Feiticeiro","Mago"],"teste":"Salvaguarda de Destreza","dano":"1d8 elétrico fogo veneno ácido frio","gatilho":"","texto":"Oito raios de luz saem de você em um Cone de 18 m. Cada criatura no Cone faz uma salvaguarda de Destreza. Para cada alvo, role 1d8 para determinar qual raio colorido o afeta, consultando a tabela Raios Prismáticos.\n\n| 1d8 | Raio |\n|---|---|\n| 1 | **Vermelho.** *Falha na Salvaguarda:* 12d6 de dano de fogo. *Sucesso na Salvaguarda:* Metade do dano. |\n| 2 | **Laranja.** *Falha na Salvaguarda:* 12d6 de dano de ácido. *Sucesso na Salvaguarda:* Metade do dano. |\n| 3 | **Amarelo.** *Falha na Salvaguarda:* 12d6 de dano elétrico. *Sucesso na Salvaguarda:* Metade do dano. |\n| 4 | **Verde.** *Falha na Salvaguarda:* 12d6 de dano de veneno. *Sucesso na Salvaguarda:* Metade do dano. |\n| 5 | **Azul.** *Falha na Salvaguarda:* 12d6 de dano de frio. *Sucesso na Salvaguarda:* Metade do dano. |\n| 6 | **Anil.** *Falha na Salvaguarda:* O alvo tem a condição Contido e faz uma salvaguarda de Constituição no final de cada um dos seus turnos. Se tiver sucesso três vezes, a condição termina. Se falhar três vezes, ele tem a condição Petrificado até ser libertado por um efeito como a magia Restauração Maior. Os sucessos e falhas não precisam ser consecutivos; mantenha a conta de ambos até o alvo acumular três de um tipo. |\n| 7 | **Violeta.** *Falha na Salvaguarda:* O alvo tem a condição Cego e faz uma salvaguarda de Sabedoria no início do seu próximo turno. Se tiver sucesso, a condição termina. Se falhar, a condição termina, e a criatura é teletransportada para outro plano de existência (escolha do Mestre). |\n| 8 | **Especial.** O alvo é atingido por dois raios. Role duas vezes, rolando de novo qualquer 8. |","superior":""},
  {"en":"Poison Spray","nome":"Spray venenoso","nivel":0,"escola":"Necromancia","tempo":"1 ação","alcance":"9 m","duracao":"Instantânea","componentes":"V, S","concentracao":false,"ritual":false,"classes":["Druida","Feiticeiro","Bruxo","Mago"],"teste":"Ataque de magia","dano":"1d12 veneno","gatilho":"","texto":"Você lança uma névoa tóxica em uma criatura ao alcance. Faça uma jogada de ataque de magia à distância contra o alvo. Se acertar, o alvo sofre 1d12 de dano de veneno.","superior":"O dano aumenta em 1d12 quando você alcança os níveis 5 (2d12), 11 (3d12) e 17 (4d12)."},
  {"en":"Starry Wisp","nome":"Starry Wisp","nivel":0,"escola":"Evocação","tempo":"1 ação","alcance":"18 m","duracao":"Instantânea","componentes":"V, S","concentracao":false,"ritual":false,"classes":["Bardo","Druida"],"teste":"Ataque de magia","dano":"1d8 radiante","gatilho":"","texto":"Você lança uma centelha de luz contra uma criatura ou objeto ao alcance. Faça uma jogada de ataque de magia à distância contra o alvo. Se acertar, o alvo sofre 1d8 de dano radiante e, até o final do seu próximo turno, emite Penumbra em um raio de 3 m e não pode se beneficiar da condição Invisível.","superior":"O dano aumenta em 1d8 quando você alcança os níveis 5 (2d8), 11 (3d8) e 17 (4d8)."},
  {"en":"Suggestion","nome":"Sugestão","nivel":2,"escola":"Encantamento","tempo":"1 ação","alcance":"9 m","duracao":"Concentração, até 8 horas","componentes":"V, M (uma gota de mel)","concentracao":true,"ritual":false,"classes":["Bardo","Feiticeiro","Bruxo","Mago"],"teste":"Salvaguarda de Sabedoria","dano":"","gatilho":"","texto":"Você sugere um curso de atividade, descrito em no máximo 25 palavras, a uma criatura que você possa ver ao alcance e que possa ouvi-lo e entendê-lo. A sugestão deve parecer realizável e não envolver nada que obviamente causaria dano ao alvo ou aos aliados dele. Por exemplo, você poderia dizer: \"Pegue a chave do cofre do tesouro do culto e entregue-a a mim.\" Ou poderia dizer: \"Pare de lutar, saia desta biblioteca em paz e não volte.\" O alvo deve ter sucesso em uma salvaguarda de Sabedoria ou ficará com a condição Enfeitiçado pela duração ou até que você ou seus aliados causem dano a ele. O alvo Enfeitiçado persegue a sugestão da melhor forma que puder. A atividade sugerida pode continuar por toda a duração, mas, se puder ser concluída em menos tempo, a magia termina para o alvo ao concluí-la.","superior":""},
  {"en":"Mass Suggestion","nome":"Sugestão em massa","nivel":6,"escola":"Encantamento","tempo":"1 ação","alcance":"18 m","duracao":"24 horas","componentes":"V, M (uma língua de cobra)","concentracao":false,"ritual":false,"classes":["Bardo","Feiticeiro","Mago"],"teste":"Salvaguarda de Sabedoria","dano":"","gatilho":"","texto":"Você sugere um curso de atividade, descrito em no máximo 25 palavras, a doze ou menos criaturas que você possa ver ao alcance e que possam ouvi-lo e entendê-lo. A sugestão deve soar realizável e não envolver nada que obviamente causaria dano a algum dos alvos ou a seus aliados. Por exemplo, você poderia dizer: \"Caminhem até a vila no fim daquela estrada e ajudem os aldeões a colher as plantações até o pôr do sol.\" Ou poderia dizer: \"Agora não é hora de violência. Larguem as armas e dancem! Parem em uma hora.\" Cada alvo deve ter sucesso em uma salvaguarda de Sabedoria ou ficará com a condição Enfeitiçado pela duração ou até que você ou seus aliados causem dano ao alvo. Cada alvo Enfeitiçado persegue a sugestão da melhor forma que puder. A atividade sugerida pode continuar por toda a duração, mas, se a atividade sugerida puder ser concluída em menos tempo, a magia termina para um alvo ao concluí-la.","superior":"A duração é maior com um espaço de magia de nível 7 (10 dias), 8 (30 dias) ou 9 (366 dias)."},
  {"en":"Summon Dragon","nome":"Summon Dragon","nivel":5,"escola":"Conjuração","tempo":"1 ação","alcance":"18 m","duracao":"Concentração, até 1 hora","componentes":"V, S, M (um objeto com a imagem de um dragão gravada que valha 500+ PO)","concentracao":true,"ritual":false,"classes":["Mago"],"teste":"","dano":"","gatilho":"","texto":"Você invoca um espírito de Dragão. Ele se manifesta em um espaço desocupado que você possa ver ao alcance e usa o bloco de estatísticas Espírito Dracônico. A criatura desaparece quando cai a 0 Pontos de Vida ou quando a magia termina. A criatura é aliada sua e dos seus aliados. Em combate, a criatura compartilha a sua contagem de Iniciativa, mas realiza seu turno imediatamente depois do seu. Ela obedece aos seus comandos verbais (sem exigir ação sua). Se você não der nenhum, ela realiza a ação Esquivar e usa seu movimento para evitar perigo.","superior":"Use o nível do espaço de magia como nível da magia no bloco de estatísticas."},
  {"en":"Dissonant Whispers","nome":"Sussurros dissonantes","nivel":1,"escola":"Encantamento","tempo":"1 ação","alcance":"18 m","duracao":"Instantânea","componentes":"V","concentracao":false,"ritual":false,"classes":["Bardo"],"teste":"Salvaguarda de Sabedoria","dano":"3d6 psíquico","gatilho":"","texto":"Uma criatura à sua escolha que você possa ver ao alcance ouve uma melodia discordante em sua mente. O alvo faz uma salvaguarda de Sabedoria. Se falhar, ele sofre 3d6 de dano psíquico e deve usar imediatamente sua reação, se disponível, para se afastar de você o máximo que puder, usando a rota mais segura. Se tiver sucesso, o alvo sofre apenas metade do dano.","superior":""},
  {"en":"Thaumaturgy","nome":"Taumaturgia","nivel":0,"escola":"Transmutação","tempo":"1 ação","alcance":"9 m","duracao":"1 minuto","componentes":"V","concentracao":false,"ritual":false,"classes":["Clérigo"],"teste":"","dano":"","gatilho":"","texto":"Você manifesta uma maravilha menor ao alcance. Você cria um dos efeitos abaixo ao alcance. Se conjurar esta magia várias vezes, você pode ter até três dos seus efeitos de 1 minuto ativos ao mesmo tempo.\n\n**_Olhos Alterados._** Você altera a aparência dos seus olhos por 1 minuto.\n\n**_Voz Estrondosa._** Sua voz ressoa até três vezes mais alta que o normal por 1 minuto. Pela duração, você tem Vantagem em testes de Carisma (Intimidação).\n\n**_Brincadeira com Fogo._** Você faz chamas tremeluzirem, se intensificarem, enfraquecerem ou mudarem de cor por 1 minuto.\n\n**_Mão Invisível._** Você faz instantaneamente uma porta ou janela destrancada abrir de repente ou bater com força.\n\n**_Som Fantasma._** Você cria um som instantâneo que se origina de um ponto à sua escolha ao alcance, como um estrondo de trovão, o grito de um corvo ou sussurros ameaçadores.\n\n**_Tremores._** Você causa tremores inofensivos no chão por 1 minuto.","superior":""},
  {"en":"Web","nome":"Teia","nivel":2,"escola":"Conjuração","tempo":"1 ação","alcance":"18 m","duracao":"Concentração, até 1 hora","componentes":"V, S, M (um pedaço de teia de aranha)","concentracao":true,"ritual":false,"classes":["Feiticeiro","Mago"],"teste":"Salvaguarda de Destreza","dano":"2d4 fogo","gatilho":"","texto":"Você conjura uma massa de teia pegajosa em um ponto ao alcance. As teias preenchem um Cubo de 6 m ali pela duração. As teias são Terreno Difícil, e a área dentro delas é Levemente Obscurecida. Se as teias não estiverem ancoradas entre duas massas sólidas (como paredes ou árvores) nem dispostas em camadas sobre um piso, parede ou teto, a teia desmorona sobre si mesma, e a magia termina no início do seu próximo turno. Teias dispostas sobre uma superfície plana têm profundidade de 1,5 m. Na primeira vez que uma criatura entra nas teias em um turno ou começa seu turno nelas, ela deve ter sucesso em uma salvaguarda de Destreza ou ficará com a condição Contido enquanto estiver nas teias ou até se libertar. Uma criatura Contida pelas teias pode usar uma ação para fazer um teste de Força (Atletismo) contra a CD de salvaguarda das suas magias. Se tiver sucesso, ela não está mais Contida. As teias são inflamáveis. Qualquer Cubo de 1,5 m de teias exposto ao fogo queima em 1 rodada, causando 2d4 de dano de fogo a qualquer criatura que comece seu turno no fogo.","superior":""},
  {"en":"Telekinesis","nome":"Telecinésia","nivel":5,"escola":"Transmutação","tempo":"1 ação","alcance":"18 m","duracao":"Concentração, até 10 minutos","componentes":"V, S","concentracao":true,"ritual":false,"classes":["Feiticeiro","Mago"],"teste":"Salvaguarda de Força","dano":"","gatilho":"","texto":"Você ganha a capacidade de mover ou manipular criaturas ou objetos pelo pensamento. Quando conjura a magia e com uma ação Magia nos seus turnos seguintes antes de a magia terminar, você pode exercer sua vontade sobre uma criatura ou objeto que possa ver ao alcance, causando o efeito apropriado abaixo. Você pode afetar o mesmo alvo rodada após rodada ou escolher um novo a qualquer momento. Se você trocar de alvo, o alvo anterior deixa de ser afetado pela magia.\n\n**_Criatura._** Você pode tentar mover uma criatura Enorme ou menor. O alvo deve ter sucesso em uma salvaguarda de Força, ou você o move até 9 m em qualquer direção dentro do alcance da magia. Até o final do seu próximo turno, a criatura fica com a condição Contido e, se você a erguer no ar, ela fica suspensa ali. Ela cai no final do seu próximo turno, a menos que você use esta opção nela novamente e ela falhe na salvaguarda.\n\n**_Objeto._** Você pode tentar mover um objeto Enorme ou menor. Se o objeto não estiver sendo vestido ou carregado, você o move automaticamente até 9 m em qualquer direção dentro do alcance da magia.\n\nSe o objeto estiver sendo vestido ou carregado por uma criatura, essa criatura deve ter sucesso em uma salvaguarda de Força, ou você puxa o objeto e o move até 9 m em qualquer direção dentro do alcance da magia.\n\nVocê pode exercer controle fino sobre objetos com seu domínio telecinético, como manipular uma ferramenta simples,","superior":""},
  {"en":"Teleport","nome":"Teletransporte","nivel":7,"escola":"Conjuração","tempo":"1 ação","alcance":"3 m","duracao":"Instantânea","componentes":"V","concentracao":false,"ritual":false,"classes":["Bardo","Feiticeiro","Mago"],"teste":"","dano":"1d100","gatilho":"","texto":"Esta magia transporta instantaneamente você e até oito criaturas voluntárias que você possa ver ao alcance, ou um único objeto que você possa ver ao alcance, para um destino que você selecionar. Se você escolher um objeto, ele deve ser Grande ou menor e não pode estar sendo segurado ou carregado por uma criatura involuntária. O destino que você escolher deve ser conhecido por você e deve estar no mesmo plano de existência que você. Sua familiaridade com o destino determina se você chega lá com sucesso. O Mestre rola 1d100 e consulta a tabela Resultado do Teleporte e as explicações depois dela.\n\n| Familiaridade | Acidente | Área Semelhante | Fora do Alvo | No Alvo |\n|---|---|---|---|---|\n| Círculo permanente | — | — | — | 01–00 |\n| Objeto vinculado | — | — | — | 01–00 |\n| Muito familiar | 01–05 | 06–13 | 14–24 | 25–00 |\n| Visto casualmente | 01–33 | 34–43 | 44–53 | 54–00 |\n| Visto uma vez ou descrito | 01–43 | 44–53 | 54–73 | 74–00 |\n| Destino falso | 01–50 | 51–00 | — | — |\n\n- \"Círculo permanente\" significa um círculo de teleporte permanente cuja sequência de sigilos você conhece.\n- \"Objeto vinculado\" significa que você possui um objeto retirado do destino desejado nos últimos seis meses, como um livro da biblioteca de um mago.\n- \"Muito familiar\" é um lugar que você visitou com frequência, um lugar que estudou com cuidado ou um lugar que você pode ver quando conjura a magia.\n- \"Visto casualmente\" é um lugar que você viu mais de uma vez, mas com o qual não é muito familiarizado.\n- \"Visto uma vez ou descrito\" é um lugar que você viu uma vez, possivelmente usando magia, ou um lugar que você conhece pela descrição de outra pessoa, talvez a partir de um mapa.\n- \"Destino falso\" é um lugar que não existe. Talvez você tenha tentado espiar o santuário de um inimigo, mas viu uma ilusão, ou esteja tentando se teleportar para um local que não existe mais.\n\n**Acidente.** A magia imprevisível resulta em uma jornada difícil. Cada criatura que se teleporta (ou o objeto alvo) sofre 3d10 de dano de energia, e o Mestre rola novamente na tabela para ver onde você vai parar (podem ocorrer vários acidentes, causando dano a cada vez).\n\n**Área Semelhante.** Você e seu grupo (ou o objeto alvo) aparecem em uma área diferente que seja visual ou tematicamente semelhante à área pretendida. Você aparece no lugar semelhante mais próximo. Se estiver indo para o seu laboratório, por exemplo, pode aparecer no laboratório de outra pessoa na mesma cidade.\n\n**Fora do Alvo.** Você e seu grupo (ou o objeto alvo) aparecem a 2d12 × 1,5 km do destino em uma direção aleatória. Role 1d8 para a direção: 1, leste; 2, sudeste; 3, sul; 4, sudoeste; 5, oeste; 6, noroeste; 7, norte; ou 8, nordeste.\n\n**No Alvo.** Você e seu grupo (ou o objeto alvo) aparecem onde você pretendia.","superior":""},
  {"en":"Storm of Vengeance","nome":"Tempestade da vingança","nivel":9,"escola":"Conjuração","tempo":"1 ação","alcance":"1,5 km","duracao":"Concentração, até 1 minuto","componentes":"V, S","concentracao":true,"ritual":false,"classes":["Druida"],"teste":"Salvaguarda de Constituição","dano":"2d6 trovejante","gatilho":"","texto":"Uma nuvem de tempestade turbulenta se forma pela duração, centrada em um ponto ao alcance e se espalhando até um raio de 90 m. Cada criatura sob a nuvem quando ela aparece deve ter sucesso em uma salvaguarda de Constituição ou sofrerá 2d6 de dano trovejante e ficará com a condição Surdo pela duração.\n\nNo início de cada um dos seus turnos seguintes, a tempestade produz efeitos diferentes, conforme detalhado abaixo.\n\n**_Turno 2._** Chuva ácida cai. Cada criatura e objeto sob a nuvem sofre 4d6 de dano ácido.\n\n**_Turno 3._** Você invoca seis raios da nuvem para atingir seis criaturas ou objetos diferentes abaixo dela. Cada alvo faz uma salvaguarda de Destreza, sofrendo 10d6 de dano elétrico se falhar ou metade desse dano se tiver sucesso.\n\n**_Turno 4._** Chove granizo. Cada criatura sob a nuvem sofre 2d6 de dano contundente.\n\n**_Turnos 5–10._** Rajadas de vento e chuva gelada assolam a área sob a nuvem. Cada criatura ali sofre 1d6 de dano de frio. Até a magia terminar, a área é Terreno Difícil e Muito Obscurecida, ataques à distância com armas são impossíveis ali e um vento forte sopra pela área.","superior":""},
  {"en":"Fire Storm","nome":"Tempestade de fogo","nivel":7,"escola":"Evocação","tempo":"1 ação","alcance":"45 m","duracao":"Instantânea","componentes":"V, S","concentracao":false,"ritual":false,"classes":["Clérigo","Druida","Feiticeiro"],"teste":"Salvaguarda de Destreza","dano":"7d10 fogo","gatilho":"","texto":"Uma tempestade de fogo surge ao alcance. A área da tempestade consiste em até dez Cubos de 3 m, que você organiza como quiser. Cada Cubo deve ser contíguo a pelo menos outro Cubo. Cada criatura na área faz uma salvaguarda de Destreza, sofrendo 7d10 de dano de fogo se falhar, ou metade desse dano se tiver sucesso. Objetos inflamáveis na área que não estejam sendo vestidos nem carregados começam a queimar.","superior":""},
  {"en":"Ice Storm","nome":"Tempestade de gelo","nivel":4,"escola":"Evocação","tempo":"1 ação","alcance":"90 m","duracao":"Instantânea","componentes":"V, S, M (uma luva sem dedos)","concentracao":false,"ritual":false,"classes":["Druida","Feiticeiro","Mago"],"teste":"Salvaguarda de Destreza","dano":"2d10 contundente frio","gatilho":"","texto":"Granizo cai em um Cilindro de 6 m de raio e 12 m de altura centrado em um ponto ao alcance. Cada criatura no Cilindro faz uma salvaguarda de Destreza. Uma criatura sofre 2d10 de dano Contundente e 4d6 de dano de Frio se falhar, ou metade desse dano se tiver sucesso. Pedras de granizo transformam o chão no Cilindro em Terreno Difícil até o final do seu próximo turno.","superior":"O dano Contundente aumenta em 1d10 para cada nível do espaço de magia acima de 4."},
  {"en":"Black Tentacles","nome":"Tentáculos negros","nivel":4,"escola":"Conjuração","tempo":"1 ação","alcance":"27 m","duracao":"Concentração, até 1 minuto","componentes":"V, S, M (um tentáculo)","concentracao":true,"ritual":false,"classes":["Mago"],"teste":"Salvaguarda de Força","dano":"3d6 contundente","gatilho":"","texto":"Tentáculos de ébano, contorcendo-se, preenchem um quadrado de 6 m de lado no chão que você possa ver ao alcance. Pela duração, esses tentáculos transformam o chão nessa área em Terreno Difícil. Cada criatura nessa área faz uma salvaguarda de Força. Em uma falha, ela sofre 3d6 de dano contundente e fica com a condição Contido até a magia acabar. Uma criatura também faz essa salvaguarda se entrar na área ou terminar o turno dela ali. Uma criatura faz essa salvaguarda apenas uma vez por turno. Uma criatura Contida pode usar uma ação para fazer um teste de Força (Atletismo) contra a CD de salvaguarda da sua magia, encerrando a condição sobre si mesma em um sucesso.","superior":""},
  {"en":"Earthquake","nome":"Terremoto","nivel":8,"escola":"Transmutação","tempo":"1 ação","alcance":"150 m","duracao":"Concentração, até 1 minuto","componentes":"V, S, M (uma rocha fraturada)","concentracao":true,"ritual":false,"classes":["Clérigo","Druida","Feiticeiro"],"teste":"Salvaguarda de Destreza","dano":"12d6 contundente","gatilho":"","texto":"Escolha um ponto no chão que você possa ver ao alcance. Pela duração, um tremor intenso rasga o solo em um círculo de 30 m de raio centrado nesse ponto. O solo ali é Terreno Difícil.\n\nQuando você conjura esta magia e no final de cada um dos seus turnos pela duração, cada criatura no chão na área faz uma salvaguarda de Destreza. Se falhar, a criatura tem a condição Caído, e sua Concentração é interrompida.\n\nVocê também pode causar os efeitos abaixo.\n\n***Fissuras.*** Um total de 1d6 fissuras se abrem na área da magia no final do turno em que você a conjura. Você escolhe os locais das fissuras, que não podem ficar sob estruturas. Cada fissura tem 1d10 × 3 m de profundidade e 3 m de largura, e se estende de uma borda da área da magia até outra borda. Uma criatura no mesmo espaço de uma fissura deve ter sucesso em uma salvaguarda de Destreza ou cairá nela. Uma criatura que tenha sucesso na salvaguarda se move com a borda da fissura enquanto ela se abre.\n\n***Estruturas.*** O tremor causa 50 de dano contundente a qualquer estrutura em contato com o chão na área quando você conjura a magia e no final de cada um dos seus turnos até a magia terminar. Se uma estrutura cair a 0 Pontos de Vida, ela desmorona.\n\nUma criatura a uma distância de uma estrutura em colapso igual à metade da altura da estrutura faz uma salvaguarda de Destreza. Se falhar, a criatura sofre 12d6 de dano contundente, tem a condição Caído e fica soterrada nos escombros, exigindo um teste de Força (Atletismo) CD 20 como ação para escapar. Se tiver sucesso, a criatura sofre apenas metade do dano.","superior":""},
  {"en":"Hallucinatory Terrain","nome":"Terreno alucinatório","nivel":4,"escola":"Ilusão","tempo":"1 minuto","alcance":"90 m","duracao":"24 horas","componentes":"V, S, M (um cogumelo)","concentracao":false,"ritual":false,"classes":["Bardo","Druida","Bruxo","Mago"],"teste":"","dano":"","gatilho":"","texto":"Você faz um terreno natural em um Cubo de 45 m ao alcance parecer, soar e cheirar como outro tipo de terreno natural. Assim, campos abertos ou uma estrada podem ser feitos para parecer um pântano, colina, fenda ou algum outro terreno difícil ou intransponível. Um lago pode parecer um prado gramado, um precipício uma encosta suave, ou uma ravina cheia de pedras uma estrada larga e lisa. Estruturas construídas, equipamentos e criaturas dentro da área não são alterados. As características táteis do terreno permanecem inalteradas, então criaturas que entrarem na área provavelmente notarão a ilusão. Se a diferença não for óbvia ao toque, uma criatura que examine a ilusão pode usar a ação Estudar para fazer um teste de Inteligência (Investigação) contra a CD de salvaguarda da sua magia para descrer dela. Se uma criatura perceber que o terreno é ilusório, ela vê uma imagem vaga sobreposta ao terreno real.","superior":""},
  {"en":"Shocking Grasp","nome":"Toque chocante","nivel":0,"escola":"Evocação","tempo":"1 ação","alcance":"Toque","duracao":"Instantânea","componentes":"V, S","concentracao":false,"ritual":false,"classes":["Feiticeiro","Mago"],"teste":"Ataque de magia","dano":"1d8 elétrico","gatilho":"","texto":"Um raio salta de você até uma criatura que você tente tocar. Faça uma jogada de ataque de magia corpo a corpo contra o alvo. Se acertar, o alvo sofre 1d8 de dano elétrico e não pode realizar Ataques de Oportunidade até o início do próximo turno dele.","superior":"O dano aumenta em 1d8 quando você alcança os níveis 5 (2d8), 11 (3d8) e 17 (4d8)."},
  {"en":"Chill Touch","nome":"Toque gélido","nivel":0,"escola":"Necromancia","tempo":"1 ação","alcance":"Toque","duracao":"Instantânea","componentes":"V, S","concentracao":false,"ritual":false,"classes":["Feiticeiro","Bruxo","Mago"],"teste":"Ataque de magia","dano":"1d10 necrótico","gatilho":"","texto":"Canalizando o frio da sepultura, faça uma jogada de ataque de magia corpo a corpo contra um alvo ao seu alcance. Se acertar, o alvo sofre 1d10 de dano necrótico e não pode recuperar Pontos de Vida até o final do seu próximo turno.","superior":"O dano aumenta em 1d10 quando você alcança os níveis 5 (2d10), 11 (3d10) e 17 (4d10)."},
  {"en":"Vampiric Touch","nome":"Toque vampírico","nivel":3,"escola":"Necromancia","tempo":"1 ação","alcance":"Pessoal","duracao":"Concentração, até 1 minuto","componentes":"V, S","concentracao":true,"ritual":false,"classes":["Feiticeiro","Bruxo","Mago"],"teste":"Ataque de magia","dano":"3d6 necrótico","gatilho":"","texto":"O toque da sua mão envolta em sombras pode sugar a força vital de outros para curar seus ferimentos. Faça uma jogada de ataque de magia corpo a corpo contra uma criatura ao seu alcance. Em um acerto, o alvo sofre 3d6 de dano necrótico, e você recupera Pontos de Vida iguais à metade do dano necrótico causado. Até a magia terminar, você pode repetir o ataque em cada um dos seus turnos com uma ação Magia, tendo como alvo a mesma criatura ou outra.","superior":"O dano aumenta em 1d6 para cada nível do espaço de magia acima de 3."},
  {"en":"Arcane Lock","nome":"Tranca arcana","nivel":2,"escola":"Abjuração","tempo":"1 ação","alcance":"Toque","duracao":"Até ser dissipada","componentes":"V, S, M (pó de ouro que valha 25+ PO, que a magia consome)","concentracao":false,"ritual":false,"classes":["Mago"],"teste":"","dano":"","gatilho":"","texto":"Você toca uma porta, janela, portão, recipiente ou escotilha fechados e os tranca magicamente pela duração. Essa tranca não pode ser destrancada por nenhum meio não mágico. Você e quaisquer criaturas que designar ao conjurar a magia podem abrir e fechar o objeto apesar da tranca. Você também pode definir uma senha que, quando dita a até 1,5 m do objeto, o destranca por 1 minuto.","superior":""},
  {"en":"Transport via Plants","nome":"Transporte via plantas","nivel":6,"escola":"Conjuração","tempo":"1 ação","alcance":"3 m","duracao":"1 minuto","componentes":"V, S","concentracao":false,"ritual":false,"classes":["Druida"],"teste":"","dano":"","gatilho":"","texto":"Esta magia cria uma ligação mágica entre uma planta inanimada de tamanho Grande ou maior ao alcance e outra planta, a qualquer distância, no mesmo plano de existência. Você deve ter visto ou tocado a planta de destino pelo menos uma vez antes. Pela duração, qualquer criatura pode entrar na planta alvo e sair pela planta de destino gastando 1,5 m de movimento.","superior":""},
  {"en":"Tree Stride","nome":"Tree Stride","nivel":5,"escola":"Conjuração","tempo":"1 ação","alcance":"Pessoal","duracao":"Concentração, até 1 minuto","componentes":"V, S","concentracao":true,"ritual":false,"classes":["Druida","Patrulheiro"],"teste":"","dano":"","gatilho":"","texto":"Você ganha a capacidade de entrar em uma árvore e se mover de dentro dela para dentro de outra árvore da mesma espécie a até 150 m. Ambas as árvores devem estar vivas e ser pelo menos do mesmo tamanho que você. Você deve gastar 1,5 m de movimento para entrar em uma árvore. Você sabe instantaneamente a localização de todas as outras árvores da mesma espécie a até 150 m e, como parte do movimento usado para entrar na árvore, pode passar para uma dessas árvores ou sair da árvore em que está. Você aparece em um ponto à sua escolha a até 1,5 m da árvore de destino, gastando outros 1,5 m de movimento. Se você não tiver movimento restante, aparece a até 1,5 m da árvore em que entrou. Você só pode usar essa capacidade de transporte uma vez em cada um dos seus turnos. Você deve terminar cada turno fora de uma árvore.","superior":""},
  {"en":"Rope Trick","nome":"Truque da corda","nivel":2,"escola":"Transmutação","tempo":"1 ação","alcance":"Toque","duracao":"1 hora","componentes":"V, S, M (um pedaço de corda)","concentracao":false,"ritual":false,"classes":["Mago"],"teste":"","dano":"","gatilho":"","texto":"Você toca uma corda. Uma das pontas dela flutua para cima até a corda ficar perpendicular ao chão ou até alcançar um teto. Na ponta superior da corda, um portal Invisível de 0,9 m por 1,5 m se abre para um espaço extradimensional que dura até a magia terminar. Esse espaço pode ser alcançado escalando a corda, que pode ser puxada para dentro dele ou largada para fora. O espaço comporta até oito criaturas Médias ou menores. Ataques, magias e outros efeitos não podem entrar nem sair do espaço, mas as criaturas dentro dele podem ver através do portal. Tudo que estiver dentro do espaço cai para fora quando a magia termina.","superior":""},
  {"en":"Tsunami","nome":"Tsunami","nivel":8,"escola":"Conjuração","tempo":"1 minuto","alcance":"1,5 km","duracao":"Concentração, até 6 rodadas","componentes":"V, S","concentracao":true,"ritual":false,"classes":["Druida"],"teste":"Salvaguarda de Força","dano":"6d10 contundente","gatilho":"","texto":"Uma parede de água surge em um ponto que você escolher ao alcance. Você pode fazer a parede ter até 90 m de comprimento, 90 m de altura e 15 m de espessura. A parede dura pela duração. Quando a parede aparece, cada criatura em sua área faz uma salvaguarda de Força, sofrendo 6d10 de dano contundente em caso de falha ou metade desse dano em caso de sucesso. No início de cada um dos seus turnos após a parede aparecer, a parede, junto com quaisquer criaturas dentro dela, se move 15 m para longe de você. Qualquer criatura de tamanho Enorme ou menor dentro da parede, ou em cujo espaço a parede entre ao se mover, deve ter sucesso em uma salvaguarda de Força ou sofrerá 5d10 de dano contundente. Uma criatura só pode sofrer esse dano uma vez por rodada. No final do turno, a altura da parede é reduzida em 15 m, e o dano que a parede causa nas rodadas seguintes é reduzido em 1d10. Quando a parede chega a 0 m de altura, a magia termina. Uma criatura presa na parede pode se mover nadando. Porém, devido à força da onda, a criatura deve ter sucesso em um teste de Força (Atletismo) contra a CD de salvaguarda das suas magias para se mover. Se falhar no teste, ela não pode se mover. Uma criatura que sai da parede cai no chão.","superior":""},
  {"en":"Haste","nome":"Velocidade","nivel":3,"escola":"Transmutação","tempo":"1 ação","alcance":"9 m","duracao":"Concentração, até 1 minuto","componentes":"V, S, M (uma lasca de raiz de alcaçuz)","concentracao":true,"ritual":false,"classes":["Feiticeiro","Mago"],"teste":"Salvaguarda de Destreza","dano":"","gatilho":"","texto":"Escolha uma criatura voluntária que você possa ver ao alcance. Até a magia terminar, o Deslocamento do alvo é dobrado, ele recebe +2 de bônus na Classe de Armadura, tem Vantagem em salvaguardas de Destreza e recebe uma ação adicional em cada um de seus turnos. Essa ação só pode ser usada para realizar as ações Atacar (apenas um ataque), Disparada, Desengajar, Esconder ou Utilizar. Quando a magia termina, o alvo fica Incapacitado e com Deslocamento 0 até o final do seu próximo turno, quando uma onda de letargia o invade.","superior":""},
  {"en":"See Invisibility","nome":"Ver o invisível","nivel":2,"escola":"Adivinhação","tempo":"1 ação","alcance":"Pessoal","duracao":"1 hora","componentes":"V, S, M (uma pitada de talco)","concentracao":false,"ritual":false,"classes":["Bardo","Feiticeiro","Mago"],"teste":"","dano":"","gatilho":"","texto":"Pela duração, você vê criaturas e objetos que tenham a condição Invisível como se fossem visíveis, e pode ver o Plano Etéreo. Criaturas e objetos ali parecem fantasmagóricos.","superior":""},
  {"en":"False Life","nome":"Vida falsa","nivel":1,"escola":"Necromancia","tempo":"1 ação","alcance":"Pessoal","duracao":"Instantânea","componentes":"V, S, M (uma gota de álcool)","concentracao":false,"ritual":false,"classes":["Feiticeiro","Mago"],"teste":"","dano":"2d4 + 4","gatilho":"","texto":"Você ganha 2d4 + 4 Pontos de Vida Temporários.","superior":"Você ganha 5 Pontos de Vida Temporários adicionais para cada nível do espaço de magia acima de 1."},
  {"en":"Scrying","nome":"Vidência","nivel":5,"escola":"Adivinhação","tempo":"1 minuto","alcance":"Pessoal","duracao":"Concentração, até 10 minutos","componentes":"V, S, M (um foco que valha 1.000+ PO, como uma bola de cristal, um espelho ou uma fonte cheia de água)","concentracao":true,"ritual":false,"classes":["Bardo","Clérigo","Druida","Bruxo","Mago"],"teste":"Salvaguarda de Sabedoria","dano":"","gatilho":"","texto":"Você pode ver e ouvir uma criatura de sua escolha que esteja no mesmo plano de existência que você. O alvo realiza uma salvaguarda de Sabedoria, modificada (veja as tabelas abaixo) pelo quanto você conhece o alvo e pelo tipo de conexão física que você tem com ele. O alvo não sabe contra o que está realizando a salvaguarda, apenas que se sente inquieto.\n\n| Seu Conhecimento do Alvo É … | Modificador da Salvaguarda |\n|---|---|\n| Indireto (ouviu falar do alvo) | +5 |\n| Direto (conheceu o alvo) | +0 |\n| Extenso (conhece bem o alvo) | −5 |\n\n| Você Tem do Alvo … | Modificador da Salvaguarda |\n|---|---|\n| Retrato ou outra semelhança | −2 |\n| Roupa ou outro pertence | −4 |\n| Parte do corpo, mecha de cabelo ou pedaço de unha | −10 |\n\nEm caso de sucesso na salvaguarda, o alvo não é afetado e você não pode usar esta magia nele novamente por 24 horas.\n\nEm caso de falha na salvaguarda, a magia cria um sensor Invisível e intangível a até 3 m do alvo. Você pode ver e ouvir através do sensor como se estivesse lá. O sensor se move com o alvo, permanecendo a até 3 m dele pela duração. Se algo puder ver o sensor, ele aparece como um orbe luminoso do tamanho aproximado de seu punho.\n\nEm vez de ter uma criatura como alvo, você pode ter como alvo um local que tenha visto. Quando fizer isso, o sensor aparece nesse local e não se move.","superior":""},
  {"en":"Planar Binding","nome":"Vínculo planar","nivel":5,"escola":"Abjuração","tempo":"1 hora","alcance":"18 m","duracao":"24 horas","componentes":"V, S, M (uma joia que valha 1.000+ PO, que a magia consome)","concentracao":false,"ritual":false,"classes":["Bardo","Clérigo","Druida","Bruxo","Mago"],"teste":"Salvaguarda de Carisma","dano":"","gatilho":"","texto":"Você tenta vincular um Celestial, um Elemental, um Feérico ou um Ínfero ao seu serviço. A criatura deve estar ao alcance durante toda a conjuração da magia. (Normalmente, a criatura é primeiro invocada para o centro da versão invertida da magia Círculo Mágico para aprisioná-la enquanto esta magia é conjurada.) Ao final da conjuração, o alvo deve ter sucesso em uma salvaguarda de Carisma ou ficará vinculado a servir você pela duração. Se a criatura foi invocada ou criada por outra magia, a duração dessa magia é estendida para igualar a duração desta magia. Uma criatura vinculada deve seguir seus comandos da melhor maneira possível. Você pode comandar a criatura a acompanhar você em uma aventura, guardar um local ou entregar uma mensagem. Se a criatura for Hostil, ela se esforça para distorcer seus comandos para alcançar seus próprios objetivos. Se a criatura cumprir seus comandos por completo antes de a magia acabar, ela viaja até você para relatar esse fato se você estiver no mesmo plano de existência. Se você estiver em um plano diferente, ela retorna ao lugar onde você a vinculou e permanece lá até a magia acabar.","superior":"A duração aumenta com um espaço de magia de nível 6 (10 dias), 7 (30 dias), 8 (180 dias) e 9 (366 dias)."},
  {"en":"Warding Bond","nome":"Vínculo protetor","nivel":2,"escola":"Abjuração","tempo":"1 ação","alcance":"Toque","duracao":"1 hora","componentes":"V, S, M (um par de anéis de platina que valham 50+ PO cada, os quais você e o alvo devem usar pela duração)","concentracao":false,"ritual":false,"classes":["Clérigo","Paladino"],"teste":"","dano":"","gatilho":"","texto":"Você toca outra criatura voluntária e cria uma conexão mística entre você e o alvo até a magia terminar. Enquanto o alvo estiver a até 18 m de você, ele ganha +1 de bônus na CA e nas salvaguardas e tem Resistência a todo dano. Além disso, cada vez que ele sofre dano, você sofre a mesma quantidade de dano. A magia termina se você cair a 0 Pontos de Vida ou se você e o alvo ficarem separados por mais de 18 m. Ela também termina se a magia for conjurada novamente em qualquer uma das criaturas conectadas.","superior":""},
  {"en":"Telepathic Bond","nome":"Vínculo telepático","nivel":5,"escola":"Adivinhação","tempo":"1 ação","alcance":"9 m","duracao":"1 hora","componentes":"V, S, M (dois ovos)","concentracao":false,"ritual":true,"classes":["Bardo","Mago"],"teste":"","dano":"","gatilho":"","texto":"Você forja um elo telepático entre até oito criaturas voluntárias à sua escolha ao alcance, ligando psiquicamente cada criatura a todas as outras pela duração. Criaturas que não se comunicam em nenhum idioma não são afetadas por esta magia. Até a magia terminar, os alvos podem se comunicar telepaticamente através do elo, compartilhem ou não um idioma. A comunicação é possível a qualquer distância, mas não pode se estender a outros planos de existência.","superior":""},
  {"en":"True Seeing","nome":"Visão da verdade","nivel":6,"escola":"Adivinhação","tempo":"1 ação","alcance":"Toque","duracao":"1 hora","componentes":"V, S, M (pó de cogumelo que valha 25+ PO, o qual a magia consome)","concentracao":false,"ritual":false,"classes":["Bardo","Clérigo","Feiticeiro","Bruxo","Mago"],"teste":"","dano":"","gatilho":"","texto":"Pela duração, a criatura voluntária que você tocar tem Visão Verdadeira com alcance de 36 m.","superior":""},
  {"en":"Darkvision","nome":"Visão no escuro","nivel":2,"escola":"Transmutação","tempo":"1 ação","alcance":"Toque","duracao":"8 horas","componentes":"V, S, M (uma cenoura seca)","concentracao":false,"ritual":false,"classes":["Druida","Patrulheiro","Feiticeiro","Mago"],"teste":"","dano":"","gatilho":"","texto":"Pela duração, uma criatura voluntária que você tocar tem Visão no Escuro com alcance de 45 m.","superior":""},
  {"en":"Fly","nome":"Voo","nivel":3,"escola":"Transmutação","tempo":"1 ação","alcance":"Toque","duracao":"Concentração, até 10 minutos","componentes":"V, S, M (uma pena)","concentracao":true,"ritual":false,"classes":["Feiticeiro","Bruxo","Mago"],"teste":"","dano":"","gatilho":"","texto":"Você toca uma criatura disposta. Pela duração, o alvo ganha Deslocamento de Voo de 18 m e pode pairar. Quando a magia acaba, o alvo cai se ainda estiver no ar, a menos que consiga interromper a queda.","superior":"Você pode escolher uma criatura adicional para cada nível do espaço de magia acima de 3."},
  {"en":"Weird","nome":"Weird","nivel":9,"escola":"Ilusão","tempo":"1 ação","alcance":"36 m","duracao":"Concentração, até 1 minuto","componentes":"V, S","concentracao":true,"ritual":false,"classes":["Bruxo","Mago"],"teste":"Salvaguarda de Sabedoria","dano":"10d10 psíquico","gatilho":"","texto":"Você tenta criar terrores ilusórios na mente dos outros. Cada criatura à sua escolha em uma Esfera de 9 m de raio centrada em um ponto ao alcance faz uma salvaguarda de Sabedoria. Em caso de falha, o alvo sofre 10d10 de dano psíquico e fica com a condição Amedrontado pela duração. Em caso de sucesso, o alvo sofre apenas metade do dano. Um alvo Amedrontado faz uma salvaguarda de Sabedoria no final de cada um dos seus turnos. Em caso de falha, ele sofre 5d10 de dano psíquico. Em caso de sucesso, a magia termina para esse alvo.","superior":""},
  {"en":"Vicious Mockery","nome":"Zombaria perversa","nivel":0,"escola":"Encantamento","tempo":"1 ação","alcance":"18 m","duracao":"Instantânea","componentes":"V","concentracao":false,"ritual":false,"classes":["Bardo"],"teste":"Ataque de magia + Salvaguarda de Sabedoria","dano":"1d6 psíquico","gatilho":"","texto":"Você lança uma sequência de insultos carregados de encantamentos sutis contra uma criatura que você possa ver ou ouvir ao alcance. O alvo deve ter sucesso em uma salvaguarda de Sabedoria ou sofrerá 1d6 de dano psíquico e terá Desvantagem na próxima jogada de ataque que fizer antes do final do seu próximo turno.","superior":"O dano aumenta em 1d6 quando você alcança os níveis 5 (2d6), 11 (3d6) e 17 (4d6)."},
  {"en":"Zone of Truth","nome":"Zona da verdade","nivel":2,"escola":"Encantamento","tempo":"1 ação","alcance":"18 m","duracao":"10 minutos","componentes":"V, S","concentracao":false,"ritual":false,"classes":["Bardo","Clérigo","Paladino"],"teste":"Salvaguarda de Carisma","dano":"","gatilho":"","texto":"Você cria uma zona mágica que protege contra o engano em uma Esfera de 4,5 m de raio centrada em um ponto ao alcance. Até a magia terminar, uma criatura que entre na área da magia pela primeira vez em um turno ou comece seu turno ali faz uma salvaguarda de Carisma. Se falhar, a criatura não pode proferir uma mentira deliberada enquanto estiver no raio. Você sabe se uma criatura tem sucesso ou falha nessa salvaguarda. Uma criatura afetada tem consciência da magia e pode evitar responder a perguntas que normalmente responderia com uma mentira. Essa criatura pode ser evasiva, mas deve ser verdadeira.","superior":""},
];
